// ─── German + French lesson section bodies (all 36 lessons) ──────────────────
// Parallel to the es/ru/mk body catalogs; arrays follow section order and are
// merged into BODY_TRANS (contentTranslations.ts). Built in era batches.
type L = 'de' | 'fr';

export const DEFR_BODY: Record<string, Partial<Record<L, string[]>>> = {
  'ancient-01': {
    de: [
      "Um 3500 v. Chr. errichteten die Sumerer im südlichen Mesopotamien — dem Land zwischen Euphrat und Tigris im heutigen Irak — die ersten Städte der Welt. Uruk, die größte, beherbergte womöglich 50.000 Menschen. Um Getreideüberschüsse und Tempelkonten zu verwalten, erfanden sumerische Schreiber um 3100 v. Chr. die Keilschrift, indem sie keilförmige Zeichen in Tontafeln drückten.\n\nDiese Schrift verbreitete sich über den Nahen Osten und blieb mehr als 3.000 Jahre die vorherrschende Schrift. Die mesopotamischen Stadtstaaten entwickelten zudem Bronzewerkzeuge, das Rad und ausgeklügelte Bewässerungskanäle, die Wüste in Ackerland verwandelten.",
      "Ägyptens Zivilisation entstand am Nil etwa zur selben Zeit wie Sumer. Die jährliche Nilflut lagerte fruchtbaren Schlamm ab und machte Ägypten zu einer der fruchtbarsten Regionen der Antike. Um 3100 v. Chr. unter Pharao Narmer geeint, bildete Ägypten einen starken Zentralstaat unter göttlichen Königen.\n\nWährend des Alten Reiches (ca. 2686–2181 v. Chr.) ließen die Pharaonen die großen Pyramiden von Giza errichten — Ingenieurleistungen, die bis heute ehrfurchtgebietend sind. Ägyptische Hieroglyphen, Mathematik und Medizin zählten zu den fortschrittlichsten der Antike.",
      "Der babylonische König Hammurabi (reg. 1792–1750 v. Chr.) einte Mesopotamien und erließ einen der frühesten schriftlichen Gesetzestexte der Welt. Der Kodex Hammurabi legte Strafen für Verbrechen fest und regelte den Handel und spiegelte eine auf Handel und Rechtsordnung gebaute Gesellschaft wider.\n\nSowohl Ägypten als auch Mesopotamien unterhielten weitreichende Handelsnetze. Ägyptisches Gold und Getreide flossen in die Levante; mesopotamische Kaufleute handelten mit dem Indus-Tal. Diese frühen Zivilisationen schufen die Blaupause für organisierte Regierung, Religion, Landwirtschaft und Stadtleben, auf der alle späteren Gesellschaften aufbauen sollten.",
      "Religion war in beiden Zivilisationen untrennbar mit politischer Macht verbunden. Die Sumerer verehrten ein Pantheon von Göttern, die Naturgewalten beherrschten — Stürme, Fluten, Fruchtbarkeit — und errichteten hoch aufragende Zikkurats als Tempel zu ihren Ehren. Priester besaßen enormen Einfluss, verwalteten Tempelländereien und beaufsichtigten riesige Kornspeicher. Die wichtigste Gottheit, Enlil, galt als König der Götter, dessen Gunst über das Schicksal einer Stadt entschied.\n\nDie ägyptische Religion kreiste um das Jenseits und die kosmische Ordnung (Maat). Pharaonen galten als lebende Götter — Verkörperungen des Horus im Leben und des Osiris im Tod. Der aufwendige Prozess der Mumifizierung und der Bau von Pyramidengräbern sollten den Leib des Pharaos für das ewige Leben bewahren. Diese religiösen Systeme gaben den Menschen Sinn, legitimierten politische Autorität und trieben architektonische Leistungen von atemberaubendem Ehrgeiz an.",
      "Unter ihrem religiösen Weltbild machten mesopotamische und ägyptische Gelehrte erstaunliche praktische Fortschritte. Babylonische Mathematiker entwickelten ein Zahlensystem zur Basis 60 — Ursprung unserer 60-Minuten-Stunde und des 360-Grad-Kreises. Sie lösten quadratische Gleichungen und verfolgten über Jahrhunderte mit peinlicher Genauigkeit die Bewegungen der Planeten.\n\nDie ägyptische Medizin war ebenso beeindruckend. Der Papyrus Edwin Smith (ca. 1600 v. Chr.) beschreibt chirurgische Behandlungen mit klinischer Beobachtung und erkennt, dass Hirnverletzungen bestimmte Lähmungen verursachen. Ägyptische Ärzte verstanden die Anatomie durch die Mumifizierung und entwickelten Behandlungen für Knochenbrüche und Infektionen. Dieser Bestand an praktischem Wissen, wenn auch mit magischen Heilmitteln vermengt, legte das Fundament für die spätere griechische Medizin und letztlich für die moderne Wissenschaft.",
    ],
    fr: [
      "Vers 3500 av. J.-C., les Sumériens du sud de la Mésopotamie — la terre entre le Tigre et l'Euphrate dans l'Irak actuel — bâtirent les premières villes du monde. Uruk, la plus grande, comptait peut-être 50 000 habitants. Pour gérer les surplus de grain et les comptes des temples, les scribes sumériens inventèrent l'écriture cunéiforme vers 3100 av. J.-C., imprimant des signes en coin dans des tablettes d'argile.\n\nCette écriture se répandit à travers le Proche-Orient et resta l'écriture dominante pendant plus de 3 000 ans. Les cités-États mésopotamiennes développèrent aussi des outils de bronze, la roue et des canaux d'irrigation sophistiqués qui transformèrent le désert en terres cultivées.",
      "La civilisation égyptienne naquit le long du Nil à peu près en même temps que Sumer. La crue annuelle du Nil déposait un limon fertile, faisant de l'Égypte l'une des régions les plus fécondes du monde antique. Unifiée sous le pharaon Narmer vers 3100 av. J.-C., l'Égypte forma un État centralisé fort dirigé par des rois-dieux.\n\nSous l'Ancien Empire (v. 2686–2181 av. J.-C.), les pharaons firent bâtir les grandes pyramides de Gizeh — prouesses d'ingénierie qui émerveillent encore aujourd'hui. Les hiéroglyphes, les mathématiques et la médecine égyptiens comptaient parmi les plus avancés de l'Antiquité.",
      "Le roi babylonien Hammurabi (r. 1792–1750 av. J.-C.) unifia la Mésopotamie et promulgua l'un des plus anciens codes de lois écrits du monde. Le Code de Hammurabi fixait des peines pour les crimes et réglementait le commerce, reflétant une société fondée sur l'échange et l'ordre juridique.\n\nL'Égypte comme la Mésopotamie entretenaient de vastes réseaux commerciaux. L'or et le grain égyptiens gagnaient le Levant ; les marchands mésopotamiens commerçaient avec la vallée de l'Indus. Ces premières civilisations établirent le modèle du gouvernement organisé, de la religion, de l'agriculture et de la vie urbaine sur lequel toutes les sociétés ultérieures bâtiraient.",
      "La religion était indissociable du pouvoir politique dans les deux civilisations. Les Sumériens vénéraient un panthéon de dieux maîtrisant les forces naturelles — tempêtes, crues, fécondité — et élevaient d'imposantes ziggourats en guise de temples. Les prêtres exerçaient une influence énorme, administrant les terres des temples et surveillant de vastes greniers. La divinité principale, Enlil, était vue comme le roi des dieux dont la faveur décidait du sort d'une cité.\n\nLa religion égyptienne était centrée sur l'au-delà et l'ordre cosmique (Maât). Les pharaons étaient tenus pour des dieux vivants — incarnations d'Horus dans la vie et d'Osiris dans la mort. Le processus élaboré de momification et la construction de tombes pyramidales visaient à préserver le corps du pharaon pour la vie éternelle. Ces systèmes religieux donnaient un sens aux gens, légitimaient l'autorité politique et suscitaient des réalisations architecturales d'une ambition vertigineuse.",
      "Sous leur vision religieuse du monde, les savants mésopotamiens et égyptiens firent d'étonnants progrès pratiques. Les mathématiciens babyloniens élaborèrent un système numérique en base 60 — source de notre heure de 60 minutes et du cercle de 360 degrés. Ils résolvaient des équations quadratiques et suivaient les mouvements planétaires sur des siècles avec une précision méticuleuse.\n\nLa médecine égyptienne était tout aussi remarquable. Le papyrus Edwin Smith (v. 1600 av. J.-C.) décrit des traitements chirurgicaux avec observation clinique, reconnaissant que les lésions cérébrales causent des paralysies précises. Les médecins égyptiens comprenaient l'anatomie par la momification et développèrent des traitements pour les fractures et les infections. Ce corpus de savoir pratique, quoique mêlé de remèdes magiques, posa les bases de la médecine grecque ultérieure et, à terme, de la science moderne.",
    ],
  },
  'ancient-02': {
    de: [
      "Das antike Griechenland war keine geeinte Nation, sondern eine Ansammlung unabhängiger Stadtstaaten (Poleis) mit je eigener Regierung und Kultur. Athen und Sparta waren die mächtigsten. Sparta entwickelte eine militaristische Gesellschaft; jeder männliche Bürger wurde ab dem siebten Lebensjahr zum Soldaten ausgebildet. Athen dagegen wurde zum Zentrum von Kunst, Philosophie und politischer Neuerung.\n\nUm 508 v. Chr. führte der athenische Reformer Kleisthenes die Demokratia ein — die Herrschaft des Volkes, die erste demokratische Regierung der Welt. Bürger (freie erwachsene Männer) stimmten in der Volksversammlung unmittelbar über Gesetze und Politik ab — eine revolutionäre Idee, die alle künftigen Demokratien prägen sollte.",
      "Als das Perserreich 490 v. Chr. in Griechenland einfiel, schlugen die Athener es bei Marathon. Eine zweite persische Invasion 480 v. Chr. erlebte den legendären Stand der Spartaner bei den Thermopylen, ehe die Athener die persische Flotte bei Salamis vernichteten.\n\nDer Sieg über Persien führte Athen auf den Gipfel seiner Macht. Der athenische Staatsmann Perikles nutzte Tributgelder, um auf der Akropolis den Parthenon zu errichten, ein Meisterwerk klassischer Architektur. Doch die Rivalität zwischen Athen und Sparta entlud sich im verheerenden Peloponnesischen Krieg (431–404 v. Chr.), der beide Mächte erschöpfte.",
      "Das klassische Athen brachte einige der größten Denker der Geschichte hervor. Sokrates lehrte durch Fragen und forderte die Athener heraus, ihre Überzeugungen zu prüfen. Seine Methode — die sokratische Methode — steht bis heute im Zentrum der Bildung. Sokrates wurde 399 v. Chr. wegen „Verderbung der Jugend“ zum Tode verurteilt.\n\nSein Schüler Platon verfasste Dialoge über Gerechtigkeit, Schönheit und den idealen Staat. Platons Schüler Aristoteles systematisierte Logik, Biologie, Ethik und Politik — ein Bestand an Methode und Wissen, den europäische Universitäten noch zweitausend Jahre später lehren sollten.",
      "Griechische Kunst und Architektur strebten nach idealer Schönheit und Proportion. Der Parthenon auf der Athener Akropolis — zwischen 447 und 432 v. Chr. unter der Aufsicht des Bildhauers Phidias errichtet — verkörpert dieses Streben. Seine Säulen wölben sich in der Mitte leicht nach außen, um optische Täuschungen auszugleichen und den Eindruck vollkommener Geradheit zu erzeugen. Griechische Bildhauer wie Myron und Praxiteles stellten den menschlichen Körper in idealisierten, naturnahen Posen dar und übertrafen die starre Frontalität früherer Stile bei weitem.\n\nDie 776 v. Chr. in Olympia zu Ehren des Zeus gegründeten Olympischen Spiele versammelten alle vier Jahre Athleten aus der ganzen griechischen Welt. Während der Spiele ruhten die Kriege unter einem heiligen Gottesfrieden. Zu den Wettkämpfen zählten Lauf, Ringen, Diskuswurf, Wagenrennen und der Fünfkampf. Olympiasieger gewannen nur einen Olivenkranz — wurden aber in ihren Heimatstädten als Helden gefeiert und in Siegesoden von Dichtern wie Pindar verewigt. Die Spiele verkörperten das griechische Ideal der Arete: Vortrefflichkeit, Tugend und Wettstreit.",
      "Im späten vierten Jahrhundert v. Chr. trugen makedonische Eroberungen griechische Sprache, Kultur und Einrichtungen über einen weiten Teil der antiken Welt — von Ägypten bis Baktrien (das heutige Afghanistan). Diese „hellenistische“ Welt erhielt prächtige Städte: Alexandria in Ägypten mit seiner legendären Bibliothek von vielleicht 500.000 Schriftrollen; Antiochia in Syrien; Pergamon in Anatolien. Diese kosmopolitischen Zentren verschmolzen griechische, persische, ägyptische und indische Traditionen.\n\nHellenistische Gelehrte machten spektakuläre Fortschritte. Eratosthenes berechnete den Erdumfang mit erstaunlicher Genauigkeit anhand von Schatten und Geometrie. Euklid systematisierte die Geometrie; Archimedes berechnete Pi und entdeckte die Prinzipien von Auftrieb und Hebel. Aristarch schlug gar vor, dass die Erde die Sonne umkreise — siebzehn Jahrhunderte vor Kopernikus. Als Rom schließlich die hellenistischen Königreiche einverleibte, bewahrte und übermittelte es dieses geistige Erbe und machte das klassische Griechenland zum Quell der westlichen Zivilisation.",
    ],
    fr: [
      "La Grèce antique n'était pas une nation unifiée mais un ensemble de cités-États (poleis) indépendantes, chacune avec son gouvernement et sa culture. Athènes et Sparte étaient les plus puissantes. Sparte développa une société militariste ; tout citoyen mâle était formé au métier des armes dès l'âge de sept ans. Athènes, en revanche, devint un centre d'art, de philosophie et d'innovation politique.\n\nVers 508 av. J.-C., le réformateur athénien Clisthène instaura la démokratia — le gouvernement du peuple, la première démocratie du monde. Les citoyens (hommes adultes libres) votaient directement les lois à l'Assemblée, une idée révolutionnaire qui influencerait toutes les démocraties à venir.",
      "Lorsque l'Empire perse envahit la Grèce en 490 av. J.-C., les Athéniens le battirent à Marathon. Une seconde invasion perse en 480 av. J.-C. vit la résistance légendaire des Spartiates aux Thermopyles avant que les Athéniens ne détruisent la flotte perse à Salamine.\n\nLa victoire sur la Perse porta Athènes au faîte de sa puissance. Le dirigeant athénien Périclès employa l'argent du tribut pour bâtir le Parthénon sur l'Acropole, chef-d'œuvre de l'architecture classique. Mais la rivalité entre Athènes et Sparte éclata dans la dévastatrice guerre du Péloponnèse (431–404 av. J.-C.), qui épuisa les deux puissances.",
      "L'Athènes classique produisit quelques-uns des plus grands penseurs de l'histoire. Socrate enseignait par le questionnement, poussant les Athéniens à examiner leurs croyances. Sa méthode — la maïeutique — reste au cœur de l'éducation. Socrate fut condamné à mort en 399 av. J.-C. pour « corruption de la jeunesse ».\n\nSon élève Platon écrivit des dialogues sur la justice, la beauté et l'État idéal. L'élève de Platon, Aristote, systématisa la logique, la biologie, l'éthique et la politique — un corpus de méthode et de savoir que les universités européennes enseigneraient encore deux mille ans plus tard.",
      "L'art et l'architecture grecs traduisaient une quête de la beauté et de la proportion idéales. Le Parthénon, au sommet de l'Acropole d'Athènes — bâti entre 447 et 432 av. J.-C. sous la direction du sculpteur Phidias — en est l'exemple parfait. Ses colonnes se renflent légèrement au milieu pour corriger les illusions d'optique, créant l'impression d'une parfaite rectitude. Des sculpteurs comme Myron et Praxitèle représentèrent le corps humain dans des poses idéalisées et naturelles, dépassant de loin la frontalité rigide des styles antérieurs.\n\nLes Jeux olympiques, fondés en 776 av. J.-C. à Olympie en l'honneur de Zeus, réunissaient tous les quatre ans des athlètes de tout le monde grec. Pendant les Jeux, les guerres étaient suspendues par une trêve sacrée. Les épreuves comprenaient la course, la lutte, le lancer du disque, la course de chars et le pentathlon. Les vainqueurs ne gagnaient qu'une couronne d'olivier — mais étaient célébrés comme des héros dans leur cité et immortalisés dans des odes par des poètes comme Pindare. Les Jeux incarnaient l'idéal grec de l'arétè : l'excellence, la vertu et l'émulation.",
      "À la fin du IVe siècle av. J.-C., les conquêtes macédoniennes portèrent la langue, la culture et les institutions grecques à travers une vaste part du monde antique — de l'Égypte à la Bactriane (l'Afghanistan actuel). Ce monde « hellénistique » abritait de magnifiques cités : Alexandrie en Égypte, avec sa légendaire bibliothèque de peut-être 500 000 rouleaux ; Antioche en Syrie ; Pergame en Anatolie. Ces centres cosmopolites mêlaient traditions grecque, perse, égyptienne et indienne.\n\nLes savants hellénistiques firent des progrès spectaculaires. Ératosthène calcula la circonférence de la Terre avec une précision remarquable à l'aide d'ombres et de géométrie. Euclide systématisa la géométrie ; Archimède calcula pi et découvrit les principes de la flottaison et du levier. Aristarque proposa même que la Terre tourne autour du Soleil — dix-sept siècles avant Copernic. Quand Rome absorba enfin les royaumes hellénistiques, elle préserva et transmit cet héritage intellectuel, faisant de la Grèce classique la source de la civilisation occidentale.",
    ],
  },
  'ancient-03': {
    de: [
      "Der Überlieferung nach wurde Rom 753 v. Chr. auf sieben Hügeln am Tiber gegründet. Nach der Vertreibung seiner Könige um 509 v. Chr. wurde Rom eine Republik, regiert von gewählten Konsuln und einem Senat aus Aristokraten. Mit der Zeit erlangten die Plebejer durch die Zwölftafelgesetze — Roms erstes schriftliches Recht — größere Rechte.\n\nRom dehnte sich stetig über Italien aus und besiegte seine Rivalen durch militärische Disziplin und geschickte Diplomatie. Um 264 v. Chr. beherrschte Rom die italische Halbinsel und richtete seinen Blick auf die weitere Mittelmeerwelt.",
      "Roms Zusammenstoß mit Karthago führte zu den drei Punischen Kriegen (264–146 v. Chr.). Der karthagische Feldherr Hannibal überquerte berühmt mit Kriegselefanten die Alpen und vernichtete 216 v. Chr. bei Cannae römische Heere. Doch Roms Widerstandskraft siegte; Karthago wurde 146 v. Chr. endgültig zerstört.\n\nDie römische Eroberung brachte großen Reichtum, aber auch soziale Spannungen. Feldherren wie Marius und Sulla befehligten persönliche, ihnen statt dem Senat ergebene Heere. Julius Cäsars militärisches Genie in Gallien machte ihn zum mächtigsten Mann Roms — bis zu seiner Ermordung an den Iden des März 44 v. Chr.",
      "Cäsars Erbe Octavian besiegte seine Rivalen und wurde 27 v. Chr. als Augustus der erste Kaiser Roms. Das augusteische Zeitalter läutete die Pax Romana ein — zwei Jahrhunderte relativer Stabilität, Wohlstand und kultureller Blüte. Das römische Straßennetz, die Aquädukte und das Rechtssystem einten ein riesiges Reich von Britannien bis Mesopotamien.\n\nAuf seinem Höhepunkt unter Kaiser Trajan umfasste Roms Reich 5 Millionen Quadratkilometer und vielleicht 70 Millionen Menschen. Doch Überdehnung, wirtschaftliche Not und militärischer Druck germanischer Stämme schwächten das Reich allmählich. 476 n. Chr. wurde der letzte weströmische Kaiser abgesetzt.",
      "Die römische Zivilisation war ebenso sehr eine Ingenieurs- wie eine politische Leistung. Die Römer bauten über 80.000 km Straßen aus gefügten Steinen. Sie erfanden den Beton, der den Bau der unbewehrten Kuppel des Pantheons — noch nach 2.000 Jahren die größte der Welt —, gewaltiger Aquädukte, die Frischwasser über Hunderte Kilometer führten, und des Kolosseums mit 80.000 Plätzen ermöglichte.\n\nDer römische Alltag ist erstaunlich vertraut. Stadtrömer lebten in mehrstöckigen Mietshäusern (insulae), kauften bei Bäckereien und Tavernen ein, besuchten öffentliche Bäder (thermae) zur Geselligkeit und wohnten Gladiatorenspielen und Wagenrennen bei. Das römische Recht, in Kaiser Justinians Corpus Juris Civilis (529 n. Chr.) systematisiert, bildet bis heute die Grundlage der Rechtssysteme in ganz Europa und Lateinamerika.",
      "Unter der Herrschaft des Augustus wurde in der römischen Provinz Judäa ein jüdischer Lehrer namens Jesus von Nazareth geboren. Um 30 n. Chr. unter dem römischen Statthalter Pontius Pilatus gekreuzigt, glaubten seine Anhänger, er sei von den Toten auferstanden. Das Christentum breitete sich rasch entlang der römischen Straßen aus und sprach besonders Sklaven, Frauen und Arme mit seiner Botschaft von Gleichheit und geistiger Erlösung an. Um 300 n. Chr. war vielleicht ein Zehntel des Reiches christlich.\n\n313 n. Chr. erließ Kaiser Konstantin das Mailänder Edikt und legalisierte das Christentum. Um 380 n. Chr. war es Staatsreligion. Die Annahme des Christentums verwandelte das Reich und die gesamte westliche Geschichte — sie prägte Bildung, Kunst, Philosophie und Recht. Als das Weströmische Reich im 5. Jahrhundert fiel, überdauerte die Kirche als wichtigste institutionelle Kontinuität zwischen antiker und mittelalterlicher Welt, bewahrte die lateinische Schriftkultur und gab Roms angesammelte Weisheit an künftige Generationen weiter.",
    ],
    fr: [
      "Selon la tradition, Rome fut fondée en 753 av. J.-C. sur sept collines au bord du Tibre. Après avoir chassé ses rois vers 509 av. J.-C., Rome devint une république gouvernée par des consuls élus et un Sénat d'aristocrates. Avec le temps, les plébéiens gagnèrent des droits grâce à la Loi des Douze Tables — le premier code écrit de Rome.\n\nRome s'étendit régulièrement à travers l'Italie, battant ses rivaux par la discipline militaire et une habile diplomatie. Vers 264 av. J.-C., Rome contrôlait la péninsule italienne et tournait son regard vers l'ensemble du monde méditerranéen.",
      "L'affrontement de Rome avec Carthage engendra les trois guerres puniques (264–146 av. J.-C.). Le général carthaginois Hannibal franchit fameusement les Alpes avec des éléphants de guerre et écrasa les armées romaines à Cannes en 216 av. J.-C. Pourtant la ténacité de Rome l'emporta ; Carthage fut finalement détruite en 146 av. J.-C.\n\nLa conquête romaine apporta de grandes richesses mais aussi des tensions sociales. Des généraux comme Marius et Sylla commandaient des armées personnelles loyales à eux plutôt qu'au Sénat. Le génie militaire de Jules César en Gaule fit de lui l'homme le plus puissant de Rome — jusqu'à son assassinat aux ides de mars 44 av. J.-C.",
      "L'héritier de César, Octave, vainquit ses rivaux et devint le premier empereur de Rome sous le nom d'Auguste en 27 av. J.-C. L'âge augustéen inaugura la Pax Romana — deux siècles de stabilité, de prospérité et de floraison culturelle relatives. Le réseau routier romain, les aqueducs et le système juridique unifièrent un vaste empire de la Bretagne à la Mésopotamie.\n\nÀ son apogée sous l'empereur Trajan, l'empire de Rome couvrait 5 millions de kilomètres carrés et comptait peut-être 70 millions d'habitants. Mais l'expansion excessive, les tensions économiques et la pression militaire des tribus germaniques affaiblirent peu à peu l'empire. En 476, le dernier empereur romain d'Occident fut déposé.",
      "La civilisation romaine fut autant une prouesse d'ingénierie que de politique. Les Romains construisirent plus de 80 000 km de routes pavées de pierres ajustées. Ils inventèrent le béton, permettant l'édification du dôme sans armature du Panthéon — encore le plus grand du monde après 2 000 ans —, de vastes aqueducs acheminant l'eau sur des centaines de kilomètres, et du Colisée pouvant accueillir 80 000 spectateurs.\n\nLa vie quotidienne romaine est étonnamment familière. Les citadins vivaient dans des immeubles à plusieurs étages (insulae), s'approvisionnaient aux boulangeries et tavernes, fréquentaient les bains publics (thermae) pour se retrouver, et assistaient aux jeux de gladiateurs et aux courses de chars. Le droit romain, systématisé dans le Corpus Juris Civilis de l'empereur Justinien (529), reste le fondement des systèmes juridiques d'Europe et d'Amérique latine à ce jour.",
      "Sous le règne d'Auguste, un maître juif nommé Jésus de Nazareth naquit dans la Judée romaine. Crucifié sous le gouverneur romain Ponce Pilate vers l'an 30, ses disciples crurent qu'il était ressuscité des morts. Le christianisme se répandit rapidement le long des routes romaines, séduisant surtout esclaves, femmes et pauvres par son message d'égalité et de rédemption spirituelle. Vers 300, peut-être 10% de l'empire était chrétien.\n\nEn 313, l'empereur Constantin promulgua l'édit de Milan, légalisant le christianisme. En 380, il était religion officielle. L'adoption du christianisme transforma l'empire et toute l'histoire occidentale — façonnant l'éducation, l'art, la philosophie et le droit. À la chute de l'Empire d'Occident au Ve siècle, l'Église survécut comme principale continuité institutionnelle entre le monde antique et le monde médiéval, préservant la culture écrite latine et transmettant la sagesse accumulée de Rome aux générations futures.",
    ],
  },
  'ancient-04': {
    de: [
      "Unter Kyros dem Großen (reg. 550–530 v. Chr.) bauten die achämenidischen Perser das größte Reich der Antike, das von Anatolien bis zum Indus-Tal reichte. Anders als viele antike Eroberer war Kyros für religiöse Toleranz bekannt — er erlaubte den jüdischen Verbannten in Babylon die Rückkehr in ihre Heimat.\n\nDareios I. gliederte das Reich in Provinzen (Satrapien) und baute die Königsstraße, die sich 2.700 km von Sardes bis Susa erstreckte und rasche Kommunikation ermöglichte. Die persische Kultur — die zoroastrische Religion, die monumentale Architektur von Persepolis und eine ausgefeilte Verwaltung — prägte alle späteren nahöstlichen Zivilisationen tief.",
      "Indiens Maurya-Reich (322–185 v. Chr.), gegründet von Chandragupta Maurya, einte als erstes den Großteil des indischen Subkontinents. Sein Enkel Ashoka (reg. 268–232 v. Chr.) wurde einer der bemerkenswertesten Herrscher der Geschichte. Nach der brutalen Eroberung von Kalinga bekehrte sich Ashoka zum Buddhismus und regierte nach dem Dharma (der sittlichen Pflicht).\n\nAshokas Felsedikte förderten Toleranz, Gewaltlosigkeit und Fürsorge. Er sandte buddhistische Missionare nach Sri Lanka, Zentralasien und Griechenland und trug so zur Verbreitung des Buddhismus in Asien bei. Die indische Mathematik — insbesondere das Konzept der Null und das Dezimalsystem — sollte später über arabische Gelehrte die Welt verwandeln.",
      "Chinas Han-Dynastie (206 v. Chr.–220 n. Chr.) beherrschte eine der ausgefeiltesten Zivilisationen der Antike. Kaiser Wu dehnte das Reich nach Zentralasien aus und begründete die Seidenstraße — Handelswege, die China mit Rom verbanden. Seide, Gewürze und Ideen flossen in beide Richtungen entlang dieser Routen.\n\nDas Han-China entwickelte Papier, den Seismographen und Gusseisen. Die konfuzianische Ethik prägte die Regierung; das Beamtenprüfungssystem — das Beamte nach Verdienst zuließ — war ein revolutionäres Konzept. Als die Han-Dynastie 220 n. Chr. fiel, zersplitterte China, doch das Han-Modell einheitlicher Reichsherrschaft blieb das Ideal aller folgenden chinesischen Dynastien.",
      "Um 1500 v. Chr. wanderten indogermanische Völker, die Arier, ins nördliche Indien ein und brachten das Sanskrit und eine komplexe polytheistische Religion mit. Die Veden — zu den ältesten heiligen Texten der Welt zählend — entstanden in dieser Zeit: Hymnen an Götter wie Indra (Krieg), Varuna (kosmische Ordnung) und Agni (Feuer). Über Jahrhunderte entwickelte sich diese vedische Religion zum Hinduismus, nahm lokale Traditionen auf und brachte reiche philosophische Schulen hervor.\n\nDie hinduistische Philosophie brachte die Upanishaden hervor — tiefgründige metaphysische Texte über das Wesen des Selbst (Atman) und die letzte Wirklichkeit (Brahman). Die Begriffe Dharma (sittliche Pflicht), Karma (Tat und Folge) und Samsara (der Kreislauf der Wiedergeburt) boten einen umfassenden Rahmen für Ethik und Kosmologie. Die Epen Mahabharata und Ramayana verankerten hinduistische Werte für Millionen in ganz Asien und bleiben bis heute lebendige kulturelle Bezugspunkte.",
      "Die Zeit der Streitenden Reiche in China (475–221 v. Chr.) war paradoxerweise eine ihrer geistig schöpferischsten Epochen. Konfuzius (551–479 v. Chr.) lehrte, dass gesellschaftliche Harmonie auf rechten Beziehungen beruhe — zwischen Herrscher und Untertan, Eltern und Kind —, geordnet durch Ritus (li), Menschlichkeit (ren) und Rechtschaffenheit (yi). Der Konfuzianismus wurde über 2.000 Jahre Chinas vorherrschende politische Philosophie.\n\nLaozi bot im Tao Te King eine gegensätzliche Sicht: Der Weg (Tao) sei eine unaussprechliche natürliche Ordnung; gute Regierung bedeute geringstes Eingreifen. Der Taoismus prägte Chinas Kunst, Medizin und Spiritualität zutiefst. Der Legalismus vertrat das Gegenteil — Han Feizi argumentierte, Herrscher sollten mit strengen Gesetzen und harten Strafen die Gesellschaft lenken. Die Qin-Dynastie einte China 221 v. Chr. nach legalistischen Grundsätzen unter dem ersten Kaiser Qin Shihuangdi, der die Große Mauer und ein Heer aus Terrakotta-Kriegern zum Schutz seines prächtigen Grabes errichten ließ.",
    ],
    fr: [
      "Sous Cyrus le Grand (r. 550–530 av. J.-C.), les Perses achéménides bâtirent le plus grand empire de l'Antiquité, s'étendant de l'Anatolie à la vallée de l'Indus. Contrairement à bien des conquérants antiques, Cyrus était réputé pour sa tolérance religieuse — il autorisa les exilés juifs de Babylone à regagner leur patrie.\n\nDarius Ier organisa l'empire en provinces (satrapies) et bâtit la Route royale longue de 2 700 km, de Sardes à Suse, permettant une communication rapide. La culture perse — le zoroastrisme, l'architecture monumentale de Persépolis et une administration sophistiquée — influença profondément toutes les civilisations ultérieures du Proche-Orient.",
      "L'Empire maurya de l'Inde (322–185 av. J.-C.), fondé par Chandragupta Maurya, fut le premier à unifier l'essentiel du sous-continent indien. Son petit-fils Ashoka (r. 268–232 av. J.-C.) devint l'un des souverains les plus remarquables de l'histoire. Après la brutale conquête du Kalinga, Ashoka se convertit au bouddhisme et gouverna selon le dharma (le devoir moral).\n\nLes édits sur roche d'Ashoka prônaient la tolérance, la non-violence et le bien-être. Il envoya des missionnaires bouddhistes au Sri Lanka, en Asie centrale et en Grèce, contribuant à répandre le bouddhisme à travers l'Asie. Les mathématiques indiennes — en particulier le concept du zéro et le système décimal — transformeraient plus tard le monde par l'intermédiaire des savants arabes.",
      "La dynastie Han de Chine (206 av. J.-C.–220 ap. J.-C.) régna sur l'une des civilisations les plus raffinées de l'Antiquité. L'empereur Wu étendit l'empire jusqu'en Asie centrale et établit la route de la Soie — des voies reliant la Chine à Rome. Soie, épices et idées circulaient dans les deux sens le long de ces routes.\n\nLa Chine des Han inventa le papier, le sismographe et la fonte. L'éthique confucéenne façonna le gouvernement ; le système des examens mandarinaux — admettant les fonctionnaires au mérite — était une idée révolutionnaire. À la chute des Han en 220, la Chine se morcela, mais le modèle Han d'un empire unifié demeura l'idéal de toutes les dynasties chinoises suivantes.",
      "Vers 1500 av. J.-C., des peuples indo-européens appelés Aryens migrèrent vers le nord de l'Inde, apportant le sanskrit et une religion polythéiste complexe. Les Védas — parmi les plus anciens textes sacrés du monde — furent composés à cette époque : hymnes à des dieux comme Indra (guerre), Varuna (ordre cosmique) et Agni (feu). Au fil des siècles, cette religion védique évolua en hindouisme, intégrant des traditions locales et développant de riches écoles philosophiques.\n\nLa philosophie hindoue produisit les Upanishads — textes métaphysiques profonds explorant la nature du soi (Atman) et de la réalité ultime (Brahman). Les concepts de dharma (devoir moral), de karma (action et conséquence) et de samsara (le cycle des renaissances) offraient un cadre complet d'éthique et de cosmologie. Les poèmes épiques du Mahabharata et du Ramayana ancrèrent les valeurs hindoues pour des millions de gens à travers l'Asie et demeurent des références culturelles vivantes.",
      "L'ère des Royaumes combattants en Chine (475–221 av. J.-C.) fut paradoxalement l'une de ses périodes les plus créatives sur le plan intellectuel. Confucius (551–479 av. J.-C.) soutenait que l'harmonie sociale reposait sur des relations justes — entre souverain et sujet, parent et enfant — régies par le rite (li), la bienveillance (ren) et la droiture (yi). Le confucianisme devint la philosophie politique dominante de la Chine pendant plus de 2 000 ans.\n\nLaozi offrit une vision contraire dans le Tao Tö King : la Voie (Tao) était un ordre naturel ineffable ; bien gouverner, c'était intervenir le moins possible. Le taoisme façonna profondément l'art, la médecine et la spiritualité chinois. Le légisme prit le parti inverse — Han Feizi soutenait que les souverains devaient recourir à des lois strictes et à des châtiments sévères. La dynastie Qin unifia la Chine en 221 av. J.-C. selon les principes légistes sous le premier empereur, Qin Shi Huang, qui édifia la Grande Muraille et une armée de soldats en terre cuite pour garder son tombeau spectaculaire.",
    ],
  },
  'ancient-05': {
    de: [
      "Im alten Ägypten waren Politik und Religion eins. Der Pharao war nicht bloß König, sondern ein lebender Gott — die irdische Verkörperung des Horus, des Falkengottes des Himmels — und verschmolz nach dem Tod mit Osiris, dem Herrscher des Jenseits. Dieses göttliche Königtum war über 3.000 Jahre der Grundstein der ägyptischen Zivilisation.\n\nDie Autorität des Pharaos war absolut. Als Mittler zwischen Göttern und Menschen vollzog er die wesentlichen Rituale, die Maat erhielten — die kosmische Ordnung, Wahrheit und Gerechtigkeit. Ohne Maat würde der Nil nicht anschwellen, die Ernten würden versagen und das Chaos würde herrschen. Dieser Glaube verlieh den Pharaonen unangefochtene Legitimität und bewog die Untertanen, ihr Leben der Arbeit an königlichen Projekten zu widmen, darunter der Bau von Monumenten, die ewig währen sollten.",
      "Die Ägypter waren zutiefst mit dem Tod beschäftigt — nicht aus Morbidität, sondern aus leidenschaftlichem Glauben an das ewige Leben. Die über Jahrtausende verfeinerte Mumifizierung sollte den Körper bewahren, damit die Seele (ka) zu ihm zurückkehren konnte. Einbalsamierer entfernten die Organe, behandelten den Leib 40 Tage mit Natronsalz, wickelten ihn in Leinen und umgaben ihn mit schützenden Amuletten.\n\nDer Verstorbene wurde dann durch die Duat — die Unterwelt — geleitet, mit Sprüchen aus dem Totenbuch. In der Halle der zwei Wahrheiten wog der Gott Anubis das Herz gegen die Feder der Maat. Ein von Sünde schweres Herz wurde vom Ungeheuer Ammit verschlungen; ein federleichtes Herz gelangte ins Paradies des Binsengefildes. Diese ausgefeilte Theologie trieb Investitionen in Grabkunst, Grabbau und Ritualtexte voran — und machte das alte Ägypten zu einer der reichhaltigsten dokumentierten Zivilisationen der Geschichte.",
      "Die Große Pyramide von Giza, um 2560 v. Chr. für Pharao Cheops erbaut, besteht aus etwa 2,3 Millionen Steinblöcken von je 2,5–15 Tonnen. Ohne Eisenwerkzeuge, Flaschenzüge oder Räder errichtet, war sie 3.800 Jahre das höchste Bauwerk der Welt. Die Präzision ist verblüffend: Die Basis ist auf 2,1 Zentimeter genau waagerecht, und die vier Seiten sind mit einem Fehler von weniger als 0,05 Grad an den Himmelsrichtungen ausgerichtet.\n\nWie gelang das? Tausende gelernte Arbeiter — keine Sklaven, wie lange angenommen, sondern bezahlte Kräfte, die Brot, Bier, ärztliche Versorgung und ein Begräbnis nahe dem Pharao erhielten — in wechselnden Teams organisiert. Die Archäologie hat die Arbeiterdörfer freigelegt, ihre Bäckereien und Brauereien, ihre Graffiti mit dem Prahlen über ihre Kolonnen. Die Pyramiden wurden nicht von gebrochenen Menschen gebaut, sondern von einer Zivilisation mit außerordentlicher Organisationskraft, getragen von echter religiöser Hingabe.",
      "Das ägyptische Pantheon umfasste Hunderte von Gottheiten, oft mit Tierköpfen dargestellt, die ihre göttlichen Eigenschaften verkörperten. Ra, der Sonnengott, segelte täglich in seiner Sonnenbarke über den Himmel und nachts durch die Unterwelt, im Kampf mit der Schlange Apophis. Osiris, von seinem eifersüchtigen Bruder Seth ermordet und zerstückelt, wurde von seiner treuen Gattin Isis auferweckt — ein Mythos von Tod und Erneuerung, der über Jahrtausende nachhallte.\n\nIsis wurde eine der beliebtesten Göttinnen der antiken Welt, ihr Kult breitete sich schließlich über das ganze Römische Reich aus. Thoth, der ibisköpfige Gott der Schrift und des Wissens, galt als Erfinder der Hieroglyphen. Sachmet, die löwenköpfige Kriegsgöttin, konnte Seuchen senden wie heilen. Diese Götter waren keine fernen Abstraktionen, sondern tätige Teilnehmer des Alltags — sie schützten Mütter bei der Geburt, leiteten die Toten und erhielten die himmlische Ordnung, die den Nil pünktlich anschwellen ließ.",
      "Ägyptens Neues Reich (ca. 1550–1070 v. Chr.) war seine mächtigste Epoche. Pharaonen wie Thutmosis III. eroberten ein Reich von Nubien bis Syrien. Ramses II. (reg. 1279–1213 v. Chr.), der 66 Jahre herrschte und über 100 Kinder zeugte, schloss nach der Schlacht bei Kadesch den ältesten erhaltenen Friedensvertrag der Geschichte mit den Hethitern.\n\nÄgyptens letzter Akt gehört Kleopatra VII. (reg. 51–30 v. Chr.), der letzten der ptolemäischen Dynastie. Eine brillante Sprachkundige, die neun Sprachen sprach, schmiedete sie strategische Bündnisse mit Julius Cäsar und Marcus Antonius, um Ägyptens Unabhängigkeit gegen Rom zu wahren. Als Antonius' Streitkräfte 31 v. Chr. bei Actium geschlagen wurden, wählte Kleopatra den Tod statt der Unterwerfung. Mit ihr endeten 3.000 Jahre pharaonischer Zivilisation — doch Ägyptens Kunst, Religion und Mythologie faszinierten und prägten weiterhin Kulturen in aller Welt.",
    ],
    fr: [
      "Dans l'Égypte antique, politique et religion ne faisaient qu'un. Le pharaon n'était pas un simple roi mais un dieu vivant — l'incarnation terrestre d'Horus, dieu-faucon du ciel — et, à sa mort, il se fondait dans Osiris, maître de l'au-delà. Cette royauté divine fut la pierre angulaire de la civilisation égyptienne pendant plus de 3 000 ans.\n\nL'autorité du pharaon était totale. Intermédiaire entre les dieux et les hommes, il accomplissait les rituels essentiels qui maintenaient la Maât — l'ordre cosmique, la vérité et la justice. Sans la Maât, le Nil ne déborderait pas, les récoltes échoueraient et le chaos régnerait. Cette croyance conférait aux pharaons une légitimité incontestée et poussait les sujets à consacrer une vie de labeur aux projets royaux, dont l'édification de monuments conçus pour durer éternellement.",
      "Les Égyptiens étaient profondément préoccupés par la mort — non par morbidité, mais par une croyance passionnée en la vie éternelle. La momification, affinée sur des millénaires, visait à préserver le corps afin que l'âme (ka) puisse y revenir. Les embaumeurs retiraient les organes, traitaient le corps au natron pendant 40 jours, l'enveloppaient de lin et l'entouraient d'amulettes protectrices.\n\nLe défunt était ensuite guidé à travers la Douat — le monde souterrain — par les formules du Livre des morts. À la Salle des Deux Vérités, le dieu Anubis pesait le cœur contre la plume de Maât. Un cœur lourd de péchés était dévoré par le monstre Ammit ; un cœur léger comme une plume entrait au paradis du Champ des roseaux. Cette théologie élaborée stimula l'investissement dans l'art funéraire, la construction des tombes et les textes rituels — faisant de l'Égypte antique l'une des civilisations les mieux documentées de l'histoire.",
      "La Grande Pyramide de Gizeh, bâtie pour le pharaon Khéops vers 2560 av. J.-C., se compose d'environ 2,3 millions de blocs de pierre pesant chacun 2,5 à 15 tonnes. Construite sans outils de fer, poulies ni roues, elle resta 3 800 ans le plus haut édifice du monde. La précision est stupéfiante : la base est de niveau à 2,1 centimètres près, et les quatre faces sont alignées sur les points cardinaux avec une erreur inférieure à 0,05 degré.\n\nComment y parvint-on ? Des milliers d'ouvriers qualifiés — non des esclaves, comme on l'a longtemps cru, mais des travailleurs payés qui recevaient pain, bière, soins médicaux et une sépulture près du pharaon — organisés en équipes tournantes. L'archéologie a révélé les villages ouvriers, leurs boulangeries et brasseries, leurs graffitis vantant leurs équipes. Les pyramides ne furent pas bâties par des gens brisés mais par une civilisation d'une extraordinaire capacité d'organisation, animée d'une dévotion religieuse sincère.",
      "Le panthéon égyptien comptait des centaines de divinités, souvent représentées à tête d'animal traduisant leurs qualités divines. Rê, dieu solaire, voguait chaque jour dans sa barque à travers le ciel et chaque nuit dans le monde souterrain, combattant le serpent Apophis. Osiris, assassiné et démembré par son frère jaloux Seth, fut ressuscité par son épouse dévouée Isis — mythe de mort et de renouveau résonnant à travers les millénaires.\n\nIsis devint l'une des déesses les plus aimées du monde antique, son culte se répandant jusque dans tout l'Empire romain. Thot, dieu à tête d'ibis de l'écriture et du savoir, passait pour l'inventeur des hiéroglyphes. Sekhmet, déesse lionne de la guerre, pouvait à la fois envoyer les fléaux et les guérir. Ces dieux n'étaient pas de lointaines abstractions mais des acteurs de la vie quotidienne — protégeant les mères en couches, guidant les défunts et maintenant l'ordre céleste qui faisait déborder le Nil à date fixe.",
      "Le Nouvel Empire égyptien (v. 1550–1070 av. J.-C.) fut son ère la plus puissante. Des pharaons comme Thoutmôsis III conquirent un empire allant de la Nubie à la Syrie. Ramsès II (r. 1279–1213 av. J.-C.), qui régna 66 ans et engendra plus de 100 enfants, signa le plus ancien traité de paix conservé de l'histoire avec les Hittites après la bataille de Qadesh.\n\nLe dernier acte de l'Égypte revient à Cléopâtre VII (r. 51–30 av. J.-C.), dernière de la dynastie lagide. Brillante polyglotte parlant neuf langues, elle noua des alliances stratégiques avec Jules César et Marc Antoine pour préserver l'indépendance égyptienne face à Rome. Quand les forces d'Antoine furent vaincues à Actium en 31 av. J.-C., Cléopâtre choisit la mort plutôt que la soumission. Avec elle s'achevèrent 3 000 ans de civilisation pharaonique — mais l'art, la religion et la mythologie de l'Égypte continuèrent de fasciner et d'influencer les cultures du monde entier.",
    ],
  },
  'ancient-06': {
    de: [
      "Die Phönizier bewohnten einen schmalen Küstenstreifen des östlichen Mittelmeers — etwa den heutigen Libanon —, eingezwängt zwischen Meer und Libanongebirge. Was ihnen an Land fehlte, gewannen sie an maritimem Genie. Ihre großen Hafenstädte — Tyros, Sidon, Byblos, Beirut — zählten zu den wohlhabendsten Handelszentren der Antike.\n\nDie Griechen nannten sie „Phoinikes“ — das Purpurvolk — nach Phöniziens berühmtestem Erzeugnis: einem leuchtend purpurroten Farbstoff aus dem Schleim der Purpurschnecke. Schon eine kleine Menge erforderte Tausende Schnecken und stank während der Verarbeitung nach Fäulnis; der fertige Farbstoff war seltener als Gold. Nur Könige und Hohepriester konnten sich phönizische Purpurgewänder leisten. Die Farbe „Königspurpur“ bewahrt bis heute ihre Verbindung zu Macht und Reichtum — ein Erbe phönizischen Handels über dreitausend Jahre hinweg.",
      "Der folgenreichste Beitrag der Phönizier zur Zivilisation war weder Purpur noch Handelsschifffahrt, sondern die Schrift. Um 1050 v. Chr. entwickelten sie eine vereinfachte Buchstabenschrift aus 22 Konsonanten — eine revolutionäre Vereinfachung der komplexen Keilschrift- und Hieroglyphensysteme, deren Beherrschung jahrelange Fachausbildung verlangt hatte. Der Lehrling eines phönizischen Kaufmanns konnte das System in Wochen lernen.\n\nDiese Praktikabilität machte es unwiderstehlich. Die Griechen übernahmen das phönizische Alphabet um das 9. Jahrhundert v. Chr. und fügten Vokale hinzu — der Vorfahre jedes westlichen Alphabets. Aus dem Griechischen wurde das Lateinische; aus dem Lateinischen Italienisch, Französisch, Spanisch, Englisch und Dutzende weitere Sprachen. Die aramäische Fassung breitete sich ostwärts aus und wurde zur Mutter von Hebräisch, Arabisch und den Schriften Südasiens. Jedes Mal, wenn Sie lesen oder schreiben, nutzen Sie ein System, das von phönizischen Kaufleuten abstammt, die eine effiziente Art brauchten, Ladelisten und Geschäfte festzuhalten. Keine einzelne kulturelle Erfindung hatte weiteren Einfluss auf die Menschheitsgeschichte.",
      "Phönizische Handelsschiffe fuhren, wohin es Gewinn zu machen gab. Sie erschlossen Routen westwärts durchs Mittelmeer, um Sizilien und Sardinien, durch die Straße von Gibraltar — die sie „Säulen des Melqart“ nannten — und entlang der Atlantikküsten Europas und Afrikas. Ihre Handelsschiffe, robuste rundbäuchige „Hippoi“ (nach ihren pferdekopfförmigen Bugen benannt), konnten Ladungen von 30–50 Tonnen tragen und navigierten nach Sternen und überliefertem Wissen.\n\nDie Phönizier gründeten Handelsposten und Kolonien im ganzen Mittelmeer: auf Zypern, Sardinien, Malta, Sizilien, den Balearen und an Spaniens Küste. Sie handelten mit kanaanäischem Wein und Öl, ägyptischem Leinen, mesopotamischen Textilien, zyprischem Kupfer, spanischem Silber und afrikanischem Elfenbein. Ihre Handelsnetze waren umfassender als die jeder früheren Zivilisation und schufen die Vorlage des Mittelmeerhandels, die Griechen, Karthager und Römer später übernehmen und ausweiten sollten.",
      "Um 814 v. Chr. führte der Überlieferung nach Königin Dido von Tyros eine Gruppe von Verbannten, um Karthago („Neustadt“) auf einer Landzunge der nordafrikanischen Küste beim heutigen Tunis zu gründen. Ob die Sagengründung zutrifft oder nicht — Karthago überflügelte rasch alle phönizischen Mutterstädte. Seine dreifachen Häfen — einer für den Handel, einer für die Kriegsflotte, einer für die königliche Flotte — konnten zugleich 220 Kriegsschiffe fassen.\n\nBis zum 4. Jahrhundert v. Chr. beherrschte Karthago den Handel des westlichen Mittelmeers und regierte ein Handelsreich, das Nordafrika, Spanien, Sardinien und Sizilien umfasste. Sein Söldnerheer — numidische Reiter, spanische Infanterie, griechische Offiziere — war die furchterregendste Macht des westlichen Mittelmeers. Karthagos Zusammenstoß mit der aufsteigenden Römischen Republik in den drei Punischen Kriegen (264–146 v. Chr.) sollte die Zivilisation verändern. Rom setzte sich schließlich durch — es machte Karthago 146 v. Chr. dem Erdboden gleich —, doch erst, nachdem Hannibals Genie Rom an den Rand der Vernichtung gebracht hatte. Der Kampf zwischen Rom und Karthago prägte die gesamte Zukunft der westlichen Zivilisation.",
      "Die Phönizier verschwanden als eigenständiges Volk, aufgesogen von der sich ausdehnenden hellenistischen und später römischen Welt, doch ihr Erbe erwies sich als unzerstörbar. Das von jeder Zivilisation, die ihm begegnete, abgewandelte Alphabet wurde zum Werkzeug, mit dem menschliches Wissen über Jahrtausende festgehalten und übermittelt wurde. Ohne die phönizische Schrift gäbe es keinen Homer, keine Bibel, keine klassische Philosophie, keine wissenschaftliche Literatur.\n\nPhönizische Seemannskunst vermaß die Welt: Griechische Geographen berichteten später, phönizische Seeleute, um 600 v. Chr. von Ägyptens Pharao Necho II. beauftragt, hätten den ganzen Kontinent Afrika umsegelt — eine Leistung, die Europäer erst mit Vasco da Gama 1488 wiederholten. Ihre Beobachtung, dass die Sonne während des südlichen Teils der Reise in ihrem Norden stand, hielt Herodot für unglaubwürdig — doch gerade dieses Detail überzeugte moderne Gelehrte von der Echtheit des Berichts. In ihrem rastlosen, kaufmännischen, seefahrenden Geist nahmen die Phönizier etwas ausgesprochen Modernes vorweg: die Idee, dass die Welt da ist, um erkundet, behandelt und verbunden zu werden.",
    ],
    fr: [
      "Les Phéniciens occupaient une étroite bande côtière de la Méditerranée orientale — à peu près le Liban actuel — coincée entre la mer et les monts du Liban. Ce qui leur manquait en terres, ils le gagnaient en génie maritime. Leurs grandes cités portuaires — Tyr, Sidon, Byblos, Beyrouth — comptaient parmi les centres commerciaux les plus prospères de l'Antiquité.\n\nLes Grecs les appelaient « Phoinikes » — le peuple pourpre — d'après le produit le plus célèbre de la Phénicie : une teinture d'un pourpre cramoisi vif extraite du mucus du murex. En produire même une petite quantité exigeait des milliers de coquillages et dégageait une puanteur de pourriture ; la teinture finie était plus rare que l'or. Seuls rois et grands prêtres pouvaient s'offrir des robes de pourpre phénicienne. La couleur « pourpre royale » conserve à ce jour son lien avec le pouvoir et la richesse — héritage du commerce phénicien sur trois mille ans.",
      "La contribution la plus décisive des Phéniciens à la civilisation ne fut ni la teinture pourpre ni la marine marchande, mais l'écriture. Vers 1050 av. J.-C., ils mirent au point une écriture alphabétique simplifiée de 22 consonnes — simplification révolutionnaire des systèmes cunéiforme et hiéroglyphique dont la maîtrise avait exigé des années de formation spécialisée. L'apprenti d'un marchand phénicien pouvait apprendre le système en quelques semaines.\n\nCette commodité le rendit irrésistible. Les Grecs adoptèrent l'alphabet phénicien vers le IXe siècle av. J.-C., ajoutant les voyelles pour créer l'ancêtre de tout alphabet occidental. Le grec devint le latin ; le latin devint l'italien, le français, l'espagnol, l'anglais et des dizaines d'autres langues. La version araméenne se répandit vers l'est, devenant la mère de l'hébreu, de l'arabe et des écritures d'Asie du Sud. Chaque fois que vous lisez ou écrivez, vous utilisez un système hérité de marchands phéniciens qui avaient besoin d'un moyen efficace de noter manifestes de cargaison et transactions. Aucune invention culturelle unique n'a eu d'impact plus vaste sur l'histoire humaine.",
      "Les navires de commerce phéniciens s'aventuraient partout où il y avait profit à faire. Ils ouvrirent des routes vers l'ouest à travers la Méditerranée, autour de la Sicile et de la Sardaigne, par le détroit de Gibraltar — qu'ils appelaient les « colonnes de Melqart » — et le long des côtes atlantiques d'Europe et d'Afrique. Leurs vaisseaux marchands, robustes « hippoi » à coque ronde (nommés d'après leurs proues en tête de cheval), pouvaient porter 30 à 50 tonnes de fret, naviguant aux étoiles et au savoir transmis de capitaine en capitaine.\n\nLes Phéniciens établirent comptoirs et colonies à travers la Méditerranée : à Chypre, en Sardaigne, à Malte, en Sicile, aux Baléares et sur la côte espagnole. Ils échangeaient vin et huile de Canaan, lin égyptien, textiles mésopotamiens, cuivre chypriote, argent espagnol et ivoire africain. Leurs réseaux commerciaux étaient plus vastes que ceux de toute civilisation antérieure, créant le modèle du commerce méditerranéen que Grecs, Carthaginois et Romains hériteraient et étendraient ensuite.",
      "Vers 814 av. J.-C., selon la tradition, la reine Didon de Tyr conduisit un groupe d'exilés pour fonder Carthage (« ville neuve ») sur un promontoire de la côte nord-africaine près de l'actuelle Tunis. Que la fondation légendaire soit exacte ou non, Carthage dépassa rapidement toutes les cités-mères phéniciennes. Ses ports triples — un pour le commerce, un pour la marine, un pour la flotte royale — pouvaient accueillir simultanément 220 navires de guerre.\n\nAu IVe siècle av. J.-C., Carthage contrôlait le commerce de la Méditerranée occidentale, régnant sur un empire commercial englobant l'Afrique du Nord, l'Espagne, la Sardaigne et la Sicile. Son armée de mercenaires — cavalerie numide, infanterie espagnole, officiers grecs — était la force la plus redoutable de la Méditerranée occidentale. L'affrontement de Carthage avec la République romaine montante lors des trois guerres puniques (264–146 av. J.-C.) allait changer le cours de la civilisation. Rome finit par l'emporter — rasant Carthage en 146 av. J.-C. — mais seulement après que le génie d'Hannibal eut mené Rome au bord de la destruction. La lutte entre Rome et Carthage façonna tout l'avenir de la civilisation occidentale.",
      "Les Phéniciens disparurent comme peuple distinct, absorbés dans les mondes hellénistique puis romain en expansion, mais leur héritage se révéla indestructible. L'alphabet, modifié par chaque civilisation qui le rencontra, devint l'outil par lequel le savoir humain fut consigné et transmis à travers les millénaires. Sans l'écriture phénicienne, il n'y aurait ni Homère, ni Bible, ni philosophie classique, ni littérature scientifique.\n\nLa marine phénicienne cartographia le monde : des géographes grecs rapportèrent plus tard que des marins phéniciens, commandités par le pharaon Néchao II d'Égypte vers 600 av. J.-C., firent le tour du continent africain — exploit que les Européens ne répétèrent qu'avec Vasco de Gama en 1488. Leur observation que le soleil paraissait au nord durant la partie sud du voyage fut jugée incroyable par Hérodote — pourtant c'est précisément ce détail qui convainquit les savants modernes de l'authenticité du récit. Dans leur esprit inquiet, marchand et marin, les Phéniciens préfiguraient quelque chose de nettement moderne : l'idée que le monde existe pour être exploré, échangé et relié.",
    ],
  },
  'ancient-07': {
    de: [
      "Nördlich des Olymp, jenseits der Stadtstaaten, die sich für das Zentrum der Zivilisation hielten, lag Makedonien — ein raues Königreich aus Bergland-Hirten, Tiefland-Bauern und harten Reiter-Aristokraten. Die Südgriechen taten die Makedonen als Halbbarbaren ab, die ihren Wein unvermischt tranken und Politik mit Jagdspeeren regelten. Doch das Königreich besaß, was den zersplitterten Stadtstaaten fehlte: Holz, Goldminen, weite Reiterebenen und ein einziges Königshaus — die Argeaden —, das seine Abstammung von Herakles herleitete.\n\nVon der Hauptstadt Pella und dem alten Königssitz Aigai, wo die Könige bestattet wurden, sah Makedonien zu, wie sich die griechische Welt in endlosen Kriegen zwischen Athen, Sparta und Theben erschöpfte. 359 v. Chr. erbte ein dreiundzwanzigjähriger Prinz namens Philipp ein zerschlagenes Königreich am Rand des Zusammenbruchs — und machte es binnen zweier Jahrzehnte zur furchtbarsten Militärmacht der Erde.",
      "Philipp II. begriff, dass Schlachten durch Organisation gewonnen werden, nicht durch Heldentum. Er bewaffnete seine Infanterie mit der Sarissa — einem bis zu sechs Meter langen Spieß — und drillte sie zu einer Phalanx, die eine undurchdringliche Hecke aus Eisenspitzen bot. Diesem Amboss stellte er einen Hammer zur Seite: die Hetairenreiterei, die besten Stoßreiter der Zeit. Er vervollkommnete die Belagerungskunst, professionalisierte den Sold und heiratete strategisch quer über den Balkan.\n\nEine nach der anderen verleibte Philipp sich die Goldminen Thrakiens, die Häfen der Chalkidiki und Thessaliens Reiterland ein. Als Athen und Theben sich schließlich 338 v. Chr. bei Chaironeia gegen ihn verbündeten, zerschmetterte sein Heer sie an einem einzigen Nachmittag — sein achtzehnjähriger Sohn Alexander führte den entscheidenden Reiterangriff. Philipp zwang die griechischen Staaten unter seiner Führung in den Korinthischen Bund und rüstete zu einer großen Invasion Persiens. 336 v. Chr., bei der Hochzeit seiner Tochter in Aigai, wurde er von seinem eigenen Leibwächter ermordet — und Thron, Heer und das Persien-Vorhaben gingen an Alexander über.",
      "Alexander setzte 334 v. Chr. mit etwa 40.000 Mann nach Asien über und schleuderte einen Speer an den Strand, um den Kontinent als „speererworbenes“ Land zu beanspruchen. Am Fluss Granikos zerbrach er das erste gegen ihn gesandte persische Heer. Bei Issos (333 v. Chr.) schlug er König Dareios III. selbst in die Flucht und nahm die königliche Familie gefangen. Dareios' Angebot der halben Reichshälfte lehnte er ab — „Ich würde annehmen“, sagte sein General Parmenion, „wäre ich Alexander“; „Das würde ich auch“, erwiderte Alexander, „wäre ich Parmenion“ — und wandte sich stattdessen nach Süden.\n\nTyros, die uneinnehmbare Inselfestung, fiel nach siebenmonatiger Belagerung, in der Alexander einen Damm durchs Meer baute. Ägypten empfing ihn als Befreier und krönte ihn zum Pharao; am Nildelta zeichnete er die Straßen Alexandrias vor, der größten der zwanzig Städte, die seinen Namen tragen sollten. Dann, bei Gaugamela 331 v. Chr., vielleicht fünf zu eins unterlegen, vernichtete er Dareios' letztes großes Heer. Babylon, Susa und Persepolis — mit seinem Schatz von 120.000 Talenten — fielen nacheinander. Das Reich des Kyros war sein.",
      "Die meisten Eroberer hätten aufgehört. Alexander marschierte weiter — durch den Hindukusch, über Baktrien und Sogdien, jagte Dareios' Mörder und schlug in drei Jahren brutaler Bergkriegsführung einen Aufstand nach dem anderen nieder. Er heiratete die baktrische Adelige Roxane, legte persische Hoftracht an und begann, unterworfene Völker als zu regierende Untertanen statt als zu plündernde Feinde zu behandeln — eine Politik, die seine makedonischen Veteranen zunehmend verdross.\n\n326 v. Chr. stieg er in den Punjab hinab und besiegte König Poros und seine Kriegselefanten am Fluss Hydaspes, in vielleicht seiner taktisch brillantesten Schlacht. Er drängte ostwärts zum Ganges — doch am Fluss Hyphasis weigerte sich sein erschöpftes Heer, acht Jahre und 20.000 Kilometer von der Heimat entfernt, einen weiteren Schritt zu tun. Zum einzigen Mal in seinem Leben wurde Alexander besiegt — von den eigenen Männern. Der Rückzug durch die gedrosische Wüste tötete mehr seiner Soldaten als alle seine Schlachten zusammen.",
      "Zurück in Babylon, bei der Planung einer Arabien-Expedition, verfiel Alexander nach einer durchzechten Nacht plötzlich in Fieber. Am 11. Juni 323 v. Chr. starb er im Palast Nebukadnezars, einen Monat vor seinem dreiunddreißigsten Geburtstag. Auf dem Sterbebett gefragt, wem er das Reich hinterlasse, flüsterte er angeblich „dem Stärksten“. Seine Generäle — die Diadochen — kamen dem nach und zerrissen das Reich in vierzig Jahren Krieg: Ptolemaios nahm Ägypten, Seleukos nahm Asien, Antigonos' Erben nahmen Makedonien selbst.\n\nDoch die Eroberung überlebte den Eroberer. Griechisch wurde die gemeinsame Sprache von der Adria bis nach Afghanistan; griechische Städte, Theater und Gymnasien sprossen über drei Kontinente; Alexandrias Bibliothek und Museum machten Ägypten zur geistigen Hauptstadt der Welt. Diese hellenistische Zivilisation — griechische Kultur verschmolzen mit persischen, ägyptischen und indischen Traditionen — formte die Welt, die Rom erben würde, die Welt, in der das Neue Testament geschrieben werden sollte. Der Junge aus Pella hatte die antike Welt nicht bloß erobert; er hatte sie neu verdrahtet.",
    ],
    fr: [
      "Au nord du mont Olympe, au-delà des cités-États qui se croyaient le centre de la civilisation, s'étendait la Macédoine — un rude royaume de bergers montagnards, de paysans des plaines et d'aristocrates cavaliers. Les Grecs du sud méprisaient les Macédoniens, ces demi-barbares qui buvaient leur vin pur et réglaient la politique à coups d'épieux de chasse. Pourtant le royaume possédait ce qui manquait aux cités morcelées : bois, mines d'or, vastes plaines à cavalerie, et une seule maison royale — les Argéades — qui se disait descendue d'Héraklès.\n\nDepuis la capitale de Pella et l'ancien siège royal d'Aigéai où l'on enterrait les rois, la Macédoine regardait le monde grec s'épuiser en guerres sans fin entre Athènes, Sparte et Thèbes. En 359 av. J.-C., un prince de vingt-trois ans nommé Philippe hérita d'un royaume meurtri au bord de l'effondrement — et en deux décennies en fit la plus redoutable puissance militaire de la terre.",
      "Philippe II comprit que les batailles se gagnent par l'organisation, non par l'héroïsme. Il arma son infanterie de la sarisse — une pique de six mètres — et la dressa en phalange offrant une haie impénétrable de pointes de fer. À cette enclume il adjoignit un marteau : la cavalerie des compagnons, les meilleurs cavaliers de choc de l'époque. Il perfectionna l'art du siège, professionnalisa la solde et se maria stratégiquement à travers les Balkans.\n\nUne à une, Philippe absorba les mines d'or de Thrace, les ports de Chalcidique et les terres à cavalerie de Thessalie. Quand Athènes et Thèbes se liguèrent enfin contre lui à Chéronée en 338 av. J.-C., son armée les brisa en un seul après-midi — son fils Alexandre, âgé de dix-huit ans, menant la charge de cavalerie décisive. Philippe força les États grecs à entrer dans la Ligue de Corinthe sous sa direction et prépara une grande invasion de la Perse. En 336 av. J.-C., aux noces de sa fille à Aigéai, il fut assassiné par son propre garde du corps — et le trône, l'armée et le projet perse passèrent à Alexandre.",
      "Alexandre passa en Asie en 334 av. J.-C. avec environ 40 000 hommes, jetant une lance sur le rivage pour revendiquer le continent comme terre « conquise par la lance ». Au fleuve Granique, il brisa la première armée perse envoyée contre lui. À Issos (333 av. J.-C.), il mit en déroute le roi Darius III lui-même, capturant la famille royale. Refusant l'offre par Darius de la moitié de l'empire — « J'accepterais, dit son général Parménion, si j'étais Alexandre » ; « Moi aussi, répliqua Alexandre, si j'étais Parménion » — il obliqua vers le sud.\n\nTyr, l'imprenable forteresse insulaire, tomba après un siège de sept mois au cours duquel Alexandre bâtit une chaussée à travers la mer. L'Égypte l'accueillit en libérateur et le couronna pharaon ; sur le delta du Nil, il traça les rues d'Alexandrie, la plus grande des vingt villes qui porteraient son nom. Puis, à Gaugamèles en 331 av. J.-C., en infériorité peut-être de cinq contre un, il anéantit la dernière grande armée de Darius. Babylone, Suse et Persépolis — avec son trésor de 120 000 talents — tombèrent tour à tour. L'empire de Cyrus était sien.",
      "La plupart des conquérants se seraient arrêtés. Alexandre poursuivit — à travers l'Hindou Kouch, la Bactriane et la Sogdiane, traquant les meurtriers de Darius et écrasant révolte sur révolte en trois ans de guerre de montagne brutale. Il épousa la noble bactrienne Roxane, adopta le costume de cour perse et commença à traiter les peuples conquis comme des sujets à gouverner plutôt que des ennemis à piller — politiques que ses vétérans macédoniens supportaient de plus en plus mal.\n\nEn 326 av. J.-C., il descendit dans le Pendjab et vainquit le roi Pôros et ses éléphants de guerre au fleuve Hydaspe, dans sa bataille peut-être la plus brillante sur le plan tactique. Il poussa vers l'est en direction du Gange — mais au fleuve Hyphase, son armée épuisée, à huit ans et 20 000 kilomètres de chez elle, refusa d'avancer d'un pas de plus. Pour la seule fois de sa vie, Alexandre fut vaincu — par ses propres hommes. La retraite à travers le désert de Gédrosie tua plus de ses soldats que toutes ses batailles réunies.",
      "De retour à Babylone, planifiant une expédition en Arabie, Alexandre tomba dans une fièvre soudaine après une nuit de forte beuverie. Le 11 juin 323 av. J.-C., il mourut dans le palais de Nabuchodonosor, à un mois de ses trente-trois ans. À qui laissait-il l'empire, lui demanda-t-on sur son lit de mort ? Il aurait murmuré « au plus fort ». Ses généraux — les diadoques — s'exécutèrent, déchirant l'empire en quarante ans de guerre : Ptolémée prit l'Égypte, Séleucos prit l'Asie, les héritiers d'Antigone prirent la Macédoine même.\n\nPourtant la conquête survécut au conquérant. Le grec devint la langue commune de l'Adriatique à l'Afghanistan ; cités, théâtres et gymnases grecs surgirent sur trois continents ; la Bibliothèque et le Musée d'Alexandrie firent de l'Égypte la capitale intellectuelle du monde. Cette civilisation hellénistique — culture grecque fondue aux traditions perse, égyptienne et indienne — façonna le monde dont Rome hériterait, le monde dans lequel serait écrit le Nouveau Testament. Le garçon de Pella n'avait pas seulement conquis le monde antique ; il l'avait recâblé.",
    ],
  },
  'ancient-08': {
    de: [
      "Als Alexander der Große 323 v. Chr. ohne klaren Erben in Babylon starb, beantworteten seine Feldherren die Frage „Wem gehört das Reich?“ mit vierzig Jahren Krieg. Diese Diadochen — „Nachfolger“ — teilten die Eroberungen immer wieder neu auf, bis sich drei große Dynastien festigten: die Ptolemäer in Ägypten, die Seleukiden im alten persischen Kernland und die Antigoniden in Makedonien und Griechenland.\n\nObwohl Alexanders Reich als Staat nicht überdauerte, überlebte es als Welt. Griechisch wurde die gemeinsame Sprache (Koine) von Verwaltung und Handel von der Adria bis nach Afghanistan, und Städte griechischen Stils mit Theatern, Gymnasien und Agoren sprossen Tausende Kilometer von Athen entfernt.",
      "Keine Stadt verkörperte das Zeitalter wie Alexandria, von Alexander an Ägyptens Küste gegründet und von Ptolemaios I. zur Hauptstadt gemacht. Sein Doppelhafen bewältigte das Getreide des Niltals; sein Pharos-Leuchtturm, eines der Sieben Weltwunder, wies den Schiffen von einem über 100 Meter hohen Turm den Weg.\n\nDie Ptolemäer steckten königlichen Reichtum in das Museion — eine Forschungsstätte, deren Gelehrte von der Krone besoldet wurden — und in seine berühmte Bibliothek, die eine Abschrift jedes existierenden Buches suchte. In Alexandria anlegende Schiffe wurden nach Schriftrollen zum Kopieren durchsucht. Hier ordnete Euklid die Geometrie, Herophilos begründete die Anatomie und Dichter bearbeiteten die maßgeblichen Homer-Texte.",
      "Die hellenistische Wissenschaft erreichte Höhen, die Europa 1.500 Jahre nicht wiedersehen würde. Archimedes von Syrakus berechnete Pi, entdeckte das Auftriebsgesetz in seiner Wanne („Heureka!“) und baute Kriegsmaschinen, die eine römische Flotte in Schrecken versetzten. Eratosthenes, Oberbibliothekar in Alexandria, maß den Erdumfang mithilfe von Schatten in zwei Städten und einfacher Geometrie — und kam erstaunlich nahe heran.\n\nAristarch von Samos schlug siebzehn Jahrhunderte vor Kopernikus vor, dass die Erde die Sonne umkreise. Hipparch katalogisierte die Sterne und entdeckte die Präzession der Tagundnachtgleichen. Der Mechanismus von Antikythera — ein bronzener Zahnradcomputer zur Vorhersage von Finsternissen, geborgen aus einem antiken Wrack — zeigt, wie ausgefeilt die Ingenieurskunst dieser Welt geworden war.",
      "Die hellenistische Welt war ein Labor kultureller Verschmelzung. In Ägypten wurden ptolemäische Pharaonen im alten Stil gemeißelt, während sie Griechisch sprachen; der neue Gott Serapis vereinte Osiris mit Zeus. In Baktrien und Indien prägten griechische Könige Münzen mit buddhistischen Symbolen, und griechisch-buddhistische Bildhauer gaben dem Buddha sein erstes menschliches Abbild im Faltengewand des Apollon.\n\nEines nach dem anderen fielen die Nachfolgereiche an Rom — Makedonien 168 v. Chr., der seleukidische Rest 63 v. Chr. und Ägypten mit dem Tod Kleopatras VII. 30 v. Chr. Doch Rom eroberte eine bereits griechische Welt, und durch Rom wurden hellenistische Philosophie, Wissenschaft und Kunst zum Fundament der westlichen — und weiten Teilen der islamischen — Zivilisation.",
      "Nicht jede hellenistische Macht war ein Riese. Die attalidischen Könige von Pergamon in Westanatolien machten aus einer Hügelfestung und einem Schatz einen der glänzendsten Höfe der Zeit. Ihre Bibliothek wuchs so ernsthaft zur Rivalin Alexandrias heran, dass die Ptolemäer angeblich die Papyrusausfuhr sperrten und Pergamon zwangen, einen Schreibträger aus behandelter Tierhaut zu vervollkommnen: charta pergamena, das Pergament, das Medium, auf dem das mittelalterliche Europa seine Bücher abschreiben sollte. Der Große Altar von Pergamon mit seinem sich windenden Fries kämpfender Götter und Giganten bleibt eine der höchsten Leistungen der antiken Kunst. Als der letzte Attalide 133 v. Chr. starb, vermachte er sein ganzes Königreich Rom — das seltsamste Vermächtnis der antiken Geschichte und ein Zeichen dafür, wo die Macht nun lag.",
    ],
    fr: [
      "Quand Alexandre le Grand mourut à Babylone en 323 av. J.-C. sans héritier clair, ses maréchaux répondirent à la question « à qui revient l'empire ? » par quarante ans de guerre. Ces diadoques — « successeurs » — partagèrent les conquêtes encore et encore jusqu'à ce que trois grandes dynasties se stabilisent : les Ptolémées en Égypte, les Séleucides sur l'ancien cœur perse et les Antigonides en Macédoine et en Grèce.\n\nBien que l'empire d'Alexandre n'ait pas survécu comme État, il survécut comme monde. Le grec devint la langue commune (koinè) de l'administration et du commerce, de l'Adriatique à l'Afghanistan, et des cités de style grec, avec théâtres, gymnases et agoras, surgirent à des milliers de kilomètres d'Athènes.",
      "Aucune cité n'incarna l'époque comme Alexandrie, fondée par Alexandre sur la côte d'Égypte et faite capitale par Ptolémée Ier. Son double port traitait le grain de la vallée du Nil ; son phare de Pharos, l'une des Sept Merveilles, guidait les navires depuis une tour de plus de 100 mètres.\n\nLes Ptolémées versèrent la richesse royale dans le Mouseion — institution de recherche dont les savants étaient salariés par la couronne — et dans sa célèbre bibliothèque, qui cherchait une copie de chaque livre existant. Les navires accostant à Alexandrie étaient fouillés pour des rouleaux à copier. Là, Euclide organisa la géométrie, Hérophile fonda l'anatomie et des poètes établirent les textes définitifs d'Homère.",
      "La science hellénistique atteignit des sommets que l'Europe ne reverrait pas avant 1 500 ans. Archimède de Syracuse calcula pi, découvrit la loi de la poussée dans son bain (« Eurêka ! ») et construisit des machines de guerre qui terrorisèrent une flotte romaine. Ératosthène, bibliothécaire en chef d'Alexandrie, mesura la circonférence de la Terre à l'aide d'ombres dans deux villes et d'une géométrie simple — et s'en approcha étonnamment.\n\nAristarque de Samos proposa que la Terre tourne autour du Soleil dix-sept siècles avant Copernic. Hipparque catalogua les étoiles et découvrit la précession des équinoxes. La machine d'Anticythère — calculateur de bronze à engrenages pour prédire les éclipses, retrouvé dans une épave antique — montre à quel point l'ingénierie de ce monde était devenue sophistiquée.",
      "Le monde hellénistique était un laboratoire de fusion culturelle. En Égypte, les pharaons lagides étaient sculptés dans le style ancien tout en parlant grec ; le nouveau dieu Sérapis mêlait Osiris à Zeus. En Bactriane et en Inde, des rois grecs frappaient des monnaies à symboles bouddhistes, et des sculpteurs gréco-bouddhiques donnèrent au Bouddha sa première image humaine dans les drapés d'Apollon.\n\nUn à un, les royaumes successeurs tombèrent devant Rome — la Macédoine en 168 av. J.-C., le reliquat séleucide en 63 av. J.-C. et l'Égypte à la mort de Cléopâtre VII en 30 av. J.-C. Mais Rome conquit un monde déjà grec, et c'est par Rome que la philosophie, la science et l'art hellénistiques devinrent le fondement de la civilisation occidentale — et d'une grande part de la civilisation islamique.",
      "Toute puissance hellénistique n'était pas un géant. Les rois attalides de Pergame, en Anatolie occidentale, firent d'une forteresse de colline et d'un trésor l'une des cours les plus brillantes de l'époque. Leur bibliothèque grandit au point de rivaliser avec celle d'Alexandrie — si sérieusement que les Ptolémées auraient interdit l'exportation de papyrus, forçant Pergame à perfectionner un support d'écriture en peau animale traitée : la charta pergamena, le parchemin, le médium sur lequel l'Europe médiévale copierait ses livres. Le Grand Autel de Pergame, avec sa frise tourmentée de dieux combattant des géants, reste l'un des sommets de l'art antique. Quand le dernier Attalide mourut en 133 av. J.-C., il légua tout son royaume à Rome — le plus étrange legs de l'histoire antique, et un signe de là où résidait désormais le pouvoir.",
    ],
  },
  'ancient-09': {
    de: [
      "In einer einzigen Generation (550–530 v. Chr.) verschlang Kyros II. von Persien das medische, das lydische und das neubabylonische Reich und schuf etwas Neues in der Weltgeschichte: einen Staat, der fast alle zivilisierten Länder des Nahen Ostens umfasste. Das Revolutionäre an Kyros war nicht die Eroberung, sondern die Herrschaft. Statt Völker zu deportieren und Tempel nach assyrischer Art zu zerschlagen, bestätigte er örtliche Priesterschaften, achtete örtliche Bräuche und ließ die jüdischen Verbannten in Babylon heimkehren, um den Tempel Jerusalems wieder aufzubauen.\n\nDer Kyros-Zylinder, eine tönerne Proklamation seiner Herrschaft in Babylon, wird oft als frühe Charta der Toleranz beschrieben. Das von ihm gegründete Reich sollte nach diesem Grundsatz regiert werden: Vielfalt unter einem einzigen König der Könige.",
      "Dareios I. (reg. 522–486 v. Chr.) machte aus Eroberungen ein System. Er teilte das Reich in etwa zwanzig Satrapien, jede unter einem Statthalter (Satrapen), der festen Tribut einzog — Gold aus Indien, Pferde aus Kilikien, Getreide aus Ägypten. Königliche Inspektoren, „die Augen und Ohren des Königs“, bereisten die Provinzen, um Ehrgeiz und Korruption im Zaum zu halten.\n\nDareios vereinheitlichte die Goldmünze (den Dareikos), grub einen Kanal vom Nil zum Roten Meer und baute die Königsstraße von Sardes nach Susa, auf der berittene Kuriere Nachrichten in etwa einer Woche weitergaben — eine Reise, die gewöhnliche Reisende drei Monate kostete. Herodots bewundernde Beschreibung dieser Kuriere — „weder Schnee noch Regen noch Hitze noch nächtliches Dunkel“ — dient noch heute als Postmotto.",
      "Auf einer großen steinernen Terrasse im persischen Kernland begann Dareios Persepolis — eine zeremonielle Hauptstadt aus Audienzhallen, deren Säulen zwanzig Meter emporragten, gekrönt von Doppelstier-Kapitellen. Ihre Treppen tragen gemeißelte Prozessionen der Völker des Reiches: Babylonier mit Textilien, Lyder mit Vasen, Äthiopier mit Elfenbein — jeder in Landestracht, mit Tribut zum Neujahrsfest. Nirgends ist die Reichsidee der Einheit-in-Vielfalt klarer gemeißelt.\n\nDie persische Religion folgte dem Propheten Zoroaster, dessen Lehre das Dasein als sittlichen Kampf zwischen Wahrheit (Asha) und Lüge (Druj) unter dem weisen Herrn Ahura Mazda begriff. Zoroastrische Vorstellungen — ein kosmischer Kampf von Gut und Böse, ein Gericht nach dem Tod, eine endgültige Erneuerung der Welt — sollten in Judentum, Christentum und Islam nachhallen.",
      "Die Westausdehnung des Reiches verstrickte es mit den zänkischen griechischen Stadtstaaten. Die großen Invasionen von 490 und 480 v. Chr. — Marathon, Thermopylen, Salamis — scheiterten und verankerten „die Perserkriege“ im griechischen Gedächtnis als Triumph freier Bürger über die Untertanen eines Königs. Die Wirklichkeit war feiner: Persien blieb weitere 150 Jahre die beherrschende Macht des östlichen Mittelmeers, finanzierte und schlichtete griechische Streitigkeiten.\n\nDas Ende kam aus dem Nordwesten. Zwischen 334 und 330 v. Chr. zerschlug Alexander von Makedonien die Heere Dareios' III. bei Granikos, Issos und Gaugamela und brannte Persepolis nieder. Doch der Eroberer regierte wie die Achämeniden — durch Satrapien, Tribut und Toleranz —, ein Beweis, dass Persien die Vorlage des Imperiums erfunden hatte, die alle nach ihm kopieren würden.",
      "Der Kern des achämenidischen Heeres war das Elitekorps, das die Griechen die Zehntausend Unsterblichen nannten — so genannt, weil seine Stärke stets bei genau 10.000 gehalten wurde, jeder Gefallene sofort ersetzt. Hinter ihnen marschierte eine wahrhaft imperiale Streitmacht: medische Reiterei, babylonische Bogenschützen, baktrische Kamelreiter, ägyptische Seesoldaten — jedes Kontingent in Landestracht unter eigenen Offizieren, das ganze Heer ein Abbild des Reiches selbst. Persiens wahres militärisches Genie aber war die Infrastruktur: Königsstraßen, die Heere in Wochen verschoben, Nachschublager, die Hunderttausende speisten, und eine Flotte aus phönizischen und griechischen Untertanengeschwadern. Persien zog gewöhnlich Gold den Pfeilen vor — es finanzierte eine griechische Stadt gegen die andere, bis, wie ein spartanischer König klagte, ihn „zehntausend persische Bogenschützen“ aus Asien vertrieben: der auf jedem goldenen Dareikos geprägte Bogenschütze.",
    ],
    fr: [
      "En une seule génération (550–530 av. J.-C.), Cyrus II de Perse engloutit les empires mède, lydien et néo-babylonien pour créer quelque chose de nouveau dans l'histoire du monde : un État couvrant presque toutes les terres civilisées du Proche-Orient. Ce qui rendait Cyrus révolutionnaire n'était pas la conquête mais le gouvernement. Au lieu de déporter les peuples et de fracasser les temples à la manière assyrienne, il confirma les clergés locaux, respecta les coutumes locales et laissa les exilés juifs de Babylone rentrer reconstruire le temple de Jérusalem.\n\nLe cylindre de Cyrus, proclamation d'argile de son règne à Babylone, est souvent décrit comme une charte précoce de tolérance. L'empire qu'il fonda serait gouverné selon ce principe : la diversité sous un seul roi des rois.",
      "Darius Ier (r. 522–486 av. J.-C.) fit des conquêtes un système. Il divisa l'empire en une vingtaine de satrapies, chacune sous un gouverneur (satrape) qui percevait un tribut fixe — or de l'Inde, chevaux de Cilicie, grain d'Égypte. Des inspecteurs royaux, « les yeux et les oreilles du roi », parcouraient les provinces pour brider l'ambition et la corruption.\n\nDarius standardisa la monnaie d'or (le darique), creusa un canal du Nil à la mer Rouge et bâtit la Route royale de Sardes à Suse, sur laquelle des courriers montés relayaient les messages en une semaine environ — trajet que les voyageurs ordinaires mettaient trois mois à parcourir. La description admirative d'Hérodote de ces courriers — « ni la neige, ni la pluie, ni la chaleur, ni l'obscurité de la nuit » — sert encore de devise postale aujourd'hui.",
      "Sur une grande terrasse de pierre au cœur de la Perse, Darius entreprit Persépolis — capitale cérémonielle de salles d'audience dont les colonnes s'élevaient à vingt mètres, couronnées de chapiteaux à double taureau. Ses escaliers portent des processions sculptées des peuples de l'empire : Babyloniens avec des tissus, Lydiens avec des vases, Éthiopiens avec de l'ivoire — chacun en costume national, apportant le tribut à la fête du Nouvel An. Nulle part l'idée impériale d'unité dans la diversité n'est gravée plus clairement.\n\nLa religion perse suivait le prophète Zoroastre, dont l'enseignement voyait l'existence comme une lutte morale entre la vérité (asha) et le mensonge (druj) sous le sage seigneur Ahura Mazda. Les idées zoroastriennes — une bataille cosmique du bien et du mal, un jugement après la mort, un renouvellement final du monde — résonneraient dans le judaïsme, le christianisme et l'islam.",
      "La portée occidentale de l'empire l'empêtra avec les turbulentes cités-États grecques. Les grandes invasions de 490 et 480 av. J.-C. — Marathon, les Thermopyles, Salamine — échouèrent, fixant « les guerres médiques » dans la mémoire grecque comme le triomphe de citoyens libres sur les sujets d'un roi. La réalité était plus subtile : la Perse resta la puissance dominante de la Méditerranée orientale pendant encore 150 ans, finançant et arbitrant les querelles grecques.\n\nLa fin vint du nord-ouest. Entre 334 et 330 av. J.-C., Alexandre de Macédoine fracassa les armées de Darius III au Granique, à Issos et à Gaugamèles, et incendia Persépolis. Pourtant le conquérant gouverna comme les Achéménides — par satrapies, tribut et tolérance — preuve que la Perse avait inventé le modèle d'empire que tous copieraient après elle.",
      "Le cœur de l'armée achéménide était le corps d'élite que les Grecs appelaient les Dix Mille Immortels — ainsi nommés parce que leur effectif était toujours maintenu à exactement 10 000, chaque homme tombé aussitôt remplacé. Derrière eux marchait une force véritablement impériale : cavalerie mède, archers babyloniens, cavaliers de chameaux bactriens, fantassins de marine égyptiens — chaque contingent en costume national sous ses propres officiers, l'armée entière un portrait de l'empire lui-même. Mais le vrai génie militaire de la Perse était l'infrastructure : routes royales déplaçant les armées en semaines, dépôts nourrissant des centaines de milliers d'hommes, et une flotte de escadres sujettes phéniciennes et grecques. La Perse préférait d'ordinaire l'or aux flèches — finançant une cité grecque contre une autre jusqu'à ce que, comme s'en plaignit un roi spartiate, il fût chassé d'Asie par « dix mille archers perses » : l'archer frappé sur chaque darique d'or.",
    ],
  },
  'medieval-01': {
    de: [
      "Im 5. Jahrhundert n. Chr. zerbröckelte das Weströmische Reich unter dem Druck germanischer Stämme, wirtschaftlichem Zusammenbruch und politischer Instabilität. 410 n. Chr. plünderten die Westgoten Rom — ein Ereignis, das die antike Welt erschütterte. 476 n. Chr. setzte der germanische Heerführer Odoaker den letzten weströmischen Kaiser ab, das herkömmliche Ende Roms.\n\nGermanische Königreiche — Franken, Westgoten, Ostgoten — ersetzten die römischen Provinzen. Die katholische Kirche wahrte die Kontinuität, bewahrte die lateinische Schriftkultur und leistete soziale Dienste im ganzen ehemaligen Reich.",
      "Der Frankenkönig Karl der Große (reg. 768–814 n. Chr.) einte durch Eroberung weite Teile Westeuropas. Am Weihnachtstag 800 krönte Papst Leo III. ihn zum „Kaiser der Römer“. Karl förderte die Bildung, vereinheitlichte Maße und Gewichte und holte Gelehrte an seinen Hof in Aachen.\n\nDie karolingische Renaissance half, klassische Texte zu bewahren. Nach Karls Tod wurde sein Reich unter seinen Enkeln im Vertrag von Verdun (843) geteilt und schuf die groben Umrisse des heutigen Frankreich und Deutschland.",
      "Die mittelalterliche europäische Gesellschaft ordnete sich um den Feudalismus — ein hierarchisches System aus Grundbesitz und Kriegsdienstpflicht. Könige verliehen Adligen Land gegen Kriegsdienst. Adlige gaben es an Ritter weiter; Bauern (Leibeigene) bearbeiteten das Land gegen Schutz. Das Herrengut — ein selbstversorgender Betrieb — war die wirtschaftliche Grundeinheit.\n\nDie katholische Kirche stand abseits — und oft über — dieser weltlichen Hierarchie. Klöster bewahrten Handschriften, führten Schulen und betrieben Hospitäler. Diese Verflechtung von geistlicher und weltlicher Macht prägte die mittelalterliche europäische Zivilisation.",
      "Während Westrom zerfiel, überdauerte das Oströmische Reich — das Byzantinische Reich — weitere tausend Jahre, ehe es 1453 den osmanischen Türken fiel. Konstantinopel (das heutige Istanbul), 330 n. Chr. von Kaiser Konstantin am Bosporus erbaut, war jahrhundertelang Europas größte und reichste Stadt. Unter Kaiser Justinian I. (reg. 527–565 n. Chr.) eroberte Byzanz weite Teile des früheren Westreichs zurück und schuf die Hagia Sophia — seine prächtige Kuppelkirche — sowie das Corpus Juris Civilis, eine systematische Kodifizierung des römischen Rechts.\n\nByzanz war eine entscheidende kulturelle Brücke. Griechische und römische Klassiker blieben in byzantinischen Bibliotheken erhalten, als die westliche Bildung stark zurückgegangen war. Byzantinische Gelehrte, die im 15. Jahrhundert dem osmanischen Vormarsch entflohen, brachten Handschriften nach Italien und trugen so zum Auslösen der Renaissance bei. Die byzantinische Kunst — ikonische Mosaiken aus Gold und satter Farbe — prägte eine Tradition, die sich über Osteuropa und Russland verbreitete, wo das orthodoxe Christentum tiefe Wurzeln schlug.",
      "Zwischen etwa 793 und 1100 n. Chr. entfesselten die Nordvölker Skandinaviens eine dramatische Expansion über Europa hinaus. Ihre Langschiffe — flachgehende, hochseetüchtige Boote, die offene See wie Flüsse befahren konnten — verliehen ihnen beispiellose Beweglichkeit. Der Überfall von 793 auf das Kloster Lindisfarne kündigte einem entsetzten Europa die Wikingerzeit an.\n\nDoch die Wikinger waren mehr als Räuber. Nordische Händler erschlossen Routen von der Ostsee bis nach Konstantinopel und Bagdad. Schwedisch-nordische (warägische) Krieger gründeten den Rus-Staat — Vorfahr Russlands und der Ukraine — um Nowgorod und Kiew. Norwegische Wikinger besiedelten Island, Grönland, und um 1000 n. Chr. erreichte Leif Eriksson Nordamerika — fünf Jahrhunderte vor Kolumbus. Nordische Siedler in Nordfrankreich wurden zu den Normannen, die 1066 England eroberten und dessen Kultur, Sprache und Herrschaft verwandelten.",
    ],
    fr: [
      "Au Ve siècle, l'Empire romain d'Occident s'effritait sous la pression des tribus germaniques, de l'effondrement économique et de l'instabilité politique. En 410, les Wisigoths pillèrent Rome — événement qui choqua le monde antique. En 476, le chef germanique Odoacre déposa le dernier empereur d'Occident, marquant la fin traditionnelle de Rome.\n\nDes royaumes germaniques — Francs, Wisigoths, Ostrogoths — remplacèrent les provinces romaines. L'Église catholique maintint la continuité, préservant la culture écrite latine et assurant des services sociaux à travers l'ancien empire.",
      "Le roi franc Charlemagne (r. 768–814) réunifia une grande partie de l'Europe occidentale par la conquête. Le jour de Noël 800, le pape Léon III le couronna « empereur des Romains ». Charlemagne encouragea l'éducation, uniformisa poids et mesures et attira des savants à sa cour d'Aix-la-Chapelle.\n\nLa renaissance carolingienne aida à préserver les textes classiques. À la mort de Charlemagne, son empire fut partagé entre ses petits-fils par le traité de Verdun (843), esquissant les contours de la France et de l'Allemagne modernes.",
      "La société médiévale européenne s'organisa autour de la féodalité — un système hiérarchique de propriété foncière et d'obligation militaire. Les rois octroyaient des terres aux nobles en échange du service militaire. Les nobles les sous-inféodaient aux chevaliers ; les paysans (serfs) travaillaient la terre en échange de protection. Le manoir — un domaine autosuffisant — était l'unité économique de base.\n\nL'Église catholique se tenait à l'écart — et souvent au-dessus — de cette hiérarchie séculière. Les monastères préservaient les manuscrits, tenaient des écoles et fournissaient des hôpitaux. Cet entrelacement du pouvoir religieux et séculier définit la civilisation médiévale européenne.",
      "Tandis que Rome d'Occident s'effondrait, l'Empire romain d'Orient — l'Empire byzantin — survécut mille ans de plus, tombant enfin devant les Turcs ottomans en 1453. Constantinople (l'actuelle Istanbul), bâtie par l'empereur Constantin en 330 sur le Bosphore, fut des siècles durant la plus grande et la plus riche ville d'Europe. Sous l'empereur Justinien Ier (r. 527–565), Byzance reconquit une grande part de l'ancien Empire d'Occident et produisit Sainte-Sophie — sa magnifique église à coupole — et le Corpus Juris Civilis, codification systématique du droit romain.\n\nByzance servit de pont culturel décisif. Les classiques grecs et romains furent préservés dans les bibliothèques byzantines quand la culture écrite occidentale avait fortement décliné. Des savants byzantins fuyant l'avancée ottomane au XVe siècle apportèrent des manuscrits en Italie, contribuant à déclencher la Renaissance. L'art byzantin — mosaïques emblématiques d'or et de couleurs riches — définit une tradition qui se répandit à travers l'Europe de l'Est et la Russie, où le christianisme orthodoxe s'enracina profondément.",
      "Entre 793 et 1100 environ, les peuples nordiques de Scandinavie lancèrent une expansion spectaculaire à travers l'Europe et au-delà. Leurs langskips — vaisseaux à faible tirant d'eau, dignes de l'océan, capables de naviguer en haute mer comme sur les rivières — leur donnaient une mobilité sans égale. Le raid de 793 sur le monastère de Lindisfarne annonça l'âge viking à une Europe horrifiée.\n\nMais les Vikings étaient plus que des pillards. Des marchands nordiques établirent des routes de la Baltique à Constantinople et Bagdad. Des guerriers suédo-nordiques (varègues) fondèrent l'État de la Rus — ancêtre de la Russie et de l'Ukraine — autour de Novgorod et de Kiev. Des Vikings norvégiens colonisèrent l'Islande, le Groenland, et vers l'an 1000, Leif Erikson atteignit l'Amérique du Nord — cinq siècles avant Colomb. Les colons nordiques du nord de la France devinrent les Normands, qui conquirent l'Angleterre en 1066 et en transformèrent la culture, la langue et le gouvernement.",
    ],
  },
  'medieval-02': {
    de: [
      "610 n. Chr. empfing der Kaufmann Mohammed in einer Höhle bei Mekka seine erste Offenbarung und begründete die Religion des Islam. Bei seinem Tod 632 n. Chr. war der Großteil Arabiens unter dem Islam geeint. Binnen eines Jahrhunderts hatten arabische Heere das Perserreich, Ägypten, Nordafrika und Spanien erobert — eine der raschesten imperialen Ausdehnungen der Geschichte.\n\nDie Kalifate der Umayyaden und Abbasiden schufen eine weite, kosmopolitische islamische Welt von der Atlantikküste bis nach Zentralasien. Arabisch wurde zur Sprache der Gelehrsamkeit, des Handels und der Religion und verband vielfältige Völker von Spanien bis Persien.",
      "Während Westeuropa sich langsam vom Fall Roms erholte, erlebte die islamische Welt ein Goldenes Zeitalter geistiger Leistungen (8.–13. Jahrhundert). Der Abbasidenhof in Bagdad wurde zum größten Zentrum der Gelehrsamkeit der Welt. Gelehrte übersetzten griechische Texte von Aristoteles, Euklid und Galen und bewahrten sie vor dem Verlust.\n\nIslamische Gelehrte leisteten eigenständige Beiträge in Mathematik (die Algebra entwickelte al-Chwarizmi), Astronomie, Medizin (Ibn Sinas Kanon der Medizin wurde jahrhundertelang an europäischen Universitäten verwendet) und Optik. Dieses Wissen floss später nach Europa zurück und half, die wissenschaftliche Revolution zu entzünden.",
      "1095 rief Papst Urban II. zu einem heiligen Krieg auf, um Jerusalem von den Seldschuken zurückzuerobern. Der Erste Kreuzzug gelang — Jerusalem fiel 1099 den Kreuzfahrern. Vier Kreuzfahrerstaaten entstanden im Heiligen Land. Doch die christliche Herrschaft erwies sich als brüchig; Saladin, der kurdische Sultan Ägyptens, nahm Jerusalem 1187 wieder ein.\n\nSieben große Kreuzzüge folgten über zwei Jahrhunderte. Militärisch letztlich gescheitert, prägten sie doch die europäische wie die islamische Zivilisation zutiefst. Sie verstärkten den Handel mit dem Osten, führten Europäer an islamische Gelehrsamkeit und Waren heran und hinterließen tiefe religiöse Feindschaften, die jahrhundertelang nachhallten.",
      "Saladin (1137–1193), der kurdische Feldherr, der das muslimische Ägypten und Syrien einte, wurde einer der am meisten bewunderten Herrscher der mittelalterlichen Welt — von Christen wie Muslimen. 1187 nahmen seine Truppen Jerusalem zurück und behandelten die christlichen Bewohner mit einer Milde, die im scharfen Gegensatz zum Massaker bei der Einnahme der Stadt durch den Ersten Kreuzzug stand. Der Dritte Kreuzzug führte Europas größte Kriegerkönige — Richard I. von England und Philipp II. von Frankreich — ins Heilige Land.\n\nDas legendäre Duell zwischen Richard und Saladin endete mit einem Vertrag, der christlichen Pilgern Zugang zu Jerusalem gewährte. Die Kreuzzüge verdichteten den Begriff des Rittertums — ein Verhaltenskodex, der militärische Tüchtigkeit mit christlichen Idealen und höfischer Höflichkeit verband. Ritterorden wie die Templer und Johanniter verbanden klösterliche Disziplin mit kriegerischem Können und verkörperten Ideale, die die europäische Adelskultur jahrhundertelang prägten.",
      "Die Kreuzzüge verstärkten den Handel zwischen Europa und der islamischen Welt dramatisch. Italienische Stadtstaaten — Venedig, Genua, Pisa — stellten Transport für Kreuzfahrer gegen Handelsrechte in östlichen Häfen. Venezianische Kaufleute führten Gewürze, Seide, Glas und Luxusgüter ein, die Italien bereicherten und die europäische Konsumkultur verwandelten.\n\nDieser Reichtum befeuerte eine städtische Handelsrevolution. Norditalienische Städte entwickelten ausgefeilte Finanzinstrumente: Kreditbriefe, doppelte Buchführung, Seeversicherung und frühes Bankwesen. Die Medici in Florenz waren Bankiers für Päpste und Könige. Diese kaufmännische Raffinesse schuf das Kapital und die unternehmerische Kultur, die die Renaissance finanzieren sollten — ein Beweis, dass das mittelalterliche Europa weit dynamischer war, als die Klischees vom „dunklen Zeitalter“ vermuten lassen.",
    ],
    fr: [
      "En 610, le marchand Mahomet reçut sa première révélation dans une grotte près de La Mecque, fondant la religion de l'islam. À sa mort en 632, l'essentiel de l'Arabie était unifié sous l'islam. En un siècle, les armées arabes avaient conquis l'Empire perse, l'Égypte, l'Afrique du Nord et l'Espagne — l'une des expansions impériales les plus rapides de l'histoire.\n\nLes califats omeyyade et abbasside créèrent un vaste monde islamique cosmopolite, de l'Atlantique à l'Asie centrale. L'arabe devint la langue du savoir, du commerce et de la religion, liant des peuples divers de l'Espagne à la Perse.",
      "Tandis que l'Europe occidentale se remettait lentement de la chute de Rome, le monde islamique connut un âge d'or de réalisations intellectuelles (VIIIe–XIIIe siècles). La cour abbasside de Bagdad devint le plus grand centre de savoir du monde. Des savants traduisirent les textes grecs d'Aristote, d'Euclide et de Galien, les sauvant de la perte.\n\nLes savants islamiques firent des contributions originales en mathématiques (l'algèbre fut développée par al-Khwarizmi), en astronomie, en médecine (le Canon de la médecine d'Ibn Sina fut utilisé des siècles dans les universités européennes) et en optique. Ce savoir reflua plus tard vers l'Europe, aidant à allumer la révolution scientifique.",
      "En 1095, le pape Urbain II appela à une guerre sainte pour reprendre Jérusalem aux Turcs seldjoukides. La première croisade réussit — Jérusalem tomba aux mains des croisés en 1099. Quatre États latins furent établis en Terre sainte. Mais le contrôle chrétien se révéla fragile ; Saladin, le sultan kurde d'Égypte, reprit Jérusalem en 1187.\n\nSept grandes croisades suivirent sur deux siècles. Bien qu'échouant militairement, elles façonnèrent profondément les civilisations européenne et islamique. Elles intensifièrent le commerce avec l'Orient, initièrent les Européens au savoir et aux produits islamiques, et laissèrent de profondes haines religieuses qui résonnèrent des siècles durant.",
      "Saladin (1137–1193), le général kurde qui unifia l'Égypte et la Syrie musulmanes, devint l'un des souverains les plus admirés du monde médiéval — par les chrétiens comme par les musulmans. En 1187, ses forces reprirent Jérusalem, traitant les habitants chrétiens avec une clémence qui contrastait nettement avec le massacre ayant accompagné la prise de la ville lors de la première croisade. La troisième croisade amena en Terre sainte les plus grands rois-guerriers d'Europe — Richard Ier d'Angleterre et Philippe II de France.\n\nLe duel légendaire de Richard et Saladin s'acheva par un traité autorisant l'accès des pèlerins chrétiens à Jérusalem. Les croisades cristallisèrent le concept de chevalerie — un code de conduite alliant prouesse militaire, idéaux chrétiens et courtoisie de cour. Des ordres militaires comme les Templiers et les Hospitaliers mêlaient discipline monastique et expertise martiale, incarnant des idéaux qui façonnèrent la culture aristocratique européenne pour des siècles.",
      "Les croisades intensifièrent spectaculairement le commerce entre l'Europe et le monde islamique. Des cités italiennes — Venise, Gênes, Pise — assuraient le transport des croisés en échange de droits commerciaux dans les ports orientaux. Les marchands vénitiens importaient épices, soie, verre et produits de luxe qui enrichirent l'Italie et transformèrent la culture de consommation européenne.\n\nCette richesse alimenta une révolution commerciale urbaine. Les villes du nord de l'Italie développèrent des instruments financiers sophistiqués : lettres de crédit, comptabilité en partie double, assurance maritime et banque naissante. Les Médicis de Florence étaient banquiers des papes et des rois. Cette sophistication commerciale créa le capital et la culture entrepreneuriale qui financeraient la Renaissance — montrant que l'Europe médiévale était bien plus dynamique que ne le suggèrent les clichés d'« âge sombre ».",
    ],
  },
  'medieval-03': {
    de: [
      "Der Schwarze Tod — verursacht durch das Bakterium Yersinia pestis, übertragen von Flöhen auf Ratten — entstand um 1340 in Zentralasien. Entlang der Handelswege verbreitet, erreichte er 1346 die Schwarzmeerhäfen und gelangte im Oktober 1347 über Sizilien nach Europa. Binnen fünf Jahren war er von Portugal bis Polen gefegt.\n\nDie Seuche trat in drei Formen auf: Beulenpest (geschwollene Lymphknoten), Lungenpest (Lungeninfektion) und Pestsepsis (Blutinfektion). Die zeitgenössische Medizin war machtlos. Städte traf es am härtesten — London verlor womöglich die Hälfte seiner Bevölkerung; Florenz verlor 60 %.",
      "Auf ihrem Höhepunkt tötete der Schwarze Tod täglich Tausende in den großen Städten. Die Leichen häuften sich schneller, als sie bestattet werden konnten. Die soziale Ordnung brach zusammen; Priester verweigerten die Sterbesakramente, Ärzte flohen. Manche wandten sich Geißlerbewegungen zu — öffentlich geißelten sie sich zur Buße. Paranoide Gemeinschaften massakrierten jüdische Bevölkerungen und beschuldigten sie fälschlich, Brunnen vergiftet zu haben.\n\nAls die schlimmsten Wellen in den 1350er Jahren vorübergezogen waren, hatte Europa zwischen einem Drittel und der Hälfte seiner Bevölkerung verloren. Das seelische Trauma war ungeheuer. Kunst und Literatur waren durchtränkt von Todesbildern; der „Totentanz“ (danse macabre) wurde zu einem beliebten Motiv, das eine von der Willkür der Sterblichkeit zutiefst erschütterte Gesellschaft spiegelte.",
      "Die Folgen der Pest verwandelten die europäische Gesellschaft. Da so viele Bauern gestorben waren, konnten die Überlebenden höhere Löhne und bessere Bedingungen fordern. Die Leibeigenschaft ging in Westeuropa rasch zurück. Der englische Bauernaufstand von 1381 zeigte, dass die Unterschichten ihre überlieferte Stellung nicht länger hinzunehmen bereit waren.\n\nDie Kirche, die die Katastrophe weder erklären noch aufhalten konnte, verlor an Ansehen. Das Hinterfragen kirchlicher Autorität half, den Boden für die Renaissance und später die Reformation zu bereiten. Widersinnig beschleunigte der Arbeitskräftemangel die technische Innovation — arbeitssparende Geräte wurden wirtschaftlich wertvoller, darunter die Druckerpresse.",
      "Zeitgleich mit dem Schwarzen Tod führten England und Frankreich den Hundertjährigen Krieg — eine Reihe von Konflikten um englische Ansprüche auf den französischen Thron, die 116 Jahre dauerten. Englische Langbogenschützen verwüsteten die französische Reiterei bei Crécy (1346) und Azincourt (1415), wo Heinrichs V. zahlenmäßig unterlegene Truppen ein fünfmal so großes Heer in die Flucht schlugen. Englische Verbände drangen tief nach Frankreich vor und beherrschten auf ihrem Höhepunkt weite Teile des Landes.\n\nDer Wendepunkt des Krieges kam durch Jeanne d'Arc, ein jugendliches Bauernmädchen aus Domrémy, das göttliche Visionen für sich beanspruchte, die es befahlen, Frankreichs Heer zu führen. Die französischen Truppen kehrten das Blatt; Jeanne wurde von den Engländern gefangen und 1431 auf dem Scheiterhaufen verbrannt — doch ihre Feldzüge hatten die englische Vorherrschaft gebrochen. Bis 1453 hatte England alles französische Gebiet außer Calais verloren. Der Krieg zeigte, dass die Ära der schwer gepanzerten Ritter der Infanterie und Artillerie wich.",
      "Paradoxerweise halfen die Krisen des 14. Jahrhunderts — Pest, Krieg, Papstschisma —, die Bedingungen für die kulturelle Erneuerung der Renaissance zu schaffen. Der Schwarze Tod bewirkte gewaltige Vermögensübertragungen, als Überlebende den Besitz der Toten erbten; diese Kapitalbündelung finanzierte die Förderung von Kunst und Gelehrsamkeit. Der Ansehensverlust der Kirche ermutigte zum eigenständigen Denken.\n\nFrühe Humanisten wie Petrarca (1304–1374) — oft der „erste Renaissance-Mensch“ genannt — sammelten klassische Handschriften und stellten die Menschenwürde ins Zentrum ihres Weltbilds. Boccaccios Decamerone schilderte den Schwarzen Tod und feierte zugleich Witz und menschliche Widerstandskraft. In der Kunst brach Giotto mit der byzantinischen Flächigkeit und stellte dreidimensionale, gefühlsstarke Figuren dar — eine Revolution, die dem Renaissance-Naturalismus die Tür öffnete. Die spätmittelalterliche Kultur, alles andere als bloß dunkel, war schwanger mit den kommenden Umwälzungen.",
    ],
    fr: [
      "La Peste noire — causée par la bactérie Yersinia pestis, transportée par les puces des rats — naquit en Asie centrale vers 1340. Se propageant par les routes commerciales, elle atteignit les ports de la mer Noire en 1346 et entra en Europe par la Sicile en octobre 1347. En cinq ans, elle avait balayé du Portugal à la Pologne.\n\nLa maladie prit trois formes : peste bubonique (ganglions enflés), peste pulmonaire (infection des poumons) et peste septicémique (infection du sang). La médecine de l'époque était impuissante. Les villes furent les plus touchées — Londres perdit peut-être la moitié de sa population ; Florence perdit 60 %.",
      "À son apogée, la Peste noire tuait des milliers de personnes par jour dans les grandes villes. Les corps s'entassaient plus vite qu'on ne pouvait les enterrer. L'ordre social s'effondra ; les prêtres refusaient les derniers sacrements, les médecins fuyaient. Certains se tournèrent vers les mouvements de flagellants — se fouettant publiquement en pénitence. Des communautés paranoïaques massacrèrent des populations juives, les accusant à tort d'empoisonner les puits.\n\nQuand les pires vagues passèrent dans les années 1350, l'Europe avait perdu entre un tiers et la moitié de sa population. Le traumatisme psychologique fut immense. L'art et la littérature se saturèrent d'images de mort ; la « danse macabre » devint un motif populaire reflétant une société profondément ébranlée par le caractère aléatoire de la mort.",
      "Les suites de la peste transformèrent la société européenne. Tant de paysans étant morts, les survivants pouvaient exiger des salaires plus élevés et de meilleures conditions. Le servage déclina rapidement en Europe occidentale. La révolte des paysans anglais de 1381 montra que les classes populaires n'acceptaient plus leur condition traditionnelle.\n\nL'Église, qui n'avait su ni expliquer ni arrêter la catastrophe, perdit son prestige. La remise en cause de l'autorité de l'Église aida à préparer le terrain de la Renaissance puis de la Réforme protestante. Paradoxalement, la pénurie de main-d'œuvre accéléra l'innovation technologique — les dispositifs économisant le travail gagnèrent en valeur, dont l'imprimerie.",
      "Concomitamment à la Peste noire, l'Angleterre et la France livrèrent la guerre de Cent Ans — une série de conflits sur les prétentions anglaises au trône de France, durant 116 ans. Les archers anglais dévastèrent la cavalerie française à Crécy (1346) et à Azincourt (1415), où les forces d'Henri V, en infériorité, mirent en déroute une armée cinq fois supérieure. Les armées anglaises pénétrèrent profondément en France et contrôlèrent à leur apogée une grande partie du pays.\n\nLe tournant de la guerre vint par Jeanne d'Arc, une jeune paysanne de Domrémy affirmant des visions divines lui ordonnant de mener l'armée de France. Les forces françaises renversèrent la vapeur ; Jeanne fut capturée par les Anglais et brûlée vive en 1431 — mais ses campagnes avaient brisé la domination anglaise. En 1453, l'Angleterre avait perdu tout territoire français hormis Calais. La guerre montra que l'ère des chevaliers lourdement cuirassés cédait la place à l'infanterie et à l'artillerie.",
      "Paradoxalement, les crises du XIVe siècle — peste, guerre, schisme pontifical — aidèrent à produire les conditions du renouveau culturel de la Renaissance. La Peste noire provoqua d'énormes transferts de richesse quand les survivants héritèrent des biens des morts ; cette concentration de capital finança le mécénat des arts et du savoir. La perte de prestige de l'Église encouragea la pensée indépendante.\n\nDes humanistes précoces comme Pétrarque (1304–1374) — souvent appelé le « premier homme de la Renaissance » — collectionnaient les manuscrits classiques et plaçaient la dignité humaine au centre de leur vision du monde. Le Décaméron de Boccace dépeignait la Peste noire tout en célébrant l'esprit et la résilience humaine. En art, Giotto rompit avec la platitude byzantine pour représenter des figures tridimensionnelles et expressives — une révolution qui ouvrit la porte au naturalisme de la Renaissance. La culture de la fin du Moyen Âge, loin d'être simplement sombre, était grosse des transformations à venir.",
    ],
  },
  'medieval-04': {
    de: [
      "Das Frühmittelalter (ca. 500–1000 n. Chr.) erlebte nach dem Fall Roms einen dramatischen Rückgang des europäischen Handels. Lokale Herren wurden auf ihren Gütern selbstversorgend; der Fernhandel verschwand fast völlig. Doch ab etwa 1000 n. Chr. besserten sich die Verhältnisse: Das Klima erwärmte sich leicht (die mittelalterliche Warmzeit), die Bevölkerung wuchs, und landwirtschaftliche Überschüsse schufen Nachfrage nach Gütern über das Existenzminimum hinaus.\n\nKaufleute begannen, regelmäßige Rundreisen zwischen wachsenden Städten zu unternehmen. Wochenmärkte und Jahrmessen vervielfachten sich. Die großen Champagne-Messen im Nordosten Frankreichs wurden zum Handelsdrehkreuz Europas und zogen Händler aus Italien, Flandern, Deutschland und der Levante an. Hier wechselten Seide und Gewürze aus dem Osten den Besitzer gegen flämische Wolle, venezianisches Glas und deutsche Metallarbeit. Eine Handelsrevolution war im Gange.",
      "Um diese Handelsausweitung zu regeln, schlossen sich Handwerker und Kaufleute zu Zünften zusammen — Verbände, die den Zugang zu den Gewerben kontrollierten, Qualitätsnormen setzten und die nächste Generation ausbildeten. Zünfte umfassten alles von Bäckern und Metzgern bis zu Goldschmieden und Wundärzten. Meister zu werden erforderte Jahre: zuerst als Lehrling (im Haushalt des Meisters lebend), dann als Geselle (bezahlter Tagelöhner) und schließlich mit einer Meisterprüfung, um als Vollmitglied in die Zunft einzutreten.\n\nZünfte schützten ihre Mitglieder vor auswärtiger Konkurrenz, legten Lehrzeiten fest, setzten Löhne und erzwangen Qualitätsnormen — Prüfer konnten minderwertige Waren beschlagnahmen oder vernichten. Doch sie erfüllten auch soziale Aufgaben: Sie unterstützten kranke Mitglieder, förderten religiöse Feiern, organisierten aufwendige Festzüge und Mysterienspiele. Das Zunftwesen prägte das städtische Wirtschaftsleben vom 12. Jahrhundert an, bis die industrielle Revolution es überflüssig machte.",
      "In Nordeuropa bildeten deutsche Kaufmannsstädte die Hanse — ein Handelsbündnis, das schließlich über 200 Städte von London bis Nowgorod umfasste und über zwei Jahrhunderte den Ostsee- und Nordseehandel beherrschte. Lübeck war die informelle Hauptstadt des Bundes; Hamburg, Bremen, Danzig und Riga waren Schlüsselmitglieder.\n\nHansekaufleute entwickelten ausgefeilte Handelspraktiken: einheitliche Maße und Gewichte, Handelsverträge, Frachtversicherung und Kaufmannsgerichte zur Streitbeilegung. Hanse-Handelsniederlassungen (Kontore) in London, Brügge, Bergen und Nowgorod waren regelrechte Städte in der Stadt, mit eigenen Lagerhäusern, Kirchen und Rechtsprivilegien. Der Erfolg der Hanse zeigte, dass mittelalterliche Menschen zu außerordentlicher kaufmännischer Raffinesse fähig waren — die Wurzeln des modernen Kapitalismus reichten tief in die mittelalterliche Stadt.",
      "Die Beulenpest gelangte 1347 aus Zentralasien nach Europa, getragen von Flöhen auf Ratten an Bord genuesischer Handelsschiffe. Binnen vier Jahren tötete sie zwischen 30 und 60 Prozent der Bevölkerung Europas — vielleicht 25 Millionen Menschen. Ganze Dörfer verschwanden. Das englische Dorf Eyam würde sich später während der Pest von 1665 vollständig abriegeln, um deren Ausbreitung zu verhindern.\n\nDie demografische Katastrophe verwandelte die Wirtschaft. Da Arbeitskräfte plötzlich knapp waren, konnten überlebende Bauern höhere Löhne und bessere Bedingungen fordern — ein wesentlicher Faktor beim Niedergang der Leibeigenschaft. Grundherren rangen um Arbeiter; manche Bauern wurden erstmals Freibauern. Die Pest erschütterte auch die überkommene Autorität, untergrub das Vertrauen in die Schutzmacht der Kirche und beschleunigte womöglich die gesellschaftlichen Veränderungen, die in Renaissance und Reformation gipfeln sollten. Die Katastrophe half paradoxerweise, die moderne Welt zu gebären.",
      "Mittelalterliche Kaufleute brauchten ausgefeilte Finanzwerkzeuge. Die Kirche verdammte das Verleihen gegen Zins als „Wucher“, doch clevere Bankiers fanden Umwege. Italienische Kaufleute erfanden den Wechsel — eine schriftliche Anweisung, mit der Kaufleute Kredit über Städte hinweg übertragen konnten, ohne Gold physisch zu bewegen, was das Raubrisiko auf mittelalterlichen Straßen drastisch senkte.\n\nDie Medici in Florenz stiegen zur beherrschenden Finanzmacht des 15. Jahrhunderts auf. Ihr Bankennetz spannte sich über Europa und finanzierte Päpste, Könige und Kaufleute. Giovanni di Bicci de' Medici und seine Nachfahren entwickelten die doppelte Buchführung, Filialstrukturen zur Haftungsbegrenzung und ausgefeilte Kreditinstrumente. Cosimo de' Medici wurde faktischer Herrscher von Florenz — ein Beweis, dass Finanzmacht der militärischen Macht ebenbürtig sein konnte. Die Medici-Förderung von Kunst und Gelehrsamkeit machte Florenz zur Wiege der Renaissance und verband kaufmännische Neuerung unmittelbar mit kultureller Revolution.",
    ],
    fr: [
      "Le haut Moyen Âge (v. 500–1000) vit le commerce européen se contracter fortement après la chute de Rome. Les seigneurs locaux devinrent autosuffisants sur leurs manoirs ; le commerce à longue distance disparut presque. Mais à partir de l'an 1000 environ, les conditions s'améliorèrent : le climat se réchauffa légèrement (l'optimum climatique médiéval), la population crût, et les surplus agricoles créèrent une demande de biens au-delà de la subsistance.\n\nLes marchands se mirent à parcourir des circuits réguliers entre les villes en croissance. Marchés hebdomadaires et foires annuelles se multiplièrent. Les grandes foires de Champagne, dans le nord-est de la France, devinrent le carrefour commercial de l'Europe, attirant des marchands d'Italie, de Flandre, d'Allemagne et du Levant. Là, soie et épices d'Orient s'échangeaient contre laine flamande, verre vénitien et métallerie allemande. Une révolution commerciale était en marche.",
      "Pour réguler cette expansion commerciale, artisans et marchands formèrent des guildes — associations qui contrôlaient l'accès aux métiers, fixaient des normes de qualité et formaient la génération suivante. Les guildes englobaient tout, des boulangers et bouchers aux orfèvres et chirurgiens. Devenir maître exigeait des années : d'abord apprenti (vivant dans la famille du maître), puis compagnon (journalier payé), et enfin réussir un chef-d'œuvre pour rejoindre la guilde comme membre à part entière.\n\nLes guildes protégeaient leurs membres de la concurrence extérieure, fixaient l'âge d'apprentissage, réglaient les salaires et imposaient des normes de qualité — les inspecteurs pouvaient saisir ou détruire les biens défectueux. Mais elles remplissaient aussi des fonctions sociales : soutenant les membres malades, parrainant les célébrations religieuses, organisant fastes cortèges et mystères. Le système des guildes façonna la vie économique urbaine du XIIe siècle jusqu'à ce que la révolution industrielle le rende obsolète.",
      "En Europe du Nord, les villes marchandes allemandes formèrent la Hanse — une alliance commerciale qui finit par englober plus de 200 villes de Londres à Novgorod, dominant le commerce de la Baltique et de la mer du Nord pendant plus de deux siècles. Lübeck en était la capitale informelle ; Hambourg, Brême, Dantzig et Riga en étaient des membres clés.\n\nLes marchands hanséates développèrent des pratiques commerciales sophistiquées : poids et mesures standardisés, contrats commerciaux, assurance de cargaison et tribunaux marchands pour trancher les litiges. Les comptoirs hanséates (Kontore) à Londres, Bruges, Bergen et Novgorod étaient de véritables villes dans les villes, avec leurs entrepôts, églises et privilèges juridiques. Le succès de la Hanse montra que les gens du Moyen Âge étaient capables d'une extraordinaire sophistication commerciale — les racines du capitalisme moderne plongeaient profondément dans la ville médiévale.",
      "La peste bubonique arriva en Europe depuis l'Asie centrale en 1347, portée par les puces des rats à bord de navires génois. En quatre ans, elle tua entre 30 et 60 pour cent de la population européenne — peut-être 25 millions de personnes. Des villages entiers disparurent. Le village anglais d'Eyam se cloîtrerait plus tard entièrement lors de la peste de 1665 pour empêcher sa propagation.\n\nLa catastrophe démographique transforma l'économie. La main-d'œuvre devenant soudain rare, les paysans survivants purent exiger des salaires plus élevés et de meilleures conditions — facteur majeur du déclin du servage. Les seigneurs se disputaient les travailleurs ; certains paysans devinrent propriétaires pour la première fois. La peste bouleversa aussi l'autorité traditionnelle, ébranla la foi dans le pouvoir protecteur de l'Église et accéléra peut-être les changements sociaux qui culmineraient dans la Renaissance et la Réforme. La catastrophe, paradoxalement, aida à enfanter le monde moderne.",
      "Les marchands médiévaux avaient besoin d'outils financiers sophistiqués. L'Église condamnait le prêt à intérêt comme « usure », mais d'astucieux banquiers trouvèrent des contournements. Les marchands italiens inventèrent la lettre de change — un ordre écrit permettant de transférer un crédit d'une ville à l'autre sans déplacer physiquement l'or, réduisant fortement le risque de vol sur les routes médiévales.\n\nLes Médicis de Florence s'élevèrent pour dominer la finance du XVe siècle. Leur réseau bancaire s'étendait à travers l'Europe, finançant papes, rois et marchands. Giovanni di Bicci de' Medici et ses descendants développèrent la comptabilité en partie double, des structures en succursales pour limiter le risque et des instruments de crédit sophistiqués. Cosme de Médicis devint le maître effectif de Florence — montrant que la puissance financière pouvait rivaliser avec la puissance militaire. Le mécénat des Médicis pour l'art et le savoir fit de Florence le berceau de la Renaissance, liant directement l'innovation commerciale à la révolution culturelle.",
    ],
  },
  'medieval-05': {
    de: [
      "In den rauen Steppen Zentralasiens wurde um 1162 n. Chr. ein Junge namens Temüdschin in einen unbedeutenden Mongolenclan geboren. Nach Jahren der Not — sein Vater von Rivalen vergiftet, Temüdschin selbst gefangen gehalten — stieg er durch eine Mischung aus außerordentlichem militärischem Talent, politischer Schläue und rücksichtsloser Entschlossenheit auf und einte die ewig verfeindeten Mongolenstämme.\n\n1206 wurde Temüdschin bei einer großen Versammlung (Kurultai) mongolischer Häuptlinge am Fluss Onon zum Dschingis Khan — „Universalherrscher“ — ausgerufen. Er verwandelte die versammelten Stämme sogleich in eine disziplinierte Kriegsmaschine, nach Dezimalprinzipien gegliedert: Einheiten von zehn, hundert, tausend und zehntausend. Die Treue galt der Einheit und dem Khan, nicht dem Clan — ein revolutionärer Wandel, der die Stammeskriege beendete, die die Mongolen über Generationen geschwächt hatten.",
      "Mongolische Heere waren die wirksamste Streitmacht der mittelalterlichen Welt und verbanden Beweglichkeit, Disziplin, psychologische Kriegsführung und taktische Raffinesse. Berittene Bogenschützen konnten 80–100 km am Tag zurücklegen und über weite Entfernungen operieren, die Infanteriearmeen lahmgelegt hätten. Vor einer Schlacht boten mongolische Gesandte den Städten eine krasse Wahl: sich ergeben und verschont bleiben oder Widerstand leisten und der völligen Vernichtung ins Auge sehen.\n\nStädte, die sich unterwarfen, wurden im Allgemeinen mit pragmatischer Milde behandelt — ihre Handwerker, Ingenieure und Verwalter wurden in die mongolische Staatsmaschine aufgenommen. Städte, die Widerstand leisteten, wurden als Warnung an andere geschleift. Als die große Stadt Zhongdu (das heutige Peking) 1215 fiel, berichteten ausländische Reisende, die Gebeine ihrer Bewohner hätten die Ebenen kilometerweit weiß gefärbt. Diese Verbindung von Milde und Schrecken erwies sich als verheerend wirksam: Die Nachricht von mongolischen Feldzügen bewog Städte oft, sich kampflos zu ergeben.",
      "Bei Dschingis Khans Tod 1227 beherrschten die Mongolen ein Reich, das sich von der Pazifikküste Chinas bis zum Kaspischen Meer erstreckte. Seine Nachfolger stießen noch weiter vor. Ögedei Khan vollendete die Eroberung Nordchinas; Batu Khan fegte durch Russland und Polen und erreichte die Adria, ehe er sich zurückzog. Hülegü Khan plünderte 1258 Bagdad, tötete den Abbasidenkalifen und beendete fünf Jahrhunderte islamischer kultureller Vorherrschaft.\n\nAuf seinem Höhepunkt war das Mongolenreich das größte zusammenhängende Landreich der Geschichte, 24 Millionen Quadratkilometer — etwa die Größe Afrikas. Es umfasste den Großteil der eurasischen Landmasse und hielt vielleicht 100 Millionen Menschen unter seiner Herrschaft. Kein Reich davor oder danach erreichte eine so rasche territoriale Ausdehnung über so vielfältige geografische und klimatische Zonen.",
      "Paradoxerweise schuf die zerstörerischste Eroberung der Geschichte eine ihrer fruchtbarsten Perioden des Kulturaustauschs. Die Pax Mongolica („Mongolischer Frieden“), etwa 1260–1350, vereinte erstmals die Handelswege Eurasiens unter einem einzigen politischen Dach. Kaufleute, Diplomaten, Missionare und Reisende konnten von China nach Europa mit relativer Sicherheit reisen und trugen Waren, Ideen, Techniken und Krankheiten die Seidenstraße entlang.\n\nMarco Polos berühmte Reise an den Hof Kublai Khans (1271–1295) war nur wegen der mongolischen Ordnung möglich. Chinesische Papierherstellung, Schießpulver und Drucktechniken wanderten westwärts; islamische Astronomie und Medizin ostwärts. Die Mongolenhöfe warben aktiv fähige Menschen ungeachtet von Religion oder Herkunft an — christliche Priester, muslimische Astronomen, chinesische Ingenieure und persische Bürokraten dienten alle am Yuan-Hof in Peking. Dieser kosmopolitische Austausch beschleunigte die technische und kommerzielle Entwicklung, die schließlich die europäische Renaissance und das Zeitalter der Entdeckungen befeuern sollte.",
      "Die mongolischen Eroberungen töteten schätzungsweise 40 Millionen Menschen — vielleicht 10 % der Weltbevölkerung — und veränderten die demografische Landschaft Zentralasiens und des Nahen Ostens dauerhaft. Irans Bevölkerung erholte sich womöglich 700 Jahre nicht auf das vormongolische Niveau. Die Zerstörung der Bewässerungssysteme Bagdads trug zum langfristigen landwirtschaftlichen Niedergang Mesopotamiens bei. Die einst großen Städte Zentralasiens — Samarkand, Buchara, Merw — erlangten ihre vormongolische Blüte nie ganz zurück.\n\nDoch die Mongolenherrschaft schuf auch. Kublai Khans Yuan-Dynastie (1271–1368) brachte China eine gewaltige wirtschaftliche Entwicklung: Papiergeld wurde vereinheitlicht, der Kaiserkanal verlängert und das Postrelaissystem (Yam) ermöglichte Kommunikation über das Reich in bisher unerreichter Geschwindigkeit. Die mongolischen Nachfolgestaaten — das Ilchanat in Persien, die Goldene Horde in Russland, das Tschagatai-Khanat in Zentralasien — traten allmählich zum Islam über und übernahmen lokale Kulturen, was eigenständige künstlerische und architektonische Traditionen hervorbrachte. Russlands lange mongolische Unterwerfung prägte seine autokratische politische Kultur. Der mongolische Augenblick, so kurz er war, ordnete Eurasien dauerhaft neu.",
    ],
    fr: [
      "Dans les steppes rudes d'Asie centrale, un garçon nommé Temüjin naquit vers 1162 dans un clan mongol mineur. Après des années d'épreuves — son père empoisonné par des rivaux, Temüjin lui-même tenu captif — il s'éleva par un mélange de talent militaire extraordinaire, de ruse politique et de détermination impitoyable pour unir les tribus mongoles perpétuellement en querelle.\n\nEn 1206, lors d'une grande assemblée (kurultai) de chefs mongols au bord de l'Onon, Temüjin fut proclamé Gengis Khan — « souverain universel ». Il transforma aussitôt les tribus rassemblées en une machine militaire disciplinée organisée selon des principes décimaux : unités de dix, cent, mille et dix mille. La loyauté allait à l'unité et au Khan, non au clan — un changement révolutionnaire qui mit fin aux guerres tribales ayant affaibli les Mongols durant des générations.",
      "Les armées mongoles étaient la force la plus efficace du monde médiéval, alliant mobilité, discipline, guerre psychologique et sophistication tactique. Les archers montés pouvaient couvrir 80 à 100 km par jour, opérant sur de vastes distances qui auraient immobilisé les armées d'infanterie. Avant une bataille, les émissaires mongols offraient aux villes un choix brutal : se rendre et être épargnées, ou résister et affronter la destruction totale.\n\nLes villes qui se soumettaient étaient généralement traitées avec une clémence pragmatique — leurs artisans, ingénieurs et administrateurs étaient absorbés dans la machine d'État mongole. Les villes qui résistaient étaient rasées en avertissement. Quand la grande cité de Zhongdu (l'actuelle Pékin) tomba en 1215, des voyageurs étrangers rapportèrent que les ossements de ses habitants blanchissaient les plaines sur des kilomètres. Cette combinaison de clémence et de terreur se révéla dévastatrice : la nouvelle des campagnes mongoles poussait souvent les villes à se soumettre sans combattre.",
      "À la mort de Gengis Khan en 1227, les Mongols contrôlaient un empire allant de la côte pacifique de la Chine à la mer Caspienne. Ses successeurs poussèrent encore plus loin. Ögödei Khan acheva la conquête du nord de la Chine ; Batu Khan déferla sur la Russie et la Pologne, atteignant l'Adriatique avant de se retirer. Houlagou Khan mit à sac Bagdad en 1258, tuant le calife abbasside et mettant fin à cinq siècles de suprématie culturelle islamique.\n\nÀ son apogée, l'Empire mongol était le plus grand empire terrestre contigu de l'histoire, couvrant 24 millions de kilomètres carrés — à peu près la taille de l'Afrique. Il englobait la majeure partie de la masse continentale eurasienne et tenait peut-être 100 millions de personnes sous sa domination. Aucun empire avant ou depuis n'a réalisé une expansion territoriale aussi rapide à travers des zones géographiques et climatiques aussi diverses.",
      "Paradoxalement, la conquête la plus destructrice de l'histoire créa l'une de ses périodes les plus fécondes d'échanges culturels. La Pax Mongolica (« paix mongole »), environ 1260–1350, unifia pour la première fois les routes commerciales de l'Eurasie sous un même parapluie politique. Marchands, diplomates, missionnaires et voyageurs pouvaient aller de la Chine à l'Europe avec une sécurité relative, portant biens, idées, techniques et maladies le long de la route de la Soie.\n\nLe fameux voyage de Marco Polo à la cour de Kubilaï Khan (1271–1295) ne fut possible que grâce à l'ordre mongol. La fabrication du papier, la poudre à canon et l'imprimerie chinoises voyagèrent vers l'ouest ; l'astronomie et la médecine islamiques vers l'est. Les cours mongoles recrutaient activement des gens qualifiés sans égard à la religion ou à l'origine — prêtres chrétiens, astronomes musulmans, ingénieurs chinois et bureaucrates persans servaient tous à la cour Yuan de Pékin. Cet échange cosmopolite accéléra le développement technologique et commercial qui alimenterait à terme la Renaissance européenne et les Grandes Découvertes.",
      "Les conquêtes mongoles tuèrent environ 40 millions de personnes — peut-être 10 % de la population mondiale — et altérèrent durablement le paysage démographique de l'Asie centrale et du Moyen-Orient. La population de l'Iran ne retrouva peut-être son niveau pré-mongol qu'après 700 ans. La destruction des systèmes d'irrigation de Bagdad contribua au long déclin agricole de la Mésopotamie. Les cités jadis grandes d'Asie centrale — Samarcande, Boukhara, Merv — ne retrouvèrent jamais pleinement leur vitalité d'avant les Mongols.\n\nPourtant la domination mongole créa aussi. La dynastie Yuan de Kubilaï Khan (1271–1368) apporta à la Chine un développement économique spectaculaire : le papier-monnaie fut standardisé, le Grand Canal prolongé, et le système de relais postaux (yam) permit une communication à travers l'empire d'une rapidité sans précédent. Les États successeurs mongols — l'Ilkhanat en Perse, la Horde d'or en Russie, le khanat de Djaghataï en Asie centrale — se convertirent peu à peu à l'islam et adoptèrent les cultures locales, produisant des traditions artistiques et architecturales distinctives. La longue sujétion mongole de la Russie façonna sa culture politique autocratique. Le moment mongol, si bref fût-il, réordonna durablement l'Eurasie.",
    ],
  },
  'medieval-06': {
    de: [
      "Japans Kaiserhof in Heian-kyō (dem heutigen Kyoto) erreichte im 10.–11. Jahrhundert seinen kulturellen Höhepunkt und brachte außerordentliche Literatur und Kunst hervor. Doch die Verwaltung der fernen Provinzen erforderte Krieger — berittene Bogenschützen, aus adligen Familien angeworben. Diese Provinzkrieger, Samurai („die dienen“) genannt, entwickelten sich allmählich von kaiserlichen Gefolgsleuten zu einer eigenen Militärklasse mit eigenen Werten und Ästhetik.\n\nDie Samurai-Gesellschaft war um das Herr-Vasallen-Verhältnis geordnet: Ein Samurai gelobte seinem Herrn (Daimyō) absolute Treue gegen Land und Schutz. Das entstehende Kriegerethos — später als Bushidō, „der Weg des Kriegers“, kodifiziert — betonte Treue (chū), Ehre (meiyo), Kampfkunst und die Annahme des Todes. Von einem Samurai, der seine Ehre verlor oder dessen Herr starb, wurde erwartet, rituellen Selbstmord (Seppuku) zu begehen, statt in Schande zu leben. Dieser strenge Kodex prägte die japanische Kultur über Jahrhunderte.",
      "Die Rivalität zwischen Japans zwei mächtigsten Kriegerclans — den Taira (Heike) und den Minamoto (Genji) — entlud sich im Genpei-Krieg (1180–1185), einem Konflikt, der zu einer der prägenden Erzählungen der japanischen Kultur wurde. Die Minamoto, geführt vom brillanten Feldherrn Minamoto no Yoshitsune, besiegten die Taira in einer Reihe von Schlachten, die in der Seeschlacht von Dan-no-ura gipfelten, wo der Kind-Kaiser Antoku mit der Taira-Flotte ertrank.\n\nMinamoto no Yoritomo, Yoshitsunes älterer Bruder, errichtete 1185 in Kamakura Japans erstes Shogunat (Militärregierung) — eine Parallelregierung, die den Kaiserhof faktisch verdrängte. Der Kaiser behielt die zeremonielle Autorität; die wirkliche Macht lag beim Shogun. Diese Doppelstruktur aus nomineller Kaiserherrschaft und tatsächlicher Militärregierung bestand mit Abweichungen bis 1868. Die Geschichten des Genpei-Krieges — Yoshitsunes Genie und tragisches Schicksal, der Untergang der Taira — wurden in der Erzählung von den Heike, Japans großem Kriegerepos, verewigt.",
      "Der Zen-Buddhismus, im späten 12. Jahrhundert aus China eingeführt, fand sein empfänglichstes Publikum in der Samurai-Klasse. Zens Betonung der unmittelbaren Erfahrung vor der Schrift, seine Meditationspraktiken, die geistige Klarheit unter Druck kultivierten, und seine Annahme der Vergänglichkeit fanden bei Kriegern, die dem Tod als tägliche Wirklichkeit gegenüberstanden, tiefen Widerhall. Zen-Meister wurden geistliche Berater von Shogunen wie Daimyō.\n\nDie Zen-Ästhetik prägte die japanische Kultur zutiefst. Die Teezeremonie (chanoyu), die Gartengestaltung, die Tuschmalerei (suiboku-ga), das Nō-Theater und das Blumenstecken (Ikebana) spiegeln alle die Zen-Werte von Schlichtheit, Vergänglichkeit und disziplinierter Aufmerksamkeit. Selbst die Schwertschmiedekunst wurde zur geistlichen Kunst: Ein Meisterschmied reinigte sich rituell, ehe er eine Klinge schmiedete, und das fertige Katana galt als Seele in Stahl. Diese Verschmelzung kriegerischer Zweckmäßigkeit mit verfeinertem ästhetischem Empfinden brachte eine der eigenständigsten Kulturtraditionen der Welt hervor.",
      "1274 und 1281 unternahm das Yuan-Reich Kublai Khans zwei gewaltige Invasionsversuche gegen Japan — die größten amphibischen Operationen des Mittelalters. Die erste Flotte aus 900 Schiffen und 40.000 Kriegern erreichte im November 1274 die Bucht von Hakata und schlug japanische Samurai mit überlegenen Armbrüsten, explosiven Bomben und koordinierter Infanterietaktik zurück, der einzelne japanische Krieger nicht gewachsen waren. Doch ein plötzlicher Sturm beschädigte die Flotte, und die Mongolen zogen sich zurück.\n\nDie zweite Invasion 1281 war weit größer: 4.400 Schiffe und bis zu 140.000 Mann. Nach wochenlangen Kämpfen an den Stränden und an Bord ankernder Schiffe zerstörte ein gewaltiger Taifun — der berühmte „göttliche Wind“ oder Kamikaze — den Großteil der Flotte. Japan war gerettet. Doch der Sieg hatte verheerende Folgen: Die verteidigenden Samurai erwarteten Landvergaben als Lohn, doch es gab kein erobertes Gebiet zu verteilen. Die daraus folgende wirtschaftliche Not schwächte das Kamakura-Shogunat und trug zu seinem schließlichen Zusammenbruch 1333 bei. Der Kamikaze-Mythos wurde zum Eckstein der japanischen nationalen Identität, erneut heraufbeschworen — mit tragischen Folgen — im Zweiten Weltkrieg.",
      "Der Ōnin-Krieg von 1467–1477, um die Nachfolge im Shogunat in den Straßen Kyotos ausgetragen, zerschlug, was von der Zentralgewalt geblieben war, und stürzte Japan in die Sengoku-Zeit („Streitende Reiche“) — anderthalb Jahrhunderte fast ununterbrochenen Krieges zwischen rivalisierenden Daimyō. Burgen wurden über das Land errichtet; Bauern wurden als Fußsoldaten (Ashigaru) ausgehoben; die Einführung von Feuerwaffen durch portugiesische Händler 1543 verwandelte die Taktik.\n\nDie Einigung kam durch drei aufeinanderfolgende „große Einiger“. Oda Nobunaga — rücksichtslos, erfinderisch und brillant — setzte Feuerwaffen und Stoßtaktik ein, um Rivalen zu besiegen, ehe er 1582 ermordet wurde. Sein General Toyotomi Hideyoshi, ein zur höchsten Macht aufgestiegener Bauernsohn, vollendete die Einigung und begann zwei katastrophale Invasionen Koreas. Nach Hideyoshis Tod besiegte Tokugawa Ieyasu seine Rivalen in der Schlacht von Sekigahara (1600) und errichtete das Tokugawa-Shogunat — eine stabile Regierung, die Japan die nächsten 260 Jahre in bewusster Abschottung vom Rest der Welt regieren und die Samurai-Kultur wie in Bernstein bewahren sollte, bis die Moderne Japans Türen aufzwang.",
    ],
    fr: [
      "La cour impériale du Japon à Heian-kyō (l'actuelle Kyoto) atteignit son zénith culturel aux Xe–XIe siècles, produisant une littérature et un art extraordinaires. Mais gouverner les provinces lointaines exigeait des guerriers — archers montés recrutés dans les familles aristocratiques. Ces guerriers provinciaux, appelés samouraïs (« ceux qui servent »), évoluèrent peu à peu de vassaux impériaux en une classe militaire distincte avec ses valeurs et son esthétique propres.\n\nLa société samouraï s'organisait autour de la relation seigneur-vassal : un samouraï jurait loyauté absolue à son seigneur (daimyō) en échange de terres et de protection. L'éthos guerrier qui se développa — codifié plus tard sous le nom de bushidō, « la voie du guerrier » — mettait l'accent sur la loyauté (chū), l'honneur (meiyo), l'habileté martiale et l'acceptation de la mort. Un samouraï ayant perdu son honneur ou dont le seigneur mourait était censé commettre le suicide rituel (seppuku) plutôt que vivre dans le déshonneur. Ce code austère façonna la culture japonaise durant des siècles.",
      "La rivalité entre les deux plus puissants clans guerriers du Japon — les Taira (Heike) et les Minamoto (Genji) — éclata dans la guerre de Genpei (1180–1185), conflit qui devint l'un des récits fondateurs de la culture japonaise. Les Minamoto, menés par le brillant général Minamoto no Yoshitsune, vainquirent les Taira dans une série de batailles culminant à la bataille navale de Dan-no-ura, où le jeune empereur Antoku se noya avec la flotte Taira.\n\nMinamoto no Yoritomo, frère aîné de Yoshitsune, établit le premier shogunat du Japon (gouvernement militaire) à Kamakura en 1185 — un gouvernement parallèle qui supplanta de fait la cour impériale. L'empereur conservait l'autorité cérémonielle ; le pouvoir réel appartenait au shogun. Cette structure double d'un règne impérial nominal et d'une gouvernance militaire effective persista, avec des variantes, jusqu'en 1868. Les récits de la guerre de Genpei — le génie et le sort tragique de Yoshitsune, la ruine des Taira — furent immortalisés dans le Dit des Heike, la grande épopée guerrière du Japon.",
      "Le bouddhisme zen, introduit de Chine à la fin du XIIe siècle, trouva son public le plus réceptif dans la classe samouraï. L'accent du zen sur l'expérience directe plutôt que sur l'écriture, ses pratiques de méditation cultivant la clarté d'esprit sous pression, et son acceptation de l'impermanence résonnaient profondément chez des guerriers qui affrontaient la mort au quotidien. Les maîtres zen devinrent conseillers spirituels des shoguns comme des daimyō.\n\nL'esthétique zen façonna profondément la culture japonaise. La cérémonie du thé (chanoyu), l'art des jardins, la peinture à l'encre (suiboku-ga), le théâtre nô et l'art floral (ikebana) reflètent tous les valeurs zen de simplicité, d'impermanence et d'attention disciplinée. Même la fabrication du sabre devint un art spirituel : un maître forgeron se purifiait rituellement avant de forger une lame, et le katana achevé était tenu pour une âme dans l'acier. Cette fusion de pragmatisme martial et de sensibilité esthétique raffinée produisit l'une des traditions culturelles les plus distinctives du monde.",
      "En 1274 et 1281, l'empire Yuan de Kubilaï Khan lança deux immenses tentatives d'invasion du Japon — les plus grandes opérations amphibies du Moyen Âge. La première flotte de 900 navires et 40 000 guerriers arriva dans la baie de Hakata en novembre 1274, repoussant les samouraïs japonais avec des arbalètes supérieures, des bombes explosives et des tactiques d'infanterie coordonnées que les guerriers japonais individuels n'étaient pas formés à contrer. Mais une tempête soudaine endommagea la flotte, et les Mongols se retirèrent.\n\nLa seconde invasion de 1281 fut bien plus vaste : 4 400 navires et jusqu'à 140 000 hommes. Après des semaines de combats sur les plages et à bord des navires ancrés, un typhon massif — le fameux « vent divin » ou kamikaze — détruisit l'essentiel de la flotte. Le Japon était sauvé. Mais la victoire eut des conséquences dévastatrices : les samouraïs défenseurs attendaient des dons de terres en récompense, mais il n'y avait aucun territoire conquis à distribuer. La tension économique qui s'ensuivit affaiblit le shogunat de Kamakura et contribua à son effondrement en 1333. La mythologie du kamikaze devint une pierre angulaire de l'identité nationale japonaise, invoquée de nouveau — avec des résultats tragiques — durant la Seconde Guerre mondiale.",
      "La guerre d'Ōnin de 1467–1477, livrée pour la succession shogunale dans les rues de Kyoto, brisa ce qui restait de l'autorité centrale et plongea le Japon dans la période Sengoku (« provinces en guerre ») — un siècle et demi de guerre quasi constante entre daimyō rivaux. Des châteaux s'élevèrent à travers le pays ; les paysans furent enrôlés comme fantassins (ashigaru) ; l'introduction des armes à feu par les marchands portugais en 1543 transforma la tactique.\n\nL'unification vint par trois « grands unificateurs » successifs. Oda Nobunaga — impitoyable, novateur et brillant — usa des armes à feu et de tactiques de choc pour vaincre ses rivaux avant son assassinat en 1582. Son général Toyotomi Hideyoshi, fils de paysan parvenu au pouvoir suprême, acheva l'unification et lança deux invasions catastrophiques de la Corée. Après la mort de Hideyoshi, Tokugawa Ieyasu vainquit ses rivaux à la bataille de Sekigahara (1600) et établit le shogunat Tokugawa — un gouvernement stable qui régnerait sur le Japon dans un isolement délibéré du reste du monde pendant les 260 années suivantes, préservant la culture samouraï comme dans l'ambre jusqu'à ce que l'ère moderne force l'ouverture du Japon.",
    ],
  },
  'medieval-07': {
    de: [
      "Am 8. Juni 793 überfielen seewärts gekommene Räuber das Kloster Lindisfarne vor der Küste Northumbriens, erschlugen Mönche und trugen seine Schätze fort. Der Gelehrte Alkuin, vom Hof Karls des Großen aus schreibend, war entsetzt: „Nie zuvor ist in Britannien solch ein Schrecken erschienen, wie wir ihn nun von einem heidnischen Volk erlitten haben.“ Der Überfall kündete die Wikingerzeit an — fast drei Jahrhunderte, in denen nordische Seefahrer aus Dänemark, Norwegen und Schweden die Landkarte Europas umgestalten würden.\n\nWas sie antrieb, ist noch umstritten. Bevölkerungsdruck auf begrenztem skandinavischem Ackerland, politische Verdichtung, die ehrgeizige jüngere Söhne hinausdrängte, der Reiz des unverteidigten Reichtums der Klöster und vor allem eine Revolution im Schiffbau spielten alle eine Rolle. Die Nordleute waren kein geeintes Volk oder Reich, sondern eine Streuung von Häuptlingen, Händlern und Kriegerscharen, die eine Sprache, ein Pantheon von Göttern und ein Genie für die See teilten. Ihren Opfern waren sie heidnische Ungeheuer; sich selbst waren sie Bauern, Dichter und Kaufleute, denen eine Raubsaison ein Unternehmen unter vielen war.",
      "Keine einzelne Technik prägte die Wikingerzeit mehr als das Langschiff. Klinkergebaut aus überlappenden Eichenplanken, leicht und biegsam, ging es kaum einen Meter tief, konnte aber den offenen Atlantik befahren. Ein einziges Rahsegel trieb es mit dem Wind rasch voran; Reihen von Rudern bewegten es bei Flaute oder flussaufwärts. Sein symmetrischer Rumpf konnte ohne Wenden die Richtung umkehren, und es ließ sich an jedem Ufer stranden oder über Land zwischen Wasserwegen tragen.\n\nDas bedeutete: Keine Küste, keine Flussstadt, keine Insel war sicher. Eine Wikingerflotte konnte ohne Warnung auftauchen, zuschlagen und verschwunden sein, ehe sich eine Verteidigung sammeln konnte. Dieselben Schiffe, die Paris und Sevilla in Schrecken versetzten, trugen Siedler und ihr Vieh über tausend Meilen offenen Ozeans nach Island. Das Langschiff war Kriegsschiff, Frachtboot und Ozeanentdecker in einem — und um es herum bauten die Nordleute eine maritime Kultur, unerreicht im mittelalterlichen Europa. Die großen Schiffsbestattungen von Oseberg und Gokstad in Norwegen bewahren diese Fahrzeuge fast unversehrt, ihre geschnitzten Steven noch zum Horizont gebogen.",
      "Der Raub wich Eroberung und Besiedlung. In England landete 865 ein „Großes Heidnisches Heer“ und überrannte die Königreiche Northumbrien, Ostanglien und Mercien; nur Alfreds des Großen Wessex hielt stand, und selbst Alfred musste den Norden und Osten dem dänischen Recht zugestehen — dem Danelag, dessen Ortsnamen auf „-by“ und „-thorpe“ noch heute die englische Karte prägen. Die Nordleute gründeten oder vergrößerten Städte wie Jorvik (York) und Dublin zu blühenden Zentren des Handels mit Silber, Sklaven und Handwerk.\n\nIn Franken gipfelten wiederholte Raubzüge die Seine hinauf in der Belagerung von Paris (885–886). Statt weiterzukämpfen, erkaufte der Frankenkönig Karl der Einfältige 911 den Frieden, indem er dem Wikingerführer Rollo das Land an der Seinemündung überließ — die Normandie, „das Land der Nordmänner“. Binnen weniger Generationen waren Rollos Nachfahren französischsprachige christliche Herzöge geworden; einer von ihnen, Wilhelm, sollte 1066 England erobern. Die Wikinger plünderten Europa nicht bloß — sie ließen sich darin nieder, und ihre Nachfahren wurden einige seiner mächtigsten Herrscher.",
      "Während Dänen und Norweger nach Westen blickten, wandten sich schwedische Wikinger — die Rus — nach Osten und schleppten ihre Boote zwischen den großen Flüssen der eurasischen Ebene. Der Wolga und dem Dnjepr folgend „von den Warägern zu den Griechen“, tauschten sie Pelze, Bernstein und Sklaven gegen das Silber der islamischen Kalifate; über ganz Skandinavien verstreute Horte arabischer Münzen zeichnen diese Reisen nach. Um diese Flussrouten bauten sie einen Staat, herrschten von Nowgorod und dann Kiew — die Kiewer Rus, Vorfahr Russlands und der Ukraine.\n\nDie Rus erreichten die Mauern Konstantinopels selbst, mal als Räuber, öfter als Händler und Söldner. Die byzantinischen Kaiser schätzten sie so hoch, dass sie aus nordischen und später angelsächsischen Kriegern die Elite-Warägergarde bildeten. 988 nahm der Rus-Fürst Wladimir das orthodoxe Christentum von Byzanz an und band die Ostslawen an Konstantinopel statt an Rom — eine Entscheidung, deren religiöse und kulturelle Folgen tausend Jahre später noch durch Osteuropa hallen.",
      "Die Nordleute schoben die Grenzen der bekannten Welt weiter hinaus als alle Europäer vor ihnen. Sie besiedelten Island ab etwa 874 und schufen ein bemerkenswertes Gemeinwesen, regiert vom Althing, einer der ältesten Versammlungen der Welt. Von Island aus führte Erik der Rote um 985 Siedler nach Grönland. Und von Grönland aus segelte sein Sohn Leif Eriksson noch weiter und erreichte ein Land, das er Vinland nannte — bestätigt durch die nordische Fundstätte von L'Anse aux Meadows in Neufundland, ein Beweis, dass Europäer Amerika fünf Jahrhunderte vor Kolumbus erreichten.\n\nDas Zeitalter, das in Lindisfarne begann, endete herkömmlich 1066 bei Stamford Bridge, wo der englische König Harold Godwinson das eindringende Heer Harald Hardrådas von Norwegen — des letzten großen Wikingereroberers — vernichtete. Wochen später fiel Harold selbst gegen Wilhelm von der Normandie, den Nachfahren eines Wikingers, bei Hastings. Da waren die skandinavischen Königreiche christlich und sesshaft geworden, ihre Kräfte nach innen gewandt. Doch das Wikingererbe blieb: in den Städten, die sie gründeten, den Staaten, die sie säten, den Sagas, die sie erzählten, und dem bleibenden Bild des drachenbestevten Langschiffs, das durch nördliche Meere schneidet.",
    ],
    fr: [
      "Le 8 juin 793, des pillards venus de la mer fondirent sur le monastère de Lindisfarne au large de la Northumbrie, massacrant les moines et emportant ses trésors. Le savant Alcuin, écrivant depuis la cour de Charlemagne, était atterré : « Jamais pareille terreur n'était apparue en Grande-Bretagne comme celle que nous subissons d'une race païenne. » Le raid annonçait l'âge viking — près de trois siècles où les marins nordiques du Danemark, de Norvège et de Suède allaient refaire la carte de l'Europe.\n\nCe qui les poussait fait encore débat. Pression démographique sur des terres scandinaves limitées, consolidation politique chassant d'ambitieux cadets, attrait de la richesse sans défense des monastères, et surtout une révolution dans la construction navale jouèrent tous un rôle. Les Nordiques n'étaient ni un peuple ni un empire unifié, mais une dispersion de chefs, de marchands et de bandes guerrières partageant une langue, un panthéon de dieux et un génie de la mer. Pour leurs victimes ils étaient des monstres païens ; pour eux-mêmes, des paysans, des poètes et des marchands pour qui une saison de razzia était une entreprise parmi d'autres.",
      "Aucune technique ne définit davantage l'âge viking que le langskip. Bordé à clin de planches de chêne se chevauchant, léger et souple, il tirait à peine un mètre d'eau mais pouvait affronter l'Atlantique. Une seule voile carrée le poussait vite au vent ; des rangs de rames le mouvaient dans le calme ou en remontant une rivière. Sa coque symétrique pouvait inverser sa direction sans virer, et il pouvait s'échouer sur n'importe quel rivage ou se porter par voie de terre entre les cours d'eau.\n\nCela signifiait qu'aucune côte, aucune ville fluviale, aucune île n'était sûre. Une flotte viking pouvait surgir sans prévenir, frapper et disparaître avant qu'une défense ne se rassemble. Les mêmes navires qui terrorisèrent Paris et Séville portèrent colons et bétail sur mille milles d'océan ouvert jusqu'en Islande. Le langskip était navire de guerre, cargo et explorateur océanique à la fois — et autour de lui les Nordiques bâtirent une culture maritime sans égale dans l'Europe médiévale. Les grandes sépultures navales d'Oseberg et de Gokstad en Norvège conservent ces vaisseaux presque intacts, leurs proues sculptées courbées encore vers l'horizon.",
      "La razzia céda la place à la conquête et à la colonisation. En Angleterre, une « Grande Armée païenne » débarqua en 865 et submergea les royaumes de Northumbrie, d'Est-Anglie et de Mercie ; seul le Wessex d'Alfred le Grand résista, et même Alfred dut concéder le nord et l'est au droit danois — le Danelaw, dont les toponymes en « -by » et « -thorpe » marquent encore la carte de l'Angleterre. Les Nordiques fondèrent ou firent croître des villes comme Jorvik (York) et Dublin en centres prospères de commerce d'argent, d'esclaves et d'artisanat.\n\nEn Francie, des raids répétés en remontant la Seine culminèrent dans le siège de Paris (885–886). Plutôt que de continuer à combattre, le roi franc Charles le Simple acheta la paix en 911 en octroyant au chef viking Rollon la terre à l'embouchure de la Seine — la Normandie, « le pays des hommes du Nord ». En quelques générations, les descendants de Rollon étaient devenus des ducs chrétiens francophones ; l'un d'eux, Guillaume, conquerrait l'Angleterre en 1066. Les Vikings ne se contentèrent pas de piller l'Europe — ils s'y installèrent, et leurs descendants en devinrent parmi les plus puissants souverains.",
      "Tandis que Danois et Norvégiens regardaient vers l'ouest, les Vikings suédois — les Rus — se tournèrent vers l'est, traînant leurs bateaux entre les grands fleuves de la plaine eurasienne. Suivant la Volga et le Dniepr « des Varègues aux Grecs », ils échangeaient fourrures, ambre et esclaves contre l'argent des califats islamiques ; des trésors de monnaies arabes trouvés à travers la Scandinavie retracent ces voyages. Autour de ces routes fluviales ils bâtirent un État, régnant depuis Novgorod puis Kiev — la Rus de Kiev, ancêtre de la Russie et de l'Ukraine.\n\nLes Rus atteignirent les murs de Constantinople elle-même, parfois en pillards, plus souvent en marchands et mercenaires. Les empereurs byzantins les prisaient tant qu'ils formèrent la garde varègue d'élite de guerriers nordiques puis anglo-saxons. En 988, le prince rus Vladimir accepta le christianisme orthodoxe de Byzance, liant les Slaves orientaux à Constantinople plutôt qu'à Rome — décision dont les conséquences religieuses et culturelles résonnent encore à travers l'Europe de l'Est mille ans plus tard.",
      "Les Nordiques repoussèrent les limites du monde connu plus loin qu'aucun Européen avant eux. Ils colonisèrent l'Islande à partir de 874 environ, créant un remarquable État régi par l'Althing, l'une des plus anciennes assemblées du monde. Depuis l'Islande, Erik le Rouge conduisit des colons au Groenland vers 985. Et depuis le Groenland, son fils Leif Erikson navigua plus loin encore, atteignant une terre qu'il appela Vinland — confirmée par le site nordique de L'Anse aux Meadows à Terre-Neuve, preuve que les Européens atteignirent les Amériques cinq siècles avant Colomb.\n\nL'âge commencé à Lindisfarne s'acheva, par convention, à Stamford Bridge en 1066, où le roi anglais Harold Godwinson détruisit l'armée d'invasion de Harald Hardrada de Norvège — le dernier grand conquérant viking. Des semaines plus tard, Harold lui-même tomba devant Guillaume de Normandie, descendant d'un Viking, à Hastings. À cette date, les royaumes scandinaves étaient devenus chrétiens et sédentaires, leurs énergies tournées vers l'intérieur. Mais l'héritage viking perdura : dans les villes qu'ils fondèrent, les États qu'ils semèrent, les sagas qu'ils contèrent, et l'image durable du langskip à proue de dragon fendant les mers du Nord.",
    ],
  },
  'medieval-08': {
    de: [
      "711 setzte ein berberisch-arabisches Heer unter Tariq ibn Ziyad von Nordafrika über die Meerenge und zerstörte in der Schlacht von Guadalete das westgotische Königreich Hispania. Der Fels, an dem er landete, trägt noch seinen Namen: Dschabal Tariq — „Tariqs Berg“ — Gibraltar. Binnen eines Jahrzehnts erstreckte sich die muslimische Herrschaft über den Großteil der Halbinsel, die arabische Sprecher al-Andalus nannten.\n\nDer Vorstoß nach Franken wurde 732 von Karl Martell bei Tours gestoppt, und die Pyrenäen wurden eine grobe Grenze. In den Bergen Asturiens im Norden gewann ein westgotischer Edelmann namens Pelayo bei Covadonga (um 722) ein Gefecht, das spätere Chronisten als ersten Funken der Reconquista erinnern würden.",
      "Als die Abbasiden 750 die Umayyaden-Dynastie in Damaskus massakrierten, entkam ein Prinz nach Westen. Abd ar-Rahman I. erreichte Iberien und baute in Córdoba ein unabhängiges Emirat; sein Nachfahre Abd ar-Rahman III. rief sich 929 zum Kalifen aus. Das Córdoba des 10. Jahrhunderts war nach europäischen Maßstäben überwältigend: Hunderttausende Einwohner, gepflasterte und lampenerleuchtete Straßen, Hunderte Bäder und Bibliotheken und der Wald gestreifter Hufeisenbögen der Großen Moschee.\n\nEine deutsche Nonnen-Chronistin nannte die Stadt „die Zierde der Welt“. Juden, Christen und Muslime lebten in einem funktionierenden — wenn auch ungleichen — Zusammenleben, später convivencia genannt. Die kalifale Bibliothek al-Hakams II. soll 400.000 Bände gehalten haben, als die größten lateinischen Bibliotheken einige hundert zählten.",
      "Nachdem der Kalifat 1031 in zerstrittene Taifa-Kleinstaaten zerfallen war, drängten die christlichen Königreiche des Nordens — León, Kastilien, Aragón, Portugal, Navarra — nach Süden. Toledo fiel 1085; die Taifa-Könige riefen die Almoraviden, dann die Almohaden, aus Marokko herbei, und die Halbinsel schwankte zwei Jahrhunderte hin und her. Der entscheidende Schlag kam 1212 bei Las Navas de Tolosa, als ein vereintes christliches Heer die Almohaden-Macht brach.\n\nCórdoba fiel 1236 und Sevilla 1248 und ließen nur das Bergemirat Granada — Heimat des erlesenen Alhambra-Palasts — als tributpflichtigen muslimischen Staat für weitere 250 Jahre. Die Grenzwelt aus Raub, Lösegeld und wechselnden Loyalitäten brachte Gestalten wie El Cid hervor, der für christliche wie muslimische Geldgeber kämpfte und zum Nationalepos Kastiliens wurde.",
      "Ferdinand von Aragón und Isabella von Kastilien, die „Katholischen Könige“, deren Ehe Spanien einte, nahmen Granada am 2. Januar 1492 nach einem zehnjährigen Krieg. Im selben Jahr vertrieben sie Spaniens Juden und finanzierten Kolumbus — drei Ereignisse, die den Wendepunkt von der mittelalterlichen zur frühneuzeitlichen Geschichte markieren. Muslime wurden binnen einer Generation zwangsbekehrt, und die Inquisition überwachte die Bekehrten.\n\nAl-Andalus hinterließ Europa ein tiefes Erbe. Durch die Übersetzerwerkstätten Toledos empfing die lateinische Christenheit Aristoteles mit den Kommentaren des Averroes, al-Chwarizmis Algebra und die arabischen Ziffern. Das Spanische trägt Tausende arabischer Wörter — von alcalde (Bürgermeister) bis azúcar (Zucker) —, und die Paläste von Sevilla und die Alhambra sprechen noch die Bildsprache des verschwundenen Kalifats.",
      "Das Córdoba des zwölften Jahrhunderts brachte binnen einer Generation zwei der einflussreichsten Denker des gesamten Mittelalters hervor. Ibn Rushd — Averroes für die lateinische Welt — schrieb Kommentare zu Aristoteles von solcher Durchdringung, dass das christliche Europa ihn schlicht „den Kommentator“ nannte; sein Beharren, dass Vernunft und Offenbarung nicht wirklich in Widerspruch geraten könnten, erschütterte drei Religionen. Sein fast Zeitgenosse Moses Maimonides, der größte jüdische Philosoph der Zeit, floh als Junge vor der Almohaden-Verfolgung und schrieb seinen Führer der Unschlüssigen auf Arabisch in Ägypten. Dass beide Männer — einer Muslim, einer Jude, beide denselben griechischen Philosophen in der Tradition derselben Stadt lesend — ihre Wirkung gleichermaßen in Pariser Hörsälen wie in hebräischen Akademien entfalteten, ist al-Andalus im Kleinen: eine Zivilisation, deren Argumente ihre Grenzen überlebten.",
    ],
    fr: [
      "En 711, une armée arabo-berbère sous Tariq ibn Ziyad franchit le détroit depuis l'Afrique du Nord et détruisit le royaume wisigoth d'Hispanie à la bataille du Guadalete. Le rocher où il débarqua porte encore son nom : Jabal Tariq — « la montagne de Tariq » — Gibraltar. En une décennie, la domination musulmane s'étendait sur l'essentiel de la péninsule, que les arabophones appelaient al-Andalus.\n\nL'avancée en Francie fut stoppée par Charles Martel à Tours en 732, et les Pyrénées devinrent une frontière approximative. Dans les montagnes des Asturies au nord, un noble wisigoth nommé Pélage remporta une escarmouche à Covadonga (v. 722) que les chroniqueurs ultérieurs retiendraient comme la première étincelle de la Reconquista.",
      "Quand les Abbassides massacrèrent la dynastie omeyyade à Damas en 750, un prince s'échappa vers l'ouest. Abd al-Rahman Ier atteignit l'Ibérie et bâtit un émirat indépendant à Cordoue ; son descendant Abd al-Rahman III se proclama calife en 929. La Cordoue du Xe siècle était stupéfiante selon les critères européens : des centaines de milliers d'habitants, des rues pavées et éclairées, des centaines de bains et de bibliothèques, et la forêt d'arcs outrepassés bicolores de la Grande Mosquée.\n\nUne chroniqueuse nonne allemande appela la ville « l'ornement du monde ». Juifs, chrétiens et musulmans vivaient sous une coexistence fonctionnelle — quoique inégale — appelée plus tard convivencia. La bibliothèque califale d'al-Hakam II aurait renfermé 400 000 volumes quand les plus grandes bibliothèques latines en comptaient quelques centaines.",
      "Après l'éclatement du califat en petits États taifas querelleurs en 1031, les royaumes chrétiens du nord — León, Castille, Aragon, Portugal, Navarre — poussèrent vers le sud. Tolède tomba en 1085 ; les rois taifas appelèrent les Almoravides, puis les Almohades, du Maroc, et la péninsule oscilla deux siècles durant. Le coup décisif vint à Las Navas de Tolosa en 1212, quand une armée chrétienne unie brisa la puissance almohade.\n\nCordoue tomba en 1236 et Séville en 1248, ne laissant que l'émirat de montagne de Grenade — siège du raffiné palais de l'Alhambra — comme État musulman tributaire pour 250 ans encore. Le monde frontalier de razzia, de rançon et d'allégeances changeantes produisit des figures comme le Cid, qui combattit pour des maîtres chrétiens comme musulmans et devint l'épopée nationale de la Castille.",
      "Ferdinand d'Aragon et Isabelle de Castille, les « Rois catholiques » dont le mariage unit l'Espagne, prirent Grenade le 2 janvier 1492 après une guerre de dix ans. La même année, ils expulsèrent les Juifs d'Espagne et financèrent Colomb — trois événements marquant le pivot de l'histoire médiévale à moderne. Les musulmans furent convertis de force en une génération, et l'Inquisition surveilla les convertis.\n\nAl-Andalus laissa à l'Europe un profond héritage. Par les ateliers de traduction de Tolède, la chrétienté latine reçut Aristote avec les commentaires d'Averroès, l'algèbre d'al-Khwarizmi et les chiffres arabes. L'espagnol porte des milliers de mots arabes — de alcalde (maire) à azúcar (sucre) — et les palais de Séville et l'Alhambra parlent encore le langage visuel du califat disparu.",
      "La Cordoue du XIIe siècle produisit, en une génération, deux des penseurs les plus influents de tout le Moyen Âge. Ibn Rushd — Averroès pour le monde latin — écrivit des commentaires sur Aristote si pénétrants que l'Europe chrétienne l'appela simplement « le Commentateur » ; son insistance sur le fait que raison et révélation ne pouvaient vraiment s'opposer ébranla trois religions. Son quasi-contemporain Moïse Maïmonide, le plus grand philosophe juif de l'époque, fuit enfant la persécution almohade et écrivit son Guide des égarés en arabe en Égypte. Que les deux hommes — l'un musulman, l'autre juif, lisant tous deux le même philosophe grec dans la tradition de la même ville — aient exercé leur influence aussi bien dans les amphithéâtres de Paris que dans les académies hébraïques, c'est al-Andalus en miniature : une civilisation dont les arguments survécurent à ses frontières.",
    ],
  },
  'medieval-09': {
    de: [
      "Der Krieg begann als dynastischer Streit: Als die französische Königslinie 1328 ausstarb, beanspruchte Eduard III. von England — durch seine Mutter Enkel eines französischen Königs — die Krone Frankreichs gegen den neuen Valois-König. Unter dem Rechtsstreit lagen ältere Reibungen: das englisch gehaltene Gascogne, der Wollhandel mit Flandern und die französische Unterstützung Schottlands.\n\nNiemand beabsichtigte ein Jahrhundert Krieg. Doch der Konflikt schleppte sich in Phasen dahin — spektakuläre englische Siege, erschöpfte Waffenstillstände, französische Erholung — und verwandelte dabei beide Königreiche. Untertanen, die sich für Normannen oder Gascogner, Burgunder oder Picarden gehalten hatten, lernten langsam, sich als Engländer oder Franzosen zu begreifen.",
      "Bei Crécy (1346) und Poitiers (1356) vernichteten englische Heere, ein Bruchteil der Größe ihrer Gegner, die Blüte des französischen Rittertums. Das Werkzeug war der Langbogen: ein zwei Meter langer Eibenstab, dessen Schützen ein Dutzend Pfeile pro Minute abschießen konnten, den Himmel verdunkelten und die Pferde angreifender Ritter in Raserei trieben. Bei Poitiers wurde der französische König selbst gefangen und für eine Summe losgekauft, die dem doppelten Jahreseinkommen seines Reiches entsprach.\n\nHeinrich V. nahm den Krieg wieder auf und wiederholte bei Azincourt (1415), im Schlamm, der gepanzerte Männer verschlang, das Gemetzel. Die Lehre war sozial wie militärisch: Ein Bauer mit einem Bogen konnte einen Herrn in Plattenpanzer töten. Das Zeitalter, in dem die aristokratische Reiterei das Schlachtfeld beherrschte, ging zu Ende.",
      "Bis 1428 schien Frankreich am Ende — sein Norden besetzt, sein König ungekrönt, Orléans belagert. Dann stellte sich ein siebzehnjähriges Bauernmädchen aus Domrémy bei Hofe vor und behauptete, Stimmen von Heiligen hätten ihr befohlen, Frankreich zu retten. Mit Rüstung und Heer versehen, entsetzte Jeanne d'Arc Orléans in neun Tagen und führte den Dauphin durch feindliches Gebiet, um in Reims als Karl VII. gekrönt zu werden — das heilige Ritual, das ihn unzweideutig zum König machte.\n\n1430 von burgundischen Verbündeten Englands gefangen, wurde Jeanne verkauft, von einem Kirchengericht in Rouen verurteilt und mit neunzehn auf dem Scheiterhaufen verbrannt. Ein Wiederaufnahmeverfahren von 1456 hob das Urteil auf; 1920 wurde sie heiliggesprochen. Sie bleibt vielleicht die außerordentlichste Gestalt des gesamten Mittelalters: eine des Lesens unkundige Jugendliche, die die Geschichte zweier Königreiche umlenkte.",
      "Frankreichs endgültige Erholung war ebenso verwaltungstechnisch wie heroisch. Karl VII. schuf Europas erstes stehendes königliches Heer und besteuerte das Reich, um es zu bezahlen — und für die neue Pulverartillerie der Brüder Bureau, deren Belagerungszüge englisch gehaltene Städte in der Normandie und Gascogne wie Nüsse knackten. Bei Castillon (1453), der letzten Schlacht des Krieges, vernichteten französische Kanonen einen englischen Angriff.\n\nEngland behielt nur Calais und wandte sich nach innen — in die Rosenkriege, geführt von Herren mit Privatheeren, die der französische Krieg ausgebildet hatte. Frankreich ging mit dauerhafter Besteuerung, einem stehenden Heer und einer Monarchie hervor, stark genug, Europa zu beherrschen. Der Krieg hatte über feudale Lehnstreue begonnen; er endete, nachdem er einen Großteil des modernen Staates erfunden hatte.",
      "Nach Crécy belagerte Eduard III. elf Monate den Hafen Calais und hungerte ihn 1347 zur Übergabe aus. Der König verlangte, dass sechs der führenden Bürger der Stadt barfuß, mit Stricken um den Hals und den Stadtschlüsseln in den Händen herauskämen — er gedachte, sie zu hängen. Der reichste Bürger, Eustache de Saint-Pierre, meldete sich zuerst; fünf weitere folgten. Nach dem Chronisten Froissart wurden sie im letzten Augenblick verschont, als Königin Philippa, hochschwanger, vor ihrem Gatten niederkniete und um ihr Leben bat. Calais blieb über zwei Jahrhunderte Englands Stützpunkt in Frankreich — und die sechs Bürger, in Rodins berühmter Skulptur verewigt, wurden zum dauerhaftesten Bild bürgerlichen Muts des Krieges: gewöhnliche Stadtleute, die dem Tod entgegengingen, damit ihre Nachbarn essen konnten.",
    ],
    fr: [
      "La guerre commença comme une querelle dynastique : à l'extinction de la lignée royale française en 1328, Édouard III d'Angleterre — petit-fils d'un roi de France par sa mère — revendiqua la couronne de France contre le nouveau roi Valois. Sous la querelle juridique couvaient de vieilles frictions : la Gascogne tenue par les Anglais, le commerce de la laine avec la Flandre et le soutien français à l'Écosse.\n\nNul ne voulut un siècle de guerre. Mais le conflit s'éternisa par phases — victoires anglaises spectaculaires, trêves épuisées, redressement français — transformant au passage les deux royaumes. Des sujets qui s'étaient crus normands ou gascons, bourguignons ou picards, apprirent peu à peu à se penser anglais ou français.",
      "À Crécy (1346) et à Poitiers (1356), des armées anglaises d'une fraction de la taille de leurs adversaires anéantirent la fleur de la chevalerie française. L'instrument était l'arc long : un fût d'if de deux mètres dont les archers pouvaient lâcher une douzaine de flèches par minute, obscurcissant le ciel et affolant les chevaux des chevaliers chargeants. À Poitiers, le roi de France lui-même fut capturé et libéré contre une rançon égale à deux fois le revenu annuel de son royaume.\n\nHenri V reprit la guerre et, à Azincourt (1415), dans une boue qui engloutissait les hommes cuirassés, répéta le massacre. La leçon était sociale autant que militaire : un paysan armé d'un arc pouvait tuer un seigneur en armure de plates. L'âge où la cavalerie aristocratique régnait sur le champ de bataille touchait à sa fin.",
      "En 1428, la France semblait finie — son nord occupé, son roi non sacré, Orléans assiégée. Puis une paysanne de dix-sept ans de Domrémy se présenta à la cour, affirmant que des voix de saints lui avaient ordonné de sauver la France. Dotée d'une armure et d'une armée, Jeanne d'Arc leva le siège d'Orléans en neuf jours et mena le dauphin à travers le territoire ennemi pour être sacré Charles VII à Reims — le rituel sacré qui le faisait roi sans ambiguïté.\n\nCapturée par les alliés bourguignons de l'Angleterre en 1430, Jeanne fut vendue, jugée par un tribunal ecclésiastique à Rouen et brûlée vive à dix-neuf ans. Un procès en révision de 1456 annula le verdict ; en 1920 elle fut canonisée. Elle reste peut-être la figure la plus extraordinaire de tout le Moyen Âge : une adolescente illettrée qui réorienta l'histoire de deux royaumes.",
      "Le redressement final de la France fut autant administratif qu'héroïque. Charles VII créa la première armée royale permanente d'Europe et taxa le royaume pour la financer — ainsi que la nouvelle artillerie à poudre des frères Bureau, dont les trains de siège fendaient les villes tenues par les Anglais en Normandie et en Gascogne comme des noix. À Castillon (1453), dernière bataille de la guerre, les canons français anéantirent une charge anglaise.\n\nL'Angleterre ne garda que Calais et se tourna vers l'intérieur — vers la guerre des Deux-Roses, menée par des seigneurs aux armées privées que la guerre de France avait formées. La France émergea avec une fiscalité permanente, une armée permanente et une monarchie assez forte pour dominer l'Europe. La guerre avait commencé pour un hommage féodal ; elle s'acheva ayant inventé une grande part de l'État moderne.",
      "Après Crécy, Édouard III assiégea le port de Calais onze mois, l'affamant jusqu'à la reddition en 1347. Le roi exigea que six des principaux citoyens de la ville sortent pieds nus, la corde au cou et les clés de la ville en main — comptant les pendre. Le plus riche bourgeois, Eustache de Saint-Pierre, se porta volontaire le premier ; cinq autres suivirent. Selon le chroniqueur Froissart, ils furent épargnés au dernier moment quand la reine Philippa, enceinte jusqu'aux yeux, s'agenouilla devant son époux et implora leur grâce. Calais resta plus de deux siècles le point d'appui de l'Angleterre en France — et les six bourgeois, immortalisés dans la célèbre sculpture de Rodin, devinrent l'image la plus durable du courage civique de la guerre : d'ordinaires citadins marchant vers la mort pour que leurs voisins puissent manger.",
    ],
  },
  'earlymod-01': {
    de: [
      "Die Renaissance („Wiedergeburt“) begann im 14. Jahrhundert in den wohlhabenden Stadtstaaten Norditaliens — Florenz, Venedig, Mailand. Reiche Mäzene wie die Medici in Florenz finanzierten Künstler, Architekten und Gelehrte und lösten damit eine Explosion der Schaffenskraft aus. Künstler studierten die klassischen griechischen und römischen Werke, um Perspektive, Proportion und die menschliche Gestalt zu verstehen.\n\nLeonardo da Vinci (1452–1519) verkörperte den „Renaissance-Menschen“ — Maler, Bildhauer, Wissenschaftler, Ingenieur und Anatom. Michelangelos Deckenfresko in der Sixtinischen Kapelle und seine David-Statue zählen bis heute zu den Gipfeln der abendländischen Kunst. Baumeister wie Brunelleschi entwarfen die Kuppel des Florentiner Doms mithilfe wiederentdeckter römischer Techniken.",
      "Der Humanismus der Renaissance rückte die menschliche Erfahrung und die Vernunft ins Zentrum des Geisteslebens — eine Abkehr vom mittelalterlichen Fokus auf Gott und Theologie. Gelehrte studierten die klassischen Texte in ihrem griechischen und lateinischen Original, gewannen verlorenes Wissen zurück und hinterfragten die Deutungen der Kirche.\n\nJohannes Gutenbergs Erfindung des Buchdrucks mit beweglichen Lettern um 1440 war umwälzend. Bücher, für deren Abschrift Mönche Monate brauchten, ließen sich nun in Tagen drucken. Um 1500 zirkulierten in Europa über 20 Millionen Bücher, die neue Ideen mit beispielloser Geschwindigkeit verbreiteten — und die Reformation überhaupt erst möglich machten.",
      "Portugiesische Seefahrer, auf der Suche nach einem Seeweg zum asiatischen Gewürzhandel, tasteten sich im Laufe des 15. Jahrhunderts die afrikanische Küste hinab. Vasco da Gama erreichte 1498 Indien. Zur selben Zeit gelangte Christoph Kolumbus im Dienst Spaniens 1492 in die Karibik — im Glauben, Asien gefunden zu haben.\n\nDer darauffolgende Kolumbische Austausch verwandelte beide Hemisphären. Die Europäer brachten Pferde, Rinder, Weizen und verheerende Krankheiten (Pocken, Masern) nach Amerika; zurück kehrten sie mit Kartoffeln, Tomaten, Mais und Tabak. Die indigenen Völker Amerikas, ohne Abwehrkräfte gegen die europäischen Seuchen, brachen binnen eines Jahrhunderts um bis zu 90 % ein — eine der größten demografischen Katastrophen der Geschichte.",
      "Nach Kolumbus’ Landung ging Spanien rasch daran, Amerika auszubeuten. Hernán Cortés stürzte mit 600 Spaniern und indigenen Verbündeten, die die aztekische Herrschaft verabscheuten, das Aztekenreich (1519–1521) — ein Reich von Millionen mit Zentrum in der prächtigen Inselstadt Tenochtitlan. Francisco Pizarro eroberte auf ähnliche Weise das Inkareich Südamerikas (1532–1533), nahm den Herrscher Atahualpa gefangen und ließ ihn trotz eines raumfüllenden Lösegelds aus Gold und Silber hinrichten.\n\nDie Folgen der Eroberung waren verheerend. Europäische Krankheiten töteten in manchen Regionen 50–90 % der Einheimischen. Der Zuckeranbau schuf den atlantischen Sklavenhandel, der Millionen Afrikaner auf amerikanische Plantagen verschleppte. Die spanische Kolonialherrschaft, durchgesetzt über das Zwangsarbeitssystem der Encomienda, zwang den Überlebenden eine gewaltsame neue Gesellschaftsordnung auf — und formte erstmals eine vernetzte Weltwirtschaft.",
      "Die Ideen der Renaissance verbreiteten sich im späten 15. Jahrhundert über die Alpen nach Norden. Erasmus von Rotterdam (1466–1536), der größte humanistische Gelehrte der nordischen Renaissance, nutzte die klassische Bildung, um mit Witz und Gelehrsamkeit die Verdorbenheit der Kirche zu geißeln. Thomas Morus’ „Utopia“ (1516) entwarf eine ideale, auf Vernunft gegründete Gesellschaft.\n\nIn der Kunst brachte der deutsche Maler Albrecht Dürer die italienischen Techniken der Perspektive nach Norden und schuf überwältigende Holzschnitte und Kupferstiche. Flämische Maler wie Jan van Eyck stellten das Alltagsleben mit beispiellosem Realismus dar. Später brachte William Shakespeare (1564–1616) den literarischen Humanismus der Renaissance auf die englische Bühne und erkundete die menschliche Psyche mit einer Tiefe, die nie übertroffen wurde. Der Buchdruck war für diese nördliche Ausbreitung entscheidend — er machte humanistische Texte, volkssprachliche Literatur und reformatorische Flugschriften einem lesekundigen Publikum in ganz Europa zugänglich.",
    ],
    fr: [
      "La Renaissance (« renouveau ») naquit au XIVᵉ siècle dans les riches cités-États de l’Italie du Nord — Florence, Venise, Milan. De riches mécènes comme les Médicis de Florence financèrent artistes, architectes et savants, déclenchant une explosion de créativité. Les artistes étudièrent les œuvres classiques grecques et romaines pour maîtriser la perspective, la proportion et la forme humaine.\n\nLéonard de Vinci (1452–1519) incarna l’« homme de la Renaissance » — peintre, sculpteur, savant, ingénieur et anatomiste. Le plafond de la chapelle Sixtine de Michel-Ange et son David demeurent des sommets de l’art occidental. Des architectes comme Brunelleschi conçurent le dôme de la cathédrale de Florence en s’appuyant sur des techniques romaines redécouvertes.",
      "L’humanisme de la Renaissance plaça l’expérience humaine et la raison au cœur de la vie intellectuelle — rupture avec la fixation médiévale sur Dieu et la théologie. Les savants étudièrent les textes classiques dans leur grec et leur latin d’origine, retrouvant un savoir perdu et remettant en question les interprétations de l’Église.\n\nL’invention par Johannes Gutenberg de l’imprimerie à caractères mobiles vers 1440 fut bouleversante. Des livres dont la copie prenait des mois aux moines pouvaient désormais être imprimés en quelques jours. Vers 1500, plus de 20 millions de livres circulaient en Europe, diffusant les idées nouvelles à une vitesse inédite — et rendant la Réforme possible.",
      "Les marins portugais, en quête d’une route maritime vers le commerce des épices asiatiques, longèrent peu à peu la côte africaine tout au long du XVᵉ siècle. Vasco de Gama atteignit l’Inde en 1498. Au même moment, Christophe Colomb, naviguant pour l’Espagne, atteignit les Caraïbes en 1492 — croyant avoir trouvé l’Asie.\n\nL’échange colombien qui suivit transforma les deux hémisphères. Les Européens apportèrent chevaux, bovins, blé et des maladies dévastatrices (variole, rougeole) aux Amériques ; ils en revinrent avec la pomme de terre, la tomate, le maïs et le tabac. Les populations amérindiennes, dépourvues d’immunité face aux maladies européennes, s’effondrèrent jusqu’à 90 % en un siècle — l’une des plus grandes catastrophes démographiques de l’histoire.",
      "Après le débarquement de Colomb, l’Espagne se hâta d’exploiter les Amériques. Hernán Cortés, avec 600 Espagnols et des alliés indigènes hostiles à la domination aztèque, renversa l’Empire aztèque (1519–1521) — un empire de millions d’habitants centré sur la magnifique cité insulaire de Tenochtitlan. Francisco Pizarro conquit de même l’Empire inca d’Amérique du Sud (1532–1533), capturant l’empereur Atahualpa et l’exécutant malgré une rançon d’or et d’argent emplissant une pièce entière.\n\nLes conséquences de la conquête furent dévastatrices. Les maladies européennes tuèrent 50 à 90 % des populations autochtones dans certaines régions. La culture du sucre engendra la traite atlantique, arrachant des millions d’Africains pour les plantations américaines. La domination coloniale espagnole, imposée par le travail forcé de l’encomienda, plaqua un ordre social violent sur les survivants — créant pour la première fois une économie mondiale interconnectée.",
      "Les idées de la Renaissance se diffusèrent vers le nord, par-delà les Alpes, à la fin du XVᵉ siècle. Érasme de Rotterdam (1466–1536), le plus grand savant humaniste de la Renaissance nordique, mit son érudition classique au service d’une critique spirituelle et mordante de la corruption de l’Église. L’« Utopie » de Thomas More (1516) imagina une société idéale fondée sur des principes rationnels.\n\nDans les arts, le peintre allemand Albrecht Dürer porta au nord les techniques italiennes de la perspective, créant des gravures sur bois et sur cuivre saisissantes. Des peintres flamands comme Jan van Eyck dépeignirent la vie quotidienne avec un réalisme inédit. Plus tard, William Shakespeare (1564–1616) porta l’humanisme littéraire de la Renaissance sur la scène anglaise, sondant la psychologie humaine avec une profondeur jamais égalée. L’imprimerie fut décisive pour cette expansion septentrionale — rendant textes humanistes, littérature en langue vulgaire et pamphlets réformateurs accessibles à un public lettré dans toute l’Europe.",
    ],
  },
  'earlymod-02': {
    de: [
      "Um 1500 sah sich die katholische Kirche breiter Kritik ausgesetzt — wegen Verderbtheit, Weltlichkeit und des Verkaufs von „Ablassbriefen“, Urkunden, die angeblich die Zeit im Fegefeuer verkürzten. Der päpstliche Hof in Rom lebte in ungeheurem Luxus, finanziert durch Abgaben gewöhnlicher Christen. Viele Geistliche waren ungebildet, abwesend oder offen unsittlich. Doch die Kirche duldete keinen Widerspruch; frühere Reformer wie Jan Hus waren als Ketzer verbrannt worden.",
      "Am 31. Oktober 1517 schlug der deutsche Mönch Martin Luther seine 95 Thesen an die Tür der Wittenberger Schlosskirche — eine Liste von Einwänden gegen den Ablasshandel und die Missstände der Kirche. Innerhalb weniger Wochen gedruckt und in ganz Deutschland verbreitet, entfachte Luthers Herausforderung einen Flächenbrand. Vor den Reichstag zu Worms 1521 geladen, weigerte sich Luther zu widerrufen: „Hier stehe ich, ich kann nicht anders.“\n\nVom Papst gebannt, entfesselte Luther die protestantische Reformation und lehrte, das Heil komme allein durch den Glauben (sola fide), nicht durch kirchliche Riten. Weitere Reformer folgten — Zwingli in Zürich, Calvin in Genf. Um 1560 war Nordeuropa überwiegend protestantisch, was die tausendjährige Einheit des westlichen Christentums zersprengte.",
      "Die Reformation löste Generationen von Religionskriegen aus. Der Dreißigjährige Krieg (1618–1648), der als Glaubenskonflikt im Heiligen Römischen Reich begann, weitete sich zu einem gesamteuropäischen Krieg aus, der 8 Millionen Menschen tötete und Teile Deutschlands um ein Drittel entvölkerte. Die Heere verwüsteten das Land; Hunger und Pest folgten.\n\nDer Westfälische Friede (1648) beendete den Krieg und begründete neue Grundsätze: Herrscher durften die Religion ihrer Territorien bestimmen, und Staaten sollten sich nicht in die inneren Angelegenheiten anderer einmischen. Diese Prinzipien von Souveränität und Nichteinmischung wurden zum Fundament des modernen zwischenstaatlichen Systems.",
      "Englands Reformation nahm einen politischen statt eines theologischen Weges. Heinrich VIII. (reg. 1509–1547), verzweifelt auf einen männlichen Erben bedacht und vom Papst an der Annullierung seiner Ehe mit Katharina von Aragón gehindert, brach 1534 mit Rom und erklärte sich zum Obersten Haupt der Kirche von England. Er löste die Klöster auf — beschlagnahmte ihren gewaltigen Reichtum — und verteilte das Klosterland an den englischen Landadel um, was die Landschaft Englands dauerhaft umformte.\n\nDie religiöse Ordnung blieb jahrzehntelang unbeständig. Heinrichs Kinder schwankten zwischen Protestantismus (Eduard VI.), radikaler katholischer Gegenreaktion (Maria I., die fast 300 Protestanten als Ketzer verbrennen ließ) und der gemäßigten protestantisch-anglikanischen Ordnung Elisabeths I. (reg. 1558–1603). Elisabeths lange Herrschaft festigte England und brachte ein goldenes Zeitalter der Entdeckung, des Handels und der Kultur hervor — Shakespeares Theater, Drakes Weltumsegelung und die Gründung der ersten englischen Kolonien in Amerika.",
      "Statt die protestantischen Erfolge stillschweigend hinzunehmen, setzte die katholische Kirche eine umfassende innere Reformbewegung in Gang. Das Konzil von Trient (1545–1563) klärte die katholische Lehre, erneuerte die Priesterausbildung, beendete die schlimmsten Missstände und errichtete Seminare zur Heranbildung gebildeter Priester. Die Barockkunst — von leidenschaftlicher Intensität, dramatischer Beleuchtung und überwältigender Bildgewalt — wurde als Propaganda für den Glauben eingesetzt.\n\nDie 1540 von Ignatius von Loyola gegründete Gesellschaft Jesu (Jesuiten) wurde zur Stoßtruppe der Gegenreformation. Hochgebildet und diszipliniert, gründeten die Jesuiten Universitäten, betrieben Missionen in Asien und Amerika und verteidigten die katholische Theologie gegen protestantische Gelehrte. Franz Xaver brachte das Christentum nach Indien und Japan; Matteo Ricci erreichte den chinesischen Kaiserhof. Um 1600 hatte die Gegenreformation Süddeutschland, Polen und weite Teile Frankreichs für den Katholizismus bewahrt — die religiöse Karte Europas, die aus diesem Ringen hervorging, ist bis heute weitgehend erkennbar.",
    ],
    fr: [
      "Vers 1500, l’Église catholique faisait l’objet de critiques généralisées pour sa corruption, sa mondanité et la vente des « indulgences » — certificats censés réduire le temps passé au purgatoire. La cour pontificale de Rome vivait dans un luxe démesuré, financé par les impôts des chrétiens ordinaires. Nombre de clercs étaient ignorants, absents ou ouvertement immoraux. Pourtant l’Église ne tolérait aucune dissidence ; des réformateurs antérieurs comme Jan Hus avaient été brûlés comme hérétiques.",
      "Le 31 octobre 1517, le moine allemand Martin Luther cloua ses 95 thèses à la porte de l’église du château de Wittenberg — une liste d’arguments contre les indulgences et la corruption de l’Église. Imprimé et diffusé à travers l’Allemagne en quelques semaines, le défi de Luther déclencha un embrasement. Convoqué devant la Diète de Worms en 1521, Luther refusa de se rétracter : « Me voici ; je ne puis faire autrement. »\n\nExcommunié par le pape, Luther lança la Réforme protestante, affirmant que le salut venait par la foi seule (sola fide), et non par les rites de l’Église. D’autres réformateurs suivirent — Zwingli à Zurich, Calvin à Genève. Vers 1560, l’Europe du Nord était majoritairement protestante, brisant l’unité millénaire de la chrétienté occidentale.",
      "La Réforme déclencha des générations de guerres de religion. La guerre de Trente Ans (1618–1648), commencée comme un conflit religieux dans le Saint-Empire, devint une guerre européenne générale qui tua 8 millions de personnes et dépeupla certaines parties de l’Allemagne d’un tiers. Les armées ravagèrent les campagnes ; la famine et la peste suivirent.\n\nLes traités de Westphalie (1648) mirent fin à la guerre et établirent de nouveaux principes : les souverains pouvaient déterminer la religion de leurs territoires, et les États ne devaient pas s’ingérer dans les affaires intérieures les uns des autres. Ces principes de souveraineté et de non-ingérence devinrent le fondement du système international moderne des États.",
      "La Réforme anglaise emprunta une voie politique plutôt que théologique. Henri VIII (r. 1509–1547), désespérément en quête d’un héritier mâle et empêché par le pape d’annuler son mariage avec Catherine d’Aragon, rompit avec Rome en 1534 et se déclara chef suprême de l’Église d’Angleterre. Il dissout les monastères — s’emparant de leurs immenses richesses — et redistribua les terres monastiques à la gentry anglaise, remodelant durablement le paysage anglais.\n\nLe règlement religieux resta instable pendant des décennies. Les enfants d’Henri alternèrent entre protestantisme (Édouard VI), réaction catholique radicale (Marie Iʳᵉ, qui fit brûler près de 300 protestants comme hérétiques) et le règlement anglican protestant modéré d’Élisabeth Iʳᵉ (r. 1558–1603). Le long règne d’Élisabeth stabilisa l’Angleterre et produisit un âge d’or de l’exploration, du commerce et de la culture — le théâtre de Shakespeare, la circumnavigation de Drake et la fondation des premières colonies anglaises en Amérique.",
      "Plutôt que d’accepter en silence les gains protestants, l’Église catholique lança un vaste mouvement de réforme interne. Le concile de Trente (1545–1563) clarifia la doctrine catholique, réforma la formation du clergé, mit fin aux abus les plus scandaleux et établit des séminaires pour former des prêtres instruits. L’art baroque — d’une intensité émotionnelle, d’un éclairage dramatique et d’une puissance visuelle écrasante — fut déployé comme propagande pour la foi.\n\nLa Compagnie de Jésus (les jésuites), fondée par Ignace de Loyola en 1540, devint la troupe de choc de la Contre-Réforme. Hautement instruits et disciplinés, les jésuites fondèrent des universités, animèrent des missions en Asie et en Amérique, et défendirent la théologie catholique face aux savants protestants. François Xavier porta le christianisme en Inde et au Japon ; Matteo Ricci atteignit la cour impériale chinoise. Vers 1600, la Contre-Réforme avait sauvé au catholicisme l’Allemagne du Sud, la Pologne et une grande partie de la France — la carte religieuse de l’Europe issue de cette lutte reste largement reconnaissable aujourd’hui.",
    ],
  },
  'earlymod-03': {
    de: [
      "Über tausend Jahre lang glaubten die Europäer, die Erde ruhe unbeweglich im Mittelpunkt des Universums. 1543 veröffentlichte der polnische Astronom Nikolaus Kopernikus „Über die Umläufe der Himmelskörper“ und legte dar, dass die Erde die Sonne umkreise.\n\nGalileo Galilei nutzte 1609 das Fernrohr, um Berge auf dem Mond und Monde um Jupiter zu beobachten — was das kopernikanische Modell stützte. Die Kirche verurteilte Galilei 1633 und zwang ihn zum Widerruf. Doch die Beweise waren erdrückend, und die alte Kosmologie konnte nicht überleben.",
      "Isaac Newton (1642–1727) fügte ein Jahrhundert astronomischer Entdeckungen zu einem einheitlichen mathematischen Gerüst zusammen. Seine „Principia Mathematica“ (1687) beschrieben die Bewegungsgesetze und die allgemeine Gravitation — dieselbe Kraft, die einen Apfel fallen ließ, hielt den Mond auf seiner Bahn. Newton zeigte, dass die Natur nach mathematischen Gesetzen wirkt, die die menschliche Vernunft entdecken kann.\n\nDie „wissenschaftliche Revolution“ veränderte das europäische Verständnis von Wissen selbst. Francis Bacon verfocht den Empirismus — Erkenntnis durch Beobachtung und Experiment. René Descartes trug die analytische Geometrie und das Prinzip des methodischen Zweifels bei. Wissenschaft wurde zur Methode, nicht bloß zu einer Ansammlung von Fakten, und diese Methode begann jedes Fachgebiet umzugestalten.",
      "Der Erfolg der wissenschaftlichen Revolution beflügelte die Gelehrten, die Vernunft auf Gesellschaft, Staat und Religion anzuwenden. Französische Philosophen — Voltaire, Montesquieu, Rousseau, Diderot — stellten die überkommene Autorität, das religiöse Dogma und die absolute Monarchie in Frage. Montesquieus „Vom Geist der Gesetze“ forderte die Gewaltenteilung; Rousseaus „Gesellschaftsvertrag“ setzte die Legitimität der Regierung auf die Zustimmung des Volkes.\n\nDiese Ideen überquerten den Atlantik. Amerikanische Gründerväter wie Jefferson schöpften unmittelbar aus dem Denken der Aufklärung, als sie die Unabhängigkeitserklärung (1776) verfassten. In Frankreich schürten die Ideen der Aufklärung den revolutionären Zorn. Als die Französische Revolution 1789 ausbrach, hinweg fegte sie die Monarchie, den Adel und die Sonderrechte der Kirche — und formte die französische Gesellschaft nach den Grundsätzen der Aufklärung neu.",
      "Die Amerikanische Revolution (1775–1783) war das dramatischste reale Experiment der Aufklärung. Die dreizehn britischen Kolonien in Nordamerika hatten Traditionen der Selbstverwaltung entwickelt, die sie für die aufklärerischen Ideen von den natürlichen Rechten empfänglich machten. Thomas Jeffersons Unabhängigkeitserklärung (1776) griff unmittelbar auf John Lockes Theorie zurück, dass Regierungen ihre rechtmäßige Gewalt aus der Zustimmung der Regierten ableiten.\n\nDie neue amerikanische Republik, durch die Verfassung (1787) begründet, verwirklichte Montesquieus Gewaltenteilung und schuf eine föderale Struktur, die zentrale und einzelstaatliche Gewalt ausbalancierte. Die Bill of Rights (1791) verbürgte die individuellen Freiheiten gegen staatliche Übergriffe. Amerika wurde zum Laboratorium der aufklärerischen Staatstheorie — und sein Beispiel inspirierte demokratische Bewegungen weltweit für die nächsten zwei Jahrhunderte auf mächtige Weise.",
      "Die Aufklärung veränderte das Selbstverständnis der abendländischen Zivilisation und machte Vernunft, individuelle Rechte, religiöse Toleranz und wissenschaftliche Forschung zu grundlegenden Werten. Die Amerikanische und die Französische Revolution verankerten die Prinzipien der Aufklärung in Recht und Staat. Das 19. Jahrhundert sah diese Ideen sich ausbreiten — Nationalismus, Liberalismus und Verfassungsstaat formten Europa um.\n\nDoch die Aufklärung hatte beunruhigende Grenzen. Viele Philosophen, die universelle Rechte verfochten, schlossen zugleich Frauen, versklavte Völker und Nicht-Europäer aus ihren Theorien aus. Voltaire schrieb antisemitische Passagen; Jefferson besaß Sklaven. Die rationalistische Zuversicht, die menschliche Vernunft allein könne die Gesellschaft neu erschaffen, trug zum Terror der Französischen Revolution bei. Romantische Denker — die Gefühl, Natur, Überlieferung und die Grenzen der Vernunft betonten — traten der kalten Rationalität entgegen. Diese Spannung zwischen aufklärerischem Rationalismus und romantischen Gegenströmungen prägt die westliche Kultur bis heute.",
    ],
    fr: [
      "Pendant plus de mille ans, les Européens crurent que la Terre demeurait immobile au centre de l’univers. En 1543, l’astronome polonais Nicolas Copernic publia « Des révolutions des sphères célestes », affirmant que la Terre tournait autour du Soleil.\n\nGalilée utilisa la lunette en 1609 pour observer des montagnes sur la Lune et des lunes autour de Jupiter — appuyant le modèle copernicien. L’Église condamna Galilée en 1633 et le contraignit à se rétracter. Mais les preuves étaient accablantes, et l’ancienne cosmologie ne put survivre.",
      "Isaac Newton (1642–1727) fondit un siècle de découvertes astronomiques en un cadre mathématique unifié. Ses « Principia Mathematica » (1687) décrivirent les lois du mouvement et de la gravitation universelle — la même force qui faisait tomber une pomme maintenait la Lune en orbite. Newton montra que la nature obéissait à des lois mathématiques que la raison humaine pouvait découvrir.\n\nLa « révolution scientifique » transforma la manière même dont les Européens concevaient le savoir. Francis Bacon défendit l’empirisme — la connaissance acquise par l’observation et l’expérience. René Descartes apporta la géométrie analytique et le principe du doute méthodique. La science devint une méthode, et non un simple ensemble de faits, et cette méthode se mit à remodeler chaque domaine.",
      "Le succès de la révolution scientifique incita les intellectuels à appliquer la raison à la société, au gouvernement et à la religion. Les philosophes français — Voltaire, Montesquieu, Rousseau, Diderot — remirent en cause l’autorité traditionnelle, le dogme religieux et la monarchie absolue. « De l’esprit des lois » de Montesquieu plaida pour la séparation des pouvoirs ; le « Contrat social » de Rousseau posa que la légitimité du gouvernement reposait sur le consentement populaire.\n\nCes idées traversèrent l’Atlantique. Des pères fondateurs américains comme Jefferson puisèrent directement dans la pensée des Lumières en rédigeant la Déclaration d’indépendance (1776). En France, les idées des Lumières attisèrent la colère révolutionnaire. Lorsque la Révolution française éclata en 1789, elle balaya la monarchie, l’aristocratie et les privilèges particuliers de l’Église — refondant la société française sur les principes des Lumières.",
      "La Révolution américaine (1775–1783) fut l’expérience concrète la plus spectaculaire des Lumières. Les treize colonies britanniques d’Amérique du Nord avaient développé des traditions d’autonomie qui les rendaient réceptives aux idées des Lumières sur les droits naturels. La Déclaration d’indépendance de Thomas Jefferson (1776) s’appuya directement sur la théorie de John Locke selon laquelle les gouvernements tirent leurs justes pouvoirs du consentement des gouvernés.\n\nLa nouvelle république américaine établie par la Constitution (1787) mit en œuvre la séparation des pouvoirs de Montesquieu et créa une structure fédérale équilibrant l’autorité centrale et celle des États. La Déclaration des droits (1791) garantit les libertés individuelles contre les excès du gouvernement. L’Amérique devint un laboratoire de la théorie politique des Lumières — et son exemple inspira puissamment les mouvements démocratiques du monde entier pendant les deux siècles suivants.",
      "Les Lumières transformèrent la conscience que la civilisation occidentale avait d’elle-même, érigeant la raison, les droits individuels, la tolérance religieuse et l’enquête scientifique en valeurs fondatrices. Les révolutions américaine et française institutionnalisèrent les principes des Lumières dans le droit et le gouvernement. Le XIXᵉ siècle vit ces idées se répandre — nationalisme, libéralisme et gouvernement constitutionnel remodelèrent l’Europe.\n\nPourtant les Lumières avaient des limites troublantes. Nombre de philosophes qui défendaient des droits universels excluaient en même temps les femmes, les peuples asservis et les non-Européens de leurs théories. Voltaire écrivit des passages antisémites ; Jefferson possédait des esclaves. La confiance rationaliste selon laquelle la seule raison humaine pouvait refaire la société contribua à la Terreur de la Révolution française. Des penseurs romantiques — insistant sur l’émotion, la nature, la tradition et les limites de la raison — s’opposèrent au froid rationalisme. Cette tension entre le rationalisme des Lumières et les contre-courants romantiques façonne encore aujourd’hui la culture occidentale.",
    ],
  },
  'earlymod-04': {
    de: [
      "Die absolute Monarchie erreichte im Frankreich des 17. Jahrhunderts ihren Höhepunkt. Die Theorie — von Bischof Bossuet formuliert — besagte, Könige leiteten ihre Gewalt unmittelbar von Gott ab, seien keiner menschlichen Einrichtung Rechenschaft schuldig und besäßen die Souveränität über alles in ihrem Reich. Dieses „Gottesgnadentum“ rechtfertigte, dass Herrscher Parlamente, Gerichte und selbst die Kirche in ihren Landen übergingen.\n\nPraktischer Absolutismus verlangte mehr als Theorie: Er erforderte, die Macht unabhängiger Adliger zu brechen, eine der Krone treu ergebene zentrale Bürokratie aufzubauen, ein stehendes Heer zu unterhalten und eine Ideologie königlicher Pracht zu pflegen, die die Untertanen in Ehrfurcht zur Unterwerfung brachte. Kein Monarch verfolgte dieses Programm systematischer oder glänzender als Ludwig XIV. von Frankreich.",
      "Ludwig XIV. (reg. 1643–1715) erbte den Thron im Alter von vier Jahren nach dem Tod seines Vaters. Während seiner Minderjährigkeit erschütterte die Fronde Frankreich — eine Reihe adliger und volkstümlicher Aufstände, die die Monarchie beinahe stürzten. Der junge Ludwig sah aus einem Versteck, wie Pariser Mob in sein Schlafgemach eindrang; die Erfahrung härtete seine Entschlossenheit, nie wieder der Macht des Adels ausgeliefert zu sein.\n\nAls er 1661 die Regierung persönlich übernahm, erklärte sich Ludwig zum Sonnenkönig — dem Zentrum, um das alles französische Leben kreiste. Er schaffte das Amt des Ersten Ministers ab, verlangte vom Adel, an seinem Hof statt auf seinen Gütern zu leben (was dessen Unabhängigkeit lähmte), stellte ein Heer von 400 000 Mann auf und verfolgte eine aggressive Außenpolitik, die Frankreich zur beherrschenden Macht Europas machen sollte. „L’état, c’est moi“ — „Der Staat bin ich“ — brachte seine Vorstellung vollkommen zum Ausdruck.",
      "Das Schloss von Versailles war Ludwigs größte politische Leistung. 1661 begonnen und über Jahrzehnte erweitert, beherbergte es schließlich den gesamten französischen Hof — an die 20 000 Menschen, darunter Adlige, Bedienstete und Höflinge. Der Spiegelsaal des Schlosses, 73 Meter lang und mit 357 Spiegeln ausgekleidet, welche die dahinterliegenden Gärten spiegelten, war der prächtigste Raum Europas.\n\nDoch Versailles war nicht bloß architektonische Eitelkeit. Es war eine Maschine zur politischen Beherrschung. Indem Ludwig die mächtigsten Adligen Frankreichs zwang, in Versailles zu leben und um königliche Gunst zu wetteifern — die Kerze des Königs zu halten, sein Hemd zu reichen —, verwandelte er potenzielle Rebellen in Höflinge, deren Macht ganz aus seiner Gunst erwuchs. Fern ihrer Güter und durch aufwendiges Hofzeremoniell abgelenkt, verloren die französischen Adligen die unabhängigen Machtbasen, die die Monarchie hätten bedrohen können. Jede Zeremonie, jedes Gemälde, jeder Springbrunnen war Propaganda, die Ludwigs göttliche Erhabenheit behauptete.",
      "Religiöse Einheitlichkeit gehörte fest zu Ludwigs Vorstellung von absoluter Macht. Frankreich hatte den protestantischen Hugenotten im Edikt von Nantes (1598) Glaubensfreiheiten gewährt und damit einen Staat im Staate geschaffen, den Ludwig unerträglich fand. 1685 widerrief er das Edikt, erklärte den Protestantismus für gesetzwidrig und zwang die Hugenotten, überzutreten, zu fliehen oder Verfolgung zu erleiden.\n\nDie Folgen waren katastrophal für Frankreich und vorteilhaft für seine Rivalen. Etwa 200 000 Hugenotten flohen — viele von ihnen geschickte Handwerker, Kaufleute und Gelehrte. Preußen, England und die Niederländische Republik nahmen diese Flüchtlinge begierig auf und gewannen deren Fertigkeiten und Kapital, während Frankreich sie verlor. Friedrich Wilhelm von Brandenburg-Preußen bot jeder Hugenottenfamilie die Ansiedlung an und gewann Seidenweber, Uhrmacher und Finanziers, die Preußens wirtschaftliche Entwicklung beflügelten. Ludwigs Bigotterie stärkte so seine Feinde auf Kosten Frankreichs.",
      "Trotz Ludwigs überwältigender Macht hatte die absolute Monarchie erhebliche Grenzen. Der König war auf die Mitwirkung der Provinzeliten, der Kirche und der Ämterkäufer angewiesen, die ihre Stellen erworben hatten. Die Steuererhebung war ineffizient; Kriege waren ruinös teuer. Bei Ludwigs Tod 1715 war Frankreich von Jahrzehnten des Krieges erschöpft — allein der Spanische Erbfolgekrieg kostete Frankreich gewaltige Mittel und endete mit dem Frieden von Utrecht (1713), der die französische Vorherrschaft in Europa vereitelte.\n\nDoch das Erbe des Absolutismus reichte über Frankreich hinaus. Peter der Große von Russland nahm sich bewusst Ludwig XIV. zum Vorbild und holte französische Architekten und Höflinge, um Russland zu verwestlichen. Friedrich der Große von Preußen, Maria Theresia von Österreich und Katharina die Große von Russland übten alle einen „aufgeklärten Absolutismus“ — der königliche Macht mit Reformen im Geist der Aufklärung verband. Der Absolutismus erzeugte auch seine eigene Kritik: Locke, Montesquieu und Rousseau entwickelten Theorien der begrenzten Regierung und der Volkssouveränität, die die Amerikanische und die Französische Revolution befeuern und schließlich die absoluten Monarchien zerstören sollten, welche die absolutistische Theorie errichtet hatte.",
    ],
    fr: [
      "La monarchie absolue atteignit son apogée dans la France du XVIIᵉ siècle. La théorie — formulée par l’évêque Bossuet — soutenait que les rois tenaient leur autorité directement de Dieu, ne devaient de comptes à aucune institution humaine et détenaient la souveraineté sur tout ce qui se trouvait dans leur royaume. Ce « droit divin des rois » justifiait que les souverains passent outre parlements, tribunaux et jusqu’à l’Église dans leurs domaines.\n\nL’absolutisme concret exigeait plus que la théorie : il fallait briser la puissance des nobles indépendants, créer une bureaucratie centralisée fidèle à la couronne, entretenir une armée professionnelle et cultiver une idéologie de magnificence royale qui frappait les sujets de respect et de soumission. Aucun monarque ne poursuivit ce programme de façon plus systématique ni plus brillante que Louis XIV de France.",
      "Louis XIV (r. 1643–1715) hérita du trône à quatre ans, après la mort de son père. Durant sa minorité, la France fut secouée par la Fronde — une série de révoltes aristocratiques et populaires qui faillirent renverser la monarchie. Le jeune Louis vit, caché, la foule parisienne envahir sa chambre ; l’expérience durcit sa résolution de ne plus jamais être vulnérable au pouvoir nobiliaire.\n\nPrenant en main personnellement le gouvernement en 1661, Louis se proclama le Roi-Soleil — le centre autour duquel gravitait toute la vie française. Il abolit la charge de premier ministre, obligea les nobles à vivre à sa cour plutôt que sur leurs terres (neutralisant leur indépendance), leva une armée de 400 000 hommes et mena une politique étrangère agressive visant à faire de la France la puissance dominante de l’Europe. « L’État, c’est moi » résuma parfaitement sa vision.",
      "Le château de Versailles fut la plus grande réussite politique de Louis. Commencé en 1661 et agrandi durant des décennies, il finit par abriter toute la cour de France — quelque 20 000 personnes, nobles, serviteurs et courtisans. La galerie des Glaces du palais, longue de 73 mètres et bordée de 357 miroirs reflétant les jardins, était la salle la plus spectaculaire d’Europe.\n\nMais Versailles n’était pas simple vanité architecturale. C’était une machine de contrôle politique. En obligeant les nobles les plus puissants de France à vivre à Versailles et à rivaliser pour les faveurs royales — tenir le bougeoir du roi, lui porter sa chemise —, Louis transforma des rebelles potentiels en courtisans dont le pouvoir venait entièrement de son approbation. Loin de leurs terres et distraits par un rituel de cour élaboré, les nobles français perdirent les bases de pouvoir indépendantes qui auraient pu menacer la monarchie. Chaque cérémonie, chaque tableau, chaque fontaine était une propagande affirmant la grandeur divine de Louis.",
      "L’uniformité religieuse faisait partie intégrante de la vision du pouvoir absolu de Louis. La France avait accordé aux protestants huguenots des libertés religieuses par l’édit de Nantes de 1598, créant un État dans l’État que Louis jugeait intolérable. En 1685, il révoqua l’édit, déclarant le protestantisme illégal et contraignant les huguenots à se convertir, à fuir ou à subir la persécution.\n\nLes conséquences furent catastrophiques pour la France et bénéfiques pour ses rivaux. Environ 200 000 huguenots s’enfuirent — nombre d’entre eux artisans qualifiés, marchands et intellectuels. La Prusse, l’Angleterre et la République néerlandaise accueillirent avidement ces réfugiés, gagnant leurs compétences et leurs capitaux tandis que la France les perdait. Frédéric-Guillaume de Brandebourg-Prusse offrit la réinstallation à toute famille huguenote, gagnant tisserands de soie, horlogers et financiers qui dopèrent le développement économique prussien. Le fanatisme de Louis renforça ainsi ses ennemis aux dépens de la France.",
      "Malgré la puissance redoutable de Louis, la monarchie absolue avait des limites considérables. Le roi dépendait de la coopération des élites provinciales, de l’Église et des officiers vénaux qui avaient acheté leurs charges. La perception des impôts était inefficace ; les guerres ruineusement coûteuses. À la mort de Louis en 1715, la France était épuisée par des décennies de guerre — la seule guerre de Succession d’Espagne coûta à la France d’immenses ressources et se termina par le traité d’Utrecht (1713), qui bloqua l’hégémonie française en Europe.\n\nPourtant l’héritage de l’absolutisme dépassa la France. Pierre le Grand de Russie se modela consciemment sur Louis XIV, important architectes et courtisans français pour occidentaliser la Russie. Frédéric le Grand de Prusse, Marie-Thérèse d’Autriche et Catherine la Grande de Russie pratiquèrent tous un « despotisme éclairé » — mêlant pouvoir royal et réformes inspirées des Lumières. L’absolutisme engendra aussi sa propre critique : Locke, Montesquieu et Rousseau élaborèrent des théories du gouvernement limité et de la souveraineté populaire qui allaient alimenter les révolutions américaine et française, et finalement détruire les monarchies absolues que la théorie absolutiste avait édifiées.",
    ],
  },
  'earlymod-05': {
    de: [
      "Der transatlantische Sklavenhandel entsprang dem Zusammentreffen von europäischem Kolonialismus, Zuckerrevolution und dem katastrophalen Zusammenbruch der indigenen Bevölkerung Amerikas. Zucker — „weißes Gold“ — gedieh nur in tropischem Klima und erforderte gewaltige Mengen brutaler Arbeit beim Anbau, bei der Ernte und der Verarbeitung. Die Portugiesen begründeten ab den 1530er Jahren den Zuckeranbau in Brasilien mit versklavten Afrikanern; das System breitete sich in die Karibik aus, als niederländische, englische und französische Kolonien im 17. Jahrhundert expandierten.\n\nUm die Mitte des 17. Jahrhunderts waren die karibischen Zuckerinseln — Barbados, Jamaika, Saint-Domingue (Haiti), Kuba — sagenhaft einträglich geworden. Eine einzige jamaikanische Zuckerplantage warf jährlich 10 % Rendite oder mehr ab. Diese Rentabilität schuf einen unstillbaren Bedarf an Arbeitskräften. Die indigene Bevölkerung war durch europäische Seuchen weitgehend ausgelöscht worden; europäische Vertragsknechte waren teuer und nur befristet verfügbar. Versklavte Afrikaner, beschafft aus westafrikanischen Königreichen mit jahrhundertelanger Erfahrung im Sklavenhandel, wurden zur Antwort.",
      "Der transatlantische Sklavenhandel funktionierte über ein brutales Dreieckssystem. Europäische Schiffe liefen mit Fertigwaren aus — Textilien, Gewehren, Eisenstangen, Alkohol — zu westafrikanischen Häfen. Dort handelten sie mit afrikanischen Königen, Kaufleuten und Sklavenjägern, die im Landesinneren in Kriegen und Überfällen gefangene Menschen lieferten. Die Versklavten wurden dann über den Atlantik gebracht — die Mittelpassage — und an Pflanzer in Amerika verkauft. Die Schiffe kehrten mit Zucker, Tabak, Baumwolle und Rum beladen nach Europa zurück.\n\nZwischen etwa 1500 und 1900 wurden schätzungsweise 12,5 Millionen Afrikaner gewaltsam auf Sklavenschiffe verladen, überwiegend von den west- und zentralafrikanischen Küsten — der Bucht von Benin, dem Kongobecken, Senegambien und Angola. Von ihnen überlebten rund 10,7 Millionen die Überfahrt. Auf ihrem Höhepunkt im 18. Jahrhundert überquerten jedes Jahr 80 000 versklavte Afrikaner den Atlantik. Der Handel bezog jede große europäische Seemacht ein — Portugal, Spanien, Britannien, Frankreich, die Niederlande und Dänemark — und seine Gewinne finanzierten Bankwesen, Manufakturen und koloniale Infrastruktur in ganz Europa.",
      "Die Mittelpassage — die Seereise von Afrika nach Amerika — war eine der langwierigsten Gräueltaten der Geschichte. Die Versklavten wurden mit entsetzlicher Dichte in die Schiffsräume gepfercht, paarweise angekettet, in Zwischendecks von zuweilen nur 45 cm Höhe. Die Reise dauerte je nach Wetter und Ziel drei bis acht Wochen. Die Sterblichkeit durch Ruhr, Pocken, Skorbut und Verdursten lag zwischen 15 % und 20 % — was bedeutete, dass einer von sechs Versklavten während der Überfahrt starb.\n\nWiderstand war ständig. Aufstände an Bord von Sklavenschiffen waren trotz der äußersten Nachteile der Versklavten — Ketten, unterschiedliche Sprachen zwischen den afrikanischen Gruppen und bewaffnete Besatzungen — verbreitet. Der erfolgreichste Aufstand auf einem Sklavenschiff ereignete sich 1839 an Bord der Amistad, als versklavte Afrikaner unter Führung von Sengbe Pieh das Schiff kaperten und schließlich vor amerikanischen Gerichten ihre Freiheit erlangten. Die gelebte Erfahrung der Mittelpassage — die über Bord geworfenen Leichen, die von ihren Eltern getrennten Kinder, die planmäßige Entmenschlichung — wurde von Überlebenden bezeugt und bildete das moralische Fundament der Abolitionsbewegung.",
      "In den Plantagenkolonien Amerikas schufteten die Versklavten unter Bedingungen außerordentlicher Grausamkeit. Auf Zuckerplantagen — der tödlichsten Umgebung — konnten die jährlichen Sterberaten 5–10 % erreichen, sodass die versklavte Bevölkerung ständigen Nachschub aus Afrika erforderte. Die Versklavten arbeiteten während der Erntezeit 18-Stunden-Tage und bedienten die Maschinen der Zuckermühle rund um die Uhr. Strafen für Widerstand, langsame Arbeit oder vermeintliche Unverschämtheit waren grausam und öffentlich, darauf angelegt zu terrorisieren.\n\nDoch die Versklavten waren nie bloß passive Opfer. Sie bewahrten afrikanische kulturelle und religiöse Überlieferungen — Musik, Tanz, Sprache, Spiritualität —, die Gemeinschaft schufen und Widerstand nährten. Maroon-Gemeinschaften entflohener Versklavter gründeten unabhängige Gesellschaften in den Bergen Jamaikas, den Wäldern Surinames und dem brasilianischen Landesinneren. Sklavenaufstände durchzogen die gesamte Geschichte der Sklaverei in der Neuen Welt; die Haitianische Revolution (1791–1804) war der einzige erfolgreiche große Sklavenaufstand der Geschichte, brachte die erste schwarze Republik hervor und veränderte die Debatten über Sklaverei und Freiheit weltweit dauerhaft.",
      "Die Abolitionsbewegung entstand im späten 18. Jahrhundert aus dem Zusammenfließen von aufklärerischem Denken, quäkerischen Glaubensgrundsätzen und den Zeugnissen ehemals Versklavter wie Olaudah Equiano, dessen veröffentlichte Autobiografie (1789) den britischen Lesern die Wirklichkeit der Sklaverei mit vernichtender Wucht vor Augen führte. Die Bewegung mobilisierte Kampagnen an der Basis — Petitionen mit Hunderttausenden Unterschriften, Zuckerboykotte, Flugschriften —, die über Jahrzehnte anhaltenden politischen Druck aufbauten.\n\nBritannien schaffte 1807 den Sklavenhandel und 1833 die Sklaverei selbst ab — entschädigte die Sklavenhalter mit 20 Millionen Pfund (über einen erst 2015 getilgten Kredit finanziert), während es den ehemals Versklavten nichts gewährte. Die Vereinigten Staaten schafften die Sklaverei erst nach dem Bürgerkrieg 1865 ab. Das Erbe des transatlantischen Sklavenhandels wirkt fort in strukturellen rassistischen Ungleichheiten in ganz Amerika, in der demografischen Umwälzung der Karibik und Brasiliens und in dem kulturellen Reichtum — Musik, Sprache, Religion —, den die afrikanischen Überlebenden und ihre Nachkommen unter Bedingungen äußerster Unterdrückung schufen. Diese Geschichte zu verstehen ist unerlässlich, um die heutige Welt zu verstehen.",
    ],
    fr: [
      "La traite atlantique naquit de la rencontre du colonialisme européen, de la révolution sucrière et de l’effondrement catastrophique des populations amérindiennes. Le sucre — l’« or blanc » — ne poussait qu’en climat tropical et exigeait d’immenses quantités de travail brutal pour la plantation, la récolte et la transformation. Les Portugais furent les pionniers de la culture sucrière au Brésil avec des Africains asservis dès les années 1530 ; le système gagna les Caraïbes à mesure que les colonies néerlandaises, anglaises et françaises s’étendaient au XVIIᵉ siècle.\n\nAu milieu du XVIIᵉ siècle, les îles sucrières des Caraïbes — Barbade, Jamaïque, Saint-Domingue (Haïti), Cuba — étaient devenues fabuleusement rentables. Une seule plantation sucrière jamaïcaine rapportait 10 % ou plus par an. Cette rentabilité créa une demande insatiable de main-d’œuvre. Les autochtones avaient été largement décimés par les maladies européennes ; les engagés européens étaient coûteux et temporaires. Les Africains asservis, fournis par des royaumes ouest-africains riches de siècles d’expérience dans la traite, devinrent la réponse.",
      "La traite atlantique opérait par un système triangulaire brutal. Les navires européens partaient avec des produits manufacturés — textiles, fusils, barres de fer, alcool — vers les ports d’Afrique de l’Ouest. Là, ils commerçaient avec des rois, marchands et pillards africains qui fournissaient des captifs pris lors de guerres et de razzias dans l’intérieur. Les asservis étaient alors transportés à travers l’Atlantique — le passage du milieu — et vendus aux planteurs des Amériques. Les navires regagnaient l’Europe chargés de sucre, tabac, coton et rhum.\n\nEntre 1500 et 1900 environ, on estime à 12,5 millions le nombre d’Africains embarqués de force sur des navires négriers, surtout depuis les côtes de l’Afrique occidentale et centrale — la baie du Bénin, le bassin du Congo, la Sénégambie et l’Angola. Sur ce total, environ 10,7 millions survécurent à la traversée. À son apogée au XVIIIᵉ siècle, 80 000 Africains asservis traversaient l’Atlantique chaque année. La traite impliqua toutes les grandes puissances maritimes européennes — Portugal, Espagne, Grande-Bretagne, France, Provinces-Unies et Danemark — et ses profits financèrent la banque, la manufacture et l’infrastructure coloniale dans toute l’Europe.",
      "Le passage du milieu — la traversée maritime d’Afrique aux Amériques — fut l’une des atrocités les plus prolongées de l’histoire. Les asservis étaient entassés dans les cales avec une densité effroyable, enchaînés par deux, allongés dans des espaces parfois hauts de 45 cm seulement. La traversée durait de trois à huit semaines selon le temps et la destination. La mortalité par dysenterie, variole, scorbut et déshydratation oscillait entre 15 % et 20 % — soit un asservi sur six mort durant la traversée.\n\nLa résistance était continue. Les révoltes à bord des navires négriers étaient fréquentes malgré les désavantages extrêmes des asservis — chaînes, langues différentes entre groupes africains, équipages armés. La révolte de navire négrier la plus réussie survint à bord de l’Amistad en 1839, quand des Africains asservis menés par Sengbe Pieh s’emparèrent du bâtiment et obtinrent finalement leur liberté devant les tribunaux américains. L’expérience vécue du passage du milieu — les corps jetés par-dessus bord, les enfants séparés de leurs parents, la déshumanisation délibérée — fut documentée par les survivants et forma le socle moral du mouvement abolitionniste.",
      "Dans les colonies de plantation des Amériques, les asservis peinaient dans des conditions d’une brutalité extraordinaire. Sur les plantations sucrières — l’environnement le plus mortel — les taux de mortalité annuels pouvaient atteindre 5 à 10 %, si bien que la population asservie exigeait un réapprovisionnement constant depuis l’Afrique. Les asservis travaillaient 18 heures par jour pendant la récolte, faisant tourner les machines du moulin à sucre jour et nuit. Les châtiments pour résistance, lenteur ou insolence supposée étaient sauvages et publics, conçus pour terroriser.\n\nPourtant les asservis ne furent jamais des victimes passives. Ils préservèrent des traditions culturelles et religieuses africaines — musique, danse, langue, spiritualité — qui créaient la communauté et nourrissaient la résistance. Des communautés marronnes d’asservis évadés fondèrent des sociétés indépendantes dans les montagnes de la Jamaïque, les forêts du Suriname et l’intérieur du Brésil. Les révoltes d’esclaves ponctuèrent toute l’histoire de l’esclavage du Nouveau Monde ; la Révolution haïtienne (1791–1804) fut la seule grande rébellion d’esclaves réussie de l’histoire, donnant naissance à la première république noire et transformant durablement les débats mondiaux sur l’esclavage et la liberté.",
      "Le mouvement abolitionniste émergea à la fin du XVIIIᵉ siècle de la convergence de la pensée des Lumières, des principes religieux quakers et des témoignages d’anciens asservis comme Olaudah Equiano, dont l’autobiographie publiée (1789) fit connaître la réalité de l’esclavage aux lecteurs britanniques avec un effet dévastateur. Le mouvement mobilisa des campagnes populaires — pétitions signées par des centaines de milliers de personnes, boycotts du sucre, pamphlets — qui bâtirent une pression politique soutenue pendant des décennies.\n\nLa Grande-Bretagne abolit la traite en 1807 et l’esclavage lui-même en 1833 — indemnisant les propriétaires d’esclaves de 20 millions de livres (financés par un emprunt remboursé seulement en 2015) sans rien accorder aux anciens asservis. Les États-Unis n’abolirent l’esclavage qu’après la guerre de Sécession, en 1865. L’héritage de la traite atlantique persiste dans les inégalités raciales structurelles à travers les Amériques, la transformation démographique des Caraïbes et du Brésil, et la richesse culturelle — musique, langue, religion — que les survivants africains et leurs descendants créèrent dans des conditions d’oppression extrême. Comprendre cette histoire est essentiel pour comprendre le monde contemporain.",
    ],
  },
  'earlymod-06': {
    de: [
      "Das Osmanische Reich wurde um 1299 vom türkischen Häuptling Osman I. im Nordwesten Anatoliens gegründet — eines von Dutzenden kleinen türkischen Fürstentümern, die nach der mongolischen Zerstörung des Seldschukensultanats entstanden. Was die Osmanen auszeichnete, war ihre Lage an der byzantinischen Grenze — eine Geografie, die eine auf ständige Ausdehnung ausgerichtete Kriegerkultur hervorbrachte und muslimische Glaubenskämpfer (Ghazi) aus der ganzen islamischen Welt anzog.\n\nDie osmanische Expansion verlief mit bemerkenswerter Geschwindigkeit. Bis 1389 hatten osmanische Truppen das serbische Königreich in der Schlacht auf dem Amselfeld besiegt und den Balkan unter ihre Kontrolle gebracht. 1453 vollbrachte Sultan Mehmed II. („der Eroberer“), was in acht Jahrhunderten kein muslimischer Herrscher geschafft hatte: Er eroberte Konstantinopel, die alte römische Hauptstadt und Sitz des östlichen Christentums, und durchbrach mit gewaltigen Bronzekanonen seine legendären Mauern. Der Fall Konstantinopels erschütterte das christliche Europa und verschaffte den Osmanen die unangefochtene Kontrolle über die Meerengen zwischen Mittelmeer und Schwarzem Meer — den strategisch bedeutendsten Ort der bekannten Welt.",
      "Süleyman I., der 1520 im Alter von sechsundzwanzig Jahren an die Macht kam, stand dem Höhepunkt der osmanischen Zivilisation vor. Die Europäer nannten ihn „den Prächtigen“ wegen seines Glanzes und seiner militärischen Macht; seine eigenen Untertanen nannten ihn „Kanuni“ — den Gesetzgeber — wegen seiner bleibendsten Leistung: einer umfassenden Kodifizierung des osmanischen Rechts (Kanun), die die islamische Scharia mit osmanischem Verwaltungsbrauch in Einklang brachte.\n\nSüleymans Gesetzbuch regelte Besteuerung, Landbesitz, Strafjustiz und das Verhalten der Amtsträger. Es war für seine Zeit bemerkenswert fortschrittlich — schützte die Bauern vor willkürlicher Enteignung, setzte Strafen Grenzen und begründete Garantien eines geordneten Verfahrens. Sein Großwesir Ibrahim Pascha führte die tägliche Verwaltung mit außerordentlicher Wirksamkeit; der kaiserliche Rat (Diwan) arbeitete mit einer Raffinesse, um die ihn europäische Monarchen beneideten. Süleymans Hof im Topkapı-Palast, in dem 30 000 Menschen lebten und arbeiteten, war der prächtigste der Welt — ein Zentrum der Architektur, Dichtung, Kalligrafie und wissenschaftlichen Gelehrsamkeit.",
      "Süleymans Feldzüge veränderten die Landkarte der Welt. 1521 nahm er Belgrad ein — das Tor nach Mitteleuropa. 1522 vertrieb er die Johanniter nach sechsmonatiger Belagerung von Rhodos. In der Schlacht bei Mohács 1526 vernichteten die osmanischen Truppen das ungarische Heer und töteten den jungen König Ludwig II., was den größten Teil Ungarns unter osmanische Kontrolle brachte. Die Belagerung Wiens 1529 bezeichnete den westlichsten Vorstoß osmanischer Macht nach Europa, gestoppt weniger durch habsburgischen Widerstand als durch überdehnte Nachschublinien und den Einbruch des Winters.\n\nZur See besiegte der osmanische Admiral Hayreddin Barbarossa 1538 bei Preveza die vereinigte christliche Flotte und begründete die osmanische Vorherrschaft im Mittelmeer. Die Osmanen dehnten ihren Einfluss bis in den Indischen Ozean aus und forderten die portugiesische Kontrolle über den Gewürzhandel heraus. Bei Süleymans Tod 1566 — er starb während eines Feldzugs in Ungarn — erstreckte sich das Reich von Algerien bis Aserbaidschan, von Ungarn bis in den Jemen. Die Verwaltung dieses riesigen Gebiets erforderte einen ausgefeilten Verwaltungsapparat: Statthalter (Paschas), eine leistungsbasierte militärisch-administrative Klasse (das Devschirme-System, das begabte Knaben aus den eroberten christlichen Bevölkerungen rekrutierte) und die wirksamste Bürokratie der Welt.",
      "Das Osmanische Reich regierte eine außerordentlich vielfältige Bevölkerung durch das Millet-System: Nichtmuslimische Gemeinschaften (orthodoxe Christen, armenische Christen, Juden) waren als halbautonome Gemeinschaften unter ihren eigenen religiösen Oberhäuptern organisiert, die dem osmanischen Staat für das Verhalten und die Steuerzahlungen ihrer Gemeinschaften verantwortlich waren. Innerhalb ihrer Millets unterhielten diese Gemeinschaften eigene Gerichte, Schulen und religiöse Einrichtungen.\n\nDieses System war keine Utopie — Nichtmuslime zahlten die Dschizya (Kopfsteuer) und sahen sich mancherlei rechtlichen Nachteilen ausgesetzt. Doch verglichen mit den religiösen Verfolgungen im Europa der Reformation — wo protestantische und katholische Gemeinschaften einander folterten und verbrannten — war die osmanische Toleranz real und bedeutend. Als die spanische Inquisition 1492 die Juden vertrieb, warb Sultan Bayezid II. sie aktiv für die osmanischen Städte an und spottete berühmt über Ferdinand von Aragón, er „verarme sein Königreich, während er meines bereichere“. Jüdische, armenische und griechische Gemeinschaften gediehen als Kaufleute, Ärzte und Gelehrte in Istanbul, Thessaloniki und anderen osmanischen Städten.",
      "Das Osmanische Reich brachte prächtige kulturelle Leistungen hervor. Der Baumeister Mimar Sinan (1489–1588), ein griechischer Christ, der durch die Devschirme ausgehoben worden war, entwarf über 300 Bauwerke für Süleyman und seine Nachfolger — darunter die Süleymaniye-Moschee in Istanbul und die Selimiye-Moschee in Edirne, die als Gipfel osmanischer Architektur gelten. Osmanische Dichtung, Kalligrafie, Miniaturmalerei und Keramikkunst (İznik-Fliesen) erreichten eine Verfeinerung, die die islamische Kunst weltweit prägte.\n\nDas Osmanische Reich überlebte Süleyman um mehr als drei Jahrhunderte und löste sich schließlich nach dem Ersten Weltkrieg 1922 auf. Bei seinem Untergang wurde es durch einen türkischen Reststaat unter Mustafa Kemal Atatürk ersetzt, der das Kalifat abschaffte und die türkischen Einrichtungen planmäßig verwestlichte. Das osmanische Erbe prägt den modernen Nahen Osten tiefgreifend: Die willkürliche Auflösung des Reiches durch die europäischen Mächte nach dem Ersten Weltkrieg — die Zerstückelung arabischer Gebiete im Sykes-Picot-Abkommen — schuf die Grenzen des Irak, Syriens, des Libanon und Palästinas und begründete Konflikte, die bis heute ungelöst sind. Die Osmanen zu verstehen ist unerlässlich, um den heutigen Nahen Osten zu verstehen.",
    ],
    fr: [
      "L’Empire ottoman fut fondé vers 1299 par le chef turc Osman Iᵉʳ dans le nord-ouest de l’Anatolie — l’une des dizaines de petites principautés turques nées après la destruction mongole du sultanat seldjoukide. Ce qui distinguait les Ottomans, c’était leur position sur la frontière byzantine — une géographie qui engendra une culture guerrière tournée vers l’expansion continue et attira des combattants de la foi musulmans (ghazi) de tout le monde islamique.\n\nL’expansion ottomane progressa à une vitesse remarquable. Dès 1389, les forces ottomanes avaient défait le royaume serbe à la bataille du Kosovo, plaçant les Balkans sous leur contrôle. En 1453, le sultan Mehmed II (« le Conquérant ») accomplit ce qu’aucun souverain musulman n’avait réussi en huit siècles : il prit Constantinople, l’antique capitale romaine et siège de la chrétienté orientale, à l’aide de gigantesques canons de bronze pour percer ses murailles légendaires. La chute de Constantinople bouleversa l’Europe chrétienne et donna aux Ottomans la maîtrise incontestée des détroits reliant la Méditerranée et la mer Noire — le site le plus stratégique du monde connu.",
      "Soliman Iᵉʳ, arrivé au pouvoir en 1520 à vingt-six ans, présida à l’apogée de la civilisation ottomane. Les Européens l’appelaient « le Magnifique » pour sa splendeur et sa puissance militaire ; ses propres sujets l’appelaient « Kanuni » — le Législateur — pour sa réalisation la plus durable : une codification complète du droit ottoman (kanun) harmonisant la charia islamique avec la coutume administrative ottomane.\n\nLe code de Soliman réglementait la fiscalité, la tenure des terres, la justice pénale et la conduite des fonctionnaires. Il était remarquablement progressiste pour son époque — protégeant les paysans de l’expropriation arbitraire, limitant les châtiments et établissant des garanties de procédure régulière. Son grand vizir Ibrahim Pacha gérait l’administration quotidienne avec une efficacité extraordinaire ; le conseil impérial (Divan) fonctionnait avec un raffinement que les monarques européens enviaient. La cour de Soliman au palais de Topkapı, où vivaient et travaillaient 30 000 personnes, était la plus magnifique du monde — un centre d’architecture, de poésie, de calligraphie et de savoir scientifique.",
      "Les campagnes militaires de Soliman redessinèrent la carte du monde. En 1521, il prit Belgrade — porte de l’Europe centrale. En 1522, il chassa les Chevaliers de Saint-Jean de Rhodes après un siège de six mois. À la bataille de Mohács en 1526, les forces ottomanes anéantirent l’armée hongroise et tuèrent le jeune roi Louis II, plaçant la majeure partie de la Hongrie sous contrôle ottoman. Le siège de Vienne en 1529 marqua l’avancée la plus occidentale de la puissance ottomane en Europe, arrêtée moins par la résistance des Habsbourg que par des lignes de ravitaillement surtendues et l’arrivée de l’hiver.\n\nSur mer, l’amiral ottoman Khayr ad-Din Barberousse défit la flotte chrétienne combinée à Préveza en 1538, établissant la domination ottomane sur la Méditerranée. Les Ottomans étendirent leur portée jusqu’à l’océan Indien, défiant le contrôle portugais du commerce des épices. À la mort de Soliman en 1566 — il mourut en campagne en Hongrie — l’empire s’étendait de l’Algérie à l’Azerbaïdjan, de la Hongrie au Yémen. Gouverner ce vaste territoire exigeait un appareil administratif sophistiqué : gouverneurs (pachas), classe militaro-administrative méritocratique (le système du devchirmé, recrutant des garçons talentueux parmi les populations chrétiennes conquises) et la bureaucratie la plus efficace du monde.",
      "L’Empire ottoman gouvernait une population d’une extraordinaire diversité par le système du millet : les communautés non musulmanes (chrétiens orthodoxes, chrétiens arméniens, juifs) étaient organisées en communautés semi-autonomes sous leurs propres chefs religieux, responsables devant l’État ottoman de la conduite et des impôts de leurs communautés. Au sein de leurs millets, ces communautés conservaient leurs propres tribunaux, écoles et institutions religieuses.\n\nCe système n’était pas une utopie — les non-musulmans payaient la jizya (capitation) et subissaient divers désavantages juridiques. Mais comparée aux persécutions religieuses de l’Europe de la Réforme — où communautés protestantes et catholiques se torturaient et se brûlaient — la tolérance ottomane était réelle et significative. Quand l’Inquisition espagnole expulsa les juifs en 1492, le sultan Bayezid II les recruta activement pour les villes ottomanes, raillant fameusement Ferdinand d’Aragon qui « appauvrissait son royaume tout en enrichissant le mien ». Les communautés juives, arméniennes et grecques prospérèrent comme marchands, médecins et savants à Istanbul, Thessalonique et d’autres villes ottomanes.",
      "L’Empire ottoman produisit de magnifiques réalisations culturelles. L’architecte Mimar Sinan (1489–1588), chrétien grec enrôlé par le devchirmé, conçut plus de 300 édifices pour Soliman et ses successeurs — parmi lesquels la mosquée Süleymaniye d’Istanbul et la mosquée Selimiye d’Edirne, considérée comme le sommet de l’architecture ottomane. La poésie, la calligraphie, la peinture de miniatures et les arts céramiques ottomans (carreaux d’İznik) atteignirent des sommets de raffinement qui façonnèrent l’art islamique du monde entier.\n\nL’Empire ottoman survécut à Soliman de plus de trois siècles, se dissolvant finalement après la Première Guerre mondiale en 1922. À son effondrement, il fut remplacé par un État turc croupion sous Mustafa Kemal Atatürk, qui abolit le califat et occidentalisa méthodiquement les institutions turques. L’héritage ottoman façonne profondément le Moyen-Orient moderne : la dissolution arbitraire de l’empire par les puissances européennes après la Première Guerre mondiale — le découpage des territoires arabes dans les accords Sykes-Picot — créa les frontières de l’Irak, de la Syrie, du Liban et de la Palestine, engendrant des conflits qui demeurent irrésolus à ce jour. Comprendre les Ottomans est essentiel pour comprendre le Moyen-Orient contemporain.",
    ],
  },
  'earlymod-07': {
    de: [
      "In den 1760er Jahren hatten Britanniens dreizehn amerikanische Kolonien eine eigene politische Kultur entwickelt, verwurzelt in aufklärerischen Ideen von natürlichen Rechten, Repräsentativregierung und Gesellschaftsvertrag. Als Britannien nach dem Siebenjährigen Krieg neue Steuern auferlegte — den Stamp Act (1765), die Townshend Acts (1767) —, ohne den Kolonisten eine Vertretung im Parlament zu gewähren, verdichtete der Slogan „keine Besteuerung ohne Vertretung“ eine verfassungsrechtliche Beschwerde zu einem revolutionären Programm.\n\nDie Boston Tea Party vom Dezember 1773, bei der Kolonisten 342 Kisten Tee in den Bostoner Hafen kippten, um gegen den Tea Act zu protestieren, provozierte harte britische Vergeltung. Der offene Konflikt begann im April 1775 bei Lexington und Concord. Der Zweite Kontinentalkongress ernannte George Washington zum Befehlshaber der Kontinentalarmee. Am 4. Juli 1776 nahm der Kongress Thomas Jeffersons Unabhängigkeitserklärung an — das folgenreichste politische Dokument der Neuzeit. Durchdrungen von der Philosophie John Lockes, verkündete sie, „alle Menschen sind gleich geschaffen“ und besitzen „unveräußerliche Rechte“ auf „Leben, Freiheit und das Streben nach Glück“, und dass die Regierung ihre rechtmäßige Gewalt aus der Zustimmung der Regierten ableite.",
      "Der Unabhängigkeitskrieg (1775–1783) war keineswegs unausweichlich. Die Kontinentalarmee stand einem berufsmäßigen britischen Heer gegenüber und erlitt verheerende frühe Niederlagen. Washingtons entscheidender Sieg bei Trenton am 26. Dezember 1776 — eine Überraschungsüberquerung des eisigen Delaware in der Weihnachtsnacht — stellte die Moral wieder her und hielt die Revolution am Leben.\n\nDer Wendepunkt kam in der Schlacht von Saratoga im Oktober 1777, wo amerikanische Truppen ein ganzes britisches Heer gefangen nahmen. Dieser Triumph überzeugte Frankreich, sich förmlich mit den Amerikanern zu verbünden und Schiffe, Soldaten und Anleihen bereitzustellen, ohne die ein amerikanischer Sieg unmöglich gewesen wäre. Die letzte entscheidende Schlacht kam bei Yorktown im Oktober 1781, wo Washington und der französische Befehlshaber Rochambeau Cornwallis’ Heer zwischen Landstreitkräften und der französischen Flotte einschlossen. Cornwallis kapitulierte, und der Friede von Paris (1783) erkannte die amerikanische Unabhängigkeit an.",
      "Frankreich befand sich in den 1780er Jahren in der Krise: ein bankrotter Staat, Missernten, die die Brotpreise in die Höhe trieben, und ein Adel, der keine Steuern zahlen wollte. Als Ludwig XVI. im Mai 1789 die Generalstände einberief — die erste Zusammenkunft seit 175 Jahren —, brach sich der Dritte Stand (die Gemeinen) los und erklärte sich zur Nationalversammlung, mit dem Anspruch, Frankreichs Verfassung neu zu gestalten.\n\nAm 14. Juli 1789 stürmte eine Pariser Menge die Bastille, ein Sinnbild königlicher Tyrannei — der Augenblick, der den Beginn der Revolution markiert. Die Nationalversammlung schaffte in der Nacht des 4. August den Feudalismus über Nacht ab und erließ dann die Erklärung der Menschen- und Bürgerrechte, die Freiheit, Gleichheit vor dem Gesetz, Meinungsfreiheit und nationale Souveränität verkündete. Diese Prinzipien wurden zum ideologischen Kern der Revolution. Ludwig XVI. wurde gezwungen, eine konstitutionelle Monarchie anzunehmen; das alte Regime war tot. Frankreich wurde in Departements neu gegliedert, die Kirche verstaatlicht und das Erbvorrecht abgeschafft.",
      "Die Revolution wurde rasch radikaler und gewaltsamer. Der Krieg gegen Österreich und Preußen ab 1792, verbunden mit inneren konterrevolutionären Aufständen, schuf in Paris eine Belagerungsmentalität. Die radikale Jakobinerfraktion unter Maximilien Robespierre riss 1793 die Kontrolle über den Wohlfahrtsausschuss an sich und entfesselte die Schreckensherrschaft: eine systematische Hinrichtung von „Feinden der Revolution“, die über 17 000 Menschen unter die Guillotine schickte, darunter Ludwig XVI. (Januar 1793) und Marie-Antoinette (Oktober 1793).\n\nDer Terror verzehrte sich selbst: Im Juli 1794 wandten sich Robespierres eigene Kollegen gegen ihn („Thermidorianische Reaktion“), und am nächsten Tag wurde er guillotiniert. Ein konservativeres Direktorium regierte von 1795 bis 1799, erwies sich aber als zu schwach, um Frankreichs Kriege und inneren Konflikte zu bewältigen. In dieses Vakuum trat ein glänzender junger korsischer Artillerieoffizier: Napoleon Bonaparte.",
      "Napoleon Bonapartes Staatsstreich vom 18. Brumaire (November 1799) beendete die Revolution und begann das Konsulat, dann das Kaiserreich (1804). Napoleon stellte sich als Vollender der revolutionären Errungenschaften dar: Sein Code civil (1804) verankerte die Gleichheit vor dem Gesetz, Eigentumsrechte und religiöse Duldung — schränkte zugleich aber die Rechte der Frauen ein und stellte die soziale Hierarchie wieder her. Seine Eroberungen verbreiteten den Code und die revolutionären Einrichtungen über ganz Europa und lösten feudale Strukturen von Spanien bis Polen auf.\n\nDoch Napoleons imperiale Ambitionen provozierten schließlich eine Koalition europäischer Mächte, die ihn bei Leipzig (1813) und Waterloo (1815) besiegten und mit seiner Verbannung nach St. Helena endeten. Der Wiener Kongress versuchte, die alte Ordnung wiederherzustellen, doch der revolutionäre Geist ließ sich nicht mehr in die Flasche zurückzwingen. Die Ideen der Volkssouveränität, der natürlichen Rechte und der nationalen Selbstbestimmung verbreiteten sich über das 19. Jahrhundert und befeuerten Revolutionen von Lateinamerika über Griechenland bis zum Europa von 1848. Die Amerikanische und die Französische Revolution begründeten gemeinsam das Grundvokabular der modernen Demokratie — Freiheit, Gleichheit und das Recht auf Selbstregierung —, das das politische Leben bis heute prägt.",
    ],
    fr: [
      "Dans les années 1760, les treize colonies américaines de la Grande-Bretagne avaient développé une culture politique distincte, enracinée dans les idées des Lumières sur les droits naturels, le gouvernement représentatif et le contrat social. Lorsque la Grande-Bretagne imposa de nouvelles taxes après la guerre de Sept Ans — le Stamp Act (1765), les Townshend Acts (1767) — sans accorder aux colons de représentation au Parlement, le slogan « pas de taxation sans représentation » cristallisa un grief constitutionnel en programme révolutionnaire.\n\nLa Boston Tea Party de décembre 1773, où des colons jetèrent 342 caisses de thé dans le port de Boston pour protester contre le Tea Act, provoqua de dures représailles britanniques. Le conflit ouvert éclata à Lexington et Concord en avril 1775. Le deuxième Congrès continental nomma George Washington à la tête de l’armée continentale. Le 4 juillet 1776, le Congrès adopta la Déclaration d’indépendance de Thomas Jefferson — le document politique le plus lourd de conséquences de l’ère moderne. Imprégnée de la philosophie de John Locke, elle proclamait que « tous les hommes sont créés égaux » et possèdent des « droits inaliénables » à « la vie, la liberté et la recherche du bonheur », et que le gouvernement tire ses justes pouvoirs du consentement des gouvernés.",
      "La guerre d’Indépendance (1775–1783) ne fut nullement inévitable. L’armée continentale affrontait une armée britannique professionnelle et subit de désastreuses défaites initiales. La victoire cruciale de Washington à Trenton, le 26 décembre 1776 — une traversée surprise du fleuve Delaware gelé la nuit de Noël — restaura le moral et maintint la révolution en vie.\n\nLe tournant vint à la bataille de Saratoga en octobre 1777, où les forces américaines capturèrent une armée britannique entière. Ce triomphe convainquit la France de s’allier officiellement aux Américains, fournissant navires, soldats et prêts sans lesquels la victoire américaine eût été impossible. L’engagement décisif final eut lieu à Yorktown en octobre 1781, où Washington et le commandant français Rochambeau piégèrent l’armée de Cornwallis entre les forces terrestres et la flotte française. Cornwallis capitula, et le traité de Paris (1783) reconnut l’indépendance américaine.",
      "La France des années 1780 était en crise : un État en faillite, des mauvaises récoltes faisant flamber le prix du pain, et une aristocratie refusant de payer l’impôt. Quand Louis XVI convoqua les États généraux en mai 1789 — la première réunion en 175 ans — le tiers état (les roturiers) fit sécession et se déclara Assemblée nationale, revendiquant le droit de refaire la constitution de la France.\n\nLe 14 juillet 1789, une foule parisienne prit d’assaut la forteresse de la Bastille, symbole de la tyrannie royale — l’instant qui marque le début de la révolution. L’Assemblée nationale abolit la féodalité en une nuit, le 4 août, puis promulgua la Déclaration des droits de l’homme et du citoyen, proclamant la liberté, l’égalité devant la loi, la liberté d’expression et la souveraineté nationale. Ces principes devinrent le cœur idéologique de la révolution. Louis XVI fut contraint d’accepter une monarchie constitutionnelle ; l’Ancien Régime était mort. La France fut réorganisée en départements, l’Église nationalisée et le privilège héréditaire aboli.",
      "La révolution devint vite plus radicale et plus violente. La guerre avec l’Autriche et la Prusse à partir de 1792, jointe aux rébellions contre-révolutionnaires internes, créa une mentalité de siège à Paris. La faction jacobine radicale, menée par Maximilien Robespierre, s’empara du Comité de salut public en 1793 et lança la Terreur : une exécution systématique des « ennemis de la révolution » qui envoya plus de 17 000 personnes à la guillotine, dont Louis XVI (janvier 1793) et Marie-Antoinette (octobre 1793).\n\nLa Terreur se consuma elle-même : en juillet 1794, les propres collègues de Robespierre se retournèrent contre lui (« réaction thermidorienne »), et il fut guillotiné le lendemain. Un Directoire plus conservateur gouverna de 1795 à 1799, mais se révéla trop faible pour gérer les guerres et les conflits internes de la France. Dans ce vide s’avança un brillant jeune officier d’artillerie corse : Napoléon Bonaparte.",
      "Le coup d’État de Napoléon Bonaparte du 18 Brumaire (novembre 1799) mit fin à la Révolution et inaugura le Consulat, puis l’Empire (1804). Napoléon se présenta comme le consolidateur des acquis révolutionnaires : son Code civil (1804) consacra l’égalité devant la loi, le droit de propriété et la tolérance religieuse — tout en restreignant les droits des femmes et en réimposant la hiérarchie sociale. Ses conquêtes répandirent le Code et les institutions révolutionnaires dans toute l’Europe, dissolvant les structures féodales de l’Espagne à la Pologne.\n\nPourtant les ambitions impériales de Napoléon finirent par provoquer une coalition de puissances européennes qui le défit à Leipzig (1813) et à Waterloo (1815), s’achevant par son exil à Sainte-Hélène. Le congrès de Vienne tenta de restaurer l’ancien ordre, mais le génie révolutionnaire ne pouvait plus être remis dans sa bouteille. Les idées de souveraineté populaire, de droits naturels et d’autodétermination nationale se répandirent tout au long du XIXᵉ siècle, alimentant des révolutions de l’Amérique latine à la Grèce jusqu’à l’Europe de 1848. Les révolutions américaine et française établirent ensemble le vocabulaire fondateur de la démocratie moderne — liberté, égalité et droit à l’autogouvernement — qui façonne la vie politique jusqu’à aujourd’hui.",
    ],
  },
  'earlymod-08': {
    de: [
      "Zahir ud-Din Muhammad Babur — väterlicherseits Nachkomme Timurs, mütterlicherseits Dschingis Khans — verlor seine zentralasiatische Heimat Ferghana, ehe er zwanzig war. Nach Süden gewandt, besiegte er mit einer kleinen, mit Feuerwaffen ausgerüsteten Streitmacht 1526 bei Panipat das gewaltige Heer des Sultans von Delhi, wo seine Feldartillerie und seine flankierenden berittenen Bogenschützen Kriegselefanten und Übermacht überwanden.\n\nBabur war ein Eroberer, der Gedichte schrieb und Gärten entwarf; seine Memoiren, das Baburnama, sind erstaunlich freimütig über alles, von der Schlacht bis zur Melone. Er starb 1530, nachdem er mehr von Hindustan erobert hatte, als er zu regieren Zeit gehabt hätte — und überließ dieses Werk seinen Nachkommen.",
      "Baburs Enkel Akbar (reg. 1556–1605) erbte mit dreizehn ein wackliges Königreich und hinterließ das reichste Reich der Erde. Seine Formel war Einbeziehung. Er schaffte die Dschizya-Steuer auf Nichtmuslime ab, heiratete Radschputen-Prinzessinnen, ohne einen Übertritt zu verlangen, und besetzte Heer und Schatzkammer mit hinduistischen Feldherren und Ministern. Das Reich war über das Mansabdari-System gegliedert — ein gestufter kaiserlicher Dienst rangierter Offiziere, die Truppen und Treue unmittelbar dem Thron schuldeten.\n\nObwohl er nicht lesen konnte (wahrscheinlich Legastheniker), stellte Akbar eine Bibliothek von 24 000 Bänden zusammen und richtete in seinem Haus der Anbetung in Fatehpur Sikri Streitgespräche zwischen sunnitischen und schiitischen Gelehrten, Brahmanen, Jainas, Jesuiten und Zoroastriern aus — und schloss, zum Entsetzen seiner Hoftheologen, dass die Wahrheit in allen Glaubensrichtungen zu finden sei.",
      "Das Reich, das Akbar aufbaute, finanzierte ein Jahrhundert unvergleichlicher Pracht. Unter Jahangir erreichte die Mogul-Miniaturmalerei fotografische Feinheit; unter Shah Jahan (reg. 1628–1658) wurde die Architektur zum Kennzeichen der Dynastie. Das Rote Fort und die Jama Masjid erhoben sich in seiner neuen Hauptstadt Shahjahanabad (Alt-Delhi), doch sein Meisterwerk war ein Grabmal: der Taj Mahal, über zwei Jahrzehnte von 20 000 Handwerkern für seine geliebte Frau Mumtaz Mahal errichtet, die bei der Geburt ihres vierzehnten Kindes starb.\n\nDas Mogul-Indien war eine wirtschaftliche Supermacht — es erzeugte etwa ein Viertel der Fertigwaren der Welt. Seine Musseline und Kattune kleideten Europa, und europäisches Silber floss nach Osten, um sie zu bezahlen, da Europa fast nichts herstellte, was Indien begehrte.",
      "Shah Jahans Sohn Aurangzeb riss 1658 nach einem Brudermord-Krieg den Thron an sich und sperrte seinen Vater im Fort von Agra ein — in Sichtweite des Taj. Streng und unermüdlich fleißig, dehnte er das Reich auf seine größte Ausdehnung aus und eroberte die Dekkan-Sultanate. Doch seine Umkehr von Akbars Toleranz — die Wiedereinführung der Dschizya, die Zerstörung einiger Tempel — und seine endlosen Dekkan-Kriege gegen die Guerilla-Überfälle des Marathen-Führers Shivaji erschöpften die Schatzkammer und zerrütteten die Treue des Reiches.\n\nNach Aurangzebs Tod 1707 höhlte sich das Reich binnen einer Generation aus. Persische und afghanische Eroberer plünderten Delhi, regionale Statthalter wurden Könige in allem außer dem Namen, und eine Aktiengesellschaft englischer Kaufleute — die Ostindien-Kompanie — begann in Bengalen Steuern einzutreiben. Der Mogul-Kaiser wurde zum Rentner im eigenen Palast; der letzte wurde 1857 von den Briten abgesetzt.",
      "Der Reichtum des Mogul-Hofes kristallisierte sich in einem einzigen Gegenstand: dem Pfauenthron, den Shah Jahan in Auftrag gab — eine goldene Plattform, überkrustet mit Rubinen, Smaragden und Perlen, überdacht von zwei juwelenbesetzten Pfauen und besetzt mit dem Koh-i-Noor-Diamanten. Seine Herstellung dauerte sieben Jahre und kostete doppelt so viel wie der Taj Mahal. Sein Schicksal erzählte das des Reiches. 1739, als die Mogul-Macht ausgehöhlt war, plünderte der persische Eroberer Nadir Schah Delhi, ließ an einem einzigen Tag Zehntausende niedermetzeln und trug den Thron — und den Koh-i-Noor — nach Persien zurück. Der Diamant ging durch afghanische und Sikh-Hände, ehe er in den britischen Kronjuwelen endete, wo er bleibt: eine verdichtete Geschichte von Indiens Reichtum und von jenen, die kamen, ihn zu nehmen.",
    ],
    fr: [
      "Zahir ud-Din Muhammad Babur — descendant de Tamerlan par son père et de Gengis Khan par sa mère — perdit sa patrie d’Asie centrale, le Ferghana, avant ses vingt ans. Se tournant vers le sud avec une petite force dotée d’armes à feu, il défit la vaste armée du sultan de Delhi à Panipat en 1526, où son artillerie de campagne et ses archers à cheval débordant les flancs vainquirent éléphants de guerre et supériorité numérique.\n\nBabur était un conquérant qui écrivait des poèmes et dessinait des jardins ; ses mémoires, le Baburnama, sont d’une franchise saisissante sur tout, de la bataille aux melons. Il mourut en 1530, ayant conquis plus de l’Hindoustan qu’il n’avait eu le temps de gouverner — laissant cette tâche à ses descendants.",
      "Le petit-fils de Babur, Akbar (r. 1556–1605), hérita à treize ans d’un royaume chancelant et laissa l’empire le plus riche de la Terre. Sa formule était l’inclusion. Il abolit l’impôt de la jizya sur les non-musulmans, épousa des princesses rajpoutes sans exiger de conversion, et pourvut son armée et son trésor de généraux et de ministres hindous. L’empire était organisé par le système du mansabdari — un service impérial gradé d’officiers classés devant troupes et loyauté directement au trône.\n\nBien qu’incapable de lire (probablement dyslexique), Akbar rassembla une bibliothèque de 24 000 volumes et accueillit dans sa Maison du culte de Fatehpur Sikri des débats entre savants sunnites et chiites, brahmanes, jaïns, jésuites et zoroastriens — concluant, à l’horreur de ses théologiens de cour, que la vérité pouvait se trouver dans toutes les fois.",
      "L’empire bâti par Akbar finança un siècle de splendeur inégalée. Sous Jahangir, la miniature moghole atteignit une délicatesse photographique ; sous Shah Jahan (r. 1628–1658), l’architecture devint la signature de la dynastie. Le Fort Rouge et la Jama Masjid s’élevèrent dans sa nouvelle capitale de Shahjahanabad (le Vieux Delhi), mais son chef-d’œuvre fut un tombeau : le Taj Mahal, édifié en deux décennies par 20 000 artisans pour son épouse bien-aimée Mumtaz Mahal, morte en mettant au monde leur quatorzième enfant.\n\nL’Inde moghole était une superpuissance économique — produisant environ un quart des manufactures du monde. Ses mousselines et ses indiennes habillaient l’Europe, et l’argent européen affluait vers l’est pour les payer, puisque l’Europe ne fabriquait presque rien que l’Inde désirât.",
      "Le fils de Shah Jahan, Aurangzeb, s’empara du trône en 1658 après une guerre fratricide, emprisonnant son père au Fort d’Agra — en vue du Taj. Austère et infatigablement laborieux, il porta l’empire à sa plus grande extension, conquérant les sultanats du Deccan. Mais son revirement par rapport à la tolérance d’Akbar — rétablissant la jizya, détruisant certains temples — et ses interminables guerres du Deccan contre les razzias de guérilla du chef marathe Shivaji épuisèrent le trésor et effilochèrent les loyautés de l’empire.\n\nAprès la mort d’Aurangzeb en 1707, l’empire se vida en une génération. Des envahisseurs perses et afghans mirent Delhi à sac, les gouverneurs régionaux devinrent rois en tout sauf le nom, et une société par actions de marchands anglais — la Compagnie des Indes orientales — commença à lever l’impôt au Bengale. L’empereur moghol devint un pensionné dans son propre palais ; le dernier fut déposé par les Britanniques en 1857.",
      "La richesse de la cour moghole se cristallisa en un seul objet : le trône du Paon, commandé par Shah Jahan — une estrade dorée incrustée de rubis, d’émeraudes et de perles, surmontée d’un dais de deux paons ornés de joyaux et serti du diamant Koh-i-Noor. Sa fabrication prit sept ans et coûta deux fois plus que le Taj Mahal. Son destin raconta celui de l’empire. En 1739, la puissance moghole étant vidée, le conquérant perse Nadir Shah mit Delhi à sac, massacra des dizaines de milliers de personnes en une seule journée, et emporta le trône — et le Koh-i-Noor — en Perse. Le diamant passa par des mains afghanes et sikhes avant d’aboutir dans les joyaux de la couronne britannique, où il demeure : une histoire condensée de la richesse de l’Inde, et de ceux qui vinrent la prendre.",
    ],
  },
  'earlymod-09': {
    de: [
      "Ein Jahrhundert des Samurai-Bürgerkriegs — die Sengoku-Zeit — endete an einem nebligen Oktobermorgen des Jahres 1600 bei Sekigahara, wo die östliche Koalition Tokugawa Ieyasus ihre westlichen Rivalen an einem einzigen Tag vernichtete, unterstützt durch Überläufer auf dem Schlachtfeld, die er zuvor im Stillen arrangiert hatte. 1603 zum Shogun ernannt, begründete Ieyasu eine Dynastie, die 265 Jahre lang von Edo aus herrschen sollte.\n\nDas Tokugawa-System war vollendete Kontrolle. Die Daimyō-Fürsten behielten ihre Domänen, verbrachten aber jedes zweite Jahr in Edo (Sankin-kōtai) und ließen ihre Familien als höfliche Geiseln zurück; die ruinösen Kosten zweier Haushalte und prunkvoller Prozessionen leerten jede Kriegskasse. Burgen waren auf eine pro Domäne beschränkt, Ehen bedurften der Genehmigung, und eine erbliche Vierständeordnung — Samurai, Bauer, Handwerker, Kaufmann — ließ die Gesellschaft erstarren.",
      "Das Christentum, mit portugiesischen Händlern und jesuitischen Missionaren gekommen, hatte bis 1600 vielleicht 300 000 Bekehrte gewonnen — und das Shogunat sah darin eine fremde Loyalität, die es nicht überwachen konnte. Die Verfolgung gipfelte nach der christlich geführten Shimabara-Rebellion (1637–38), die im Blut ertränkt wurde. Es folgten die Sakoku-Erlasse („geschlossenes Land“): Japanern war die Ausreise verboten, Fremden die Einreise, und das Christentum wurde in den Untergrund gejagt.\n\nDie Abschließung war nie vollständig — sie war ein Filter. Chinesische Dschunken und ein einziger niederländischer Handelsposten auf der fächerförmigen Insel Dejima im Hafen von Nagasaki blieben, und durch Dejima sickerten westliche Bücher, Fernrohre und medizinische Texte. Eine Schule von Gelehrten der „Holland-Kunde“ (Rangaku) hielt Japan im Stillen über die europäische Wissenschaft auf dem Laufenden — ein geistiger Same, der enorm wichtig werden sollte, als sich das Land wieder öffnete.",
      "Der Friede vollbrachte, was der Krieg nie konnte: Er machte Japan städtisch, lesekundig und kaufmännisch. Edo überschritt eine Million Einwohner — größer als London oder Paris —, während Osaka zur reismaklerischen „Küche Japans“ wurde, wo Kaufleute den ersten organisierten Terminmarkt der Welt betrieben. Die Lesefähigkeit, von Tempelschulen verbreitet, erreichte anderswo unerreichte Höhen.\n\nIn den lizenzierten Vergnügungsvierteln erblühte die Kultur des Ukiyo — der „fließenden Welt“ aus Kabuki-Theatern, Geishas, Sumo und volkstümlicher Erzählkunst. Holzschnittkünstler wie Hokusai und Hiroshige druckten in Massen Bilder von Schauspielern, Schönheiten und Landschaften — die Große Welle, die Stationen der Tōkaidō-Straße —, die zum Preis einer Schale Nudeln verkauft wurden. Als diese Drucke im 19. Jahrhundert als Packpapier nach Europa gelangten, elektrisierten sie Monet, Degas und Van Gogh.",
      "Zu Beginn des 19. Jahrhunderts alterte das System: Samurai-Bezüge kauften weniger, Kaufleute hielten den wahren Reichtum, Hungersnöte entfachten Aufruhr, und ausländische Walfänger und Kriegsschiffe suchten mit wachsendem Nachdruck die Küsten heim. Russische Gesandte, britische Vermesser und amerikanische Kapitäne wurden alle abgewiesen — bis im Juli 1853 das Geschwader von Kommodore Matthew Perry aus schwarzrumpfigen Dampffregatten in der Bucht von Edo ankerte und sich weigerte fortzugehen.\n\nUnfähig, Dampf und Granate zu widerstehen, unterzeichnete das Shogunat Verträge, die Häfen öffneten — und seine Autorität, die auf dem Anspruch beruhte, Barbaren zu unterwerfen, brach binnen fünfzehn Jahren zusammen. Die Meiji-Restauration von 1868 beendete die Samurai-Herrschaft im Namen des Kaisers. Doch die Hinterlassenschaften des Tokugawa-Japans — eine geeinte, geordnete, hochgebildete Gesellschaft mit Sinn für disziplinierte Organisation — sind genau das, was Japans blitzartige Modernisierung möglich machte.",
      "1701 zog ein Provinzfürst, im Palast des Shoguns gereizt, sein Schwert — ein Kapitalverbrechen — und wurde zum Seppuku befohlen; seine Domäne wurde eingezogen, und seine Samurai wurden zu herrenlosen Rōnin. Siebenundvierzig von ihnen gaben fast zwei Jahre lang vor, Trunkenbolde und Handwerker zu sein, um den Verdacht einzuschläfern, stürmten dann das Anwesen des Hofbeamten, der ihren Herrn gereizt hatte, und legten dessen Kopf auf das Grab ihres Meisters. Das Shogunat stand vor einem Dilemma, das Japan faszinierte: Die Rōnin waren der Loyalität gefolgt, der höchsten Samurai-Tugend, indem sie das Gesetz brachen. Das Urteil — ehrenvolles Seppuku statt Hinrichtung — befriedigte beides. In Kabuki und Druck endlos nacherzählt, wurde die Geschichte zur prägenden Erzählung des Tokugawa-Japans: Was bedeutet Pflicht für eine Kriegerkaste in einer Welt ohne Kriege mehr zu führen?",
    ],
    fr: [
      "Un siècle de guerre civile des samouraïs — l’ère Sengoku — s’acheva par un brumeux matin d’octobre 1600 à Sekigahara, où la coalition orientale de Tokugawa Ieyasu détruisit ses rivaux occidentaux en une seule journée, aidée par des défections sur le champ de bataille qu’il avait discrètement arrangées d’avance. Nommé shogun en 1603, Ieyasu fonda une dynastie qui régnerait depuis Edo pendant 265 ans.\n\nLe système Tokugawa était le contrôle porté à la perfection. Les seigneurs daimyo gardaient leurs domaines mais passaient une année sur deux à Edo (sankin-kotai), laissant leur famille derrière eux comme otages courtois ; le coût ruineux d’entretenir deux maisons et de grandes processions vidait tout trésor de guerre. Les châteaux étaient limités à un par domaine, les mariages requéraient une autorisation, et un ordre héréditaire à quatre classes — samouraï, paysan, artisan, marchand — figeait la société sur place.",
      "Le christianisme, arrivé avec les marchands portugais et les missionnaires jésuites, avait gagné peut-être 300 000 convertis vers 1600 — et le shogunat y voyait une loyauté étrangère qu’il ne pouvait surveiller. La persécution culmina après la rébellion de Shimabara menée par des chrétiens (1637–38), noyée dans le sang. Les édits du sakoku (« pays fermé ») suivirent : il fut interdit aux Japonais de partir, aux étrangers d’entrer, et le christianisme fut traqué dans la clandestinité.\n\nLa fermeture ne fut jamais totale — c’était un filtre. Des jonques chinoises et un unique comptoir néerlandais sur l’îlot en éventail de Dejima, dans le port de Nagasaki, subsistèrent, et par Dejima s’infiltrèrent livres, télescopes et traités médicaux occidentaux. Une école de savants du « savoir hollandais » (rangaku) tint le Japon discrètement informé de la science européenne — une graine intellectuelle qui compterait énormément à la réouverture du pays.",
      "La paix accomplit ce que la guerre n’avait jamais pu : elle rendit le Japon urbain, lettré et commerçant. Edo dépassa le million d’habitants — plus grande que Londres ou Paris — tandis qu’Osaka devint la « cuisine du Japon » du courtage du riz, où les marchands tenaient le premier marché à terme organisé du monde. L’alphabétisation, répandue par les écoles de temple, atteignit des niveaux inégalés ailleurs.\n\nDans les quartiers de plaisir autorisés fleurit la culture de l’ukiyo — le « monde flottant » des théâtres kabuki, des geishas, du sumo et de la fiction populaire. Des maîtres de l’estampe comme Hokusai et Hiroshige produisirent en masse des images d’acteurs, de beautés et de paysages — la Grande Vague, les stations de la route du Tokaido — vendues au prix d’un bol de nouilles. Lorsque ces estampes parvinrent en Europe au XIXᵉ siècle comme papier d’emballage, elles électrisèrent Monet, Degas et Van Gogh.",
      "Au début des années 1800, le système vieillissait : les rentes des samouraïs achetaient moins, les marchands détenaient la vraie richesse, les famines déclenchaient des émeutes, et baleiniers et navires de guerre étrangers sondaient les côtes avec une insistance croissante. Envoyés russes, arpenteurs britanniques et capitaines américains furent tous éconduits — jusqu’en juillet 1853, quand l’escadre du commodore Matthew Perry, faite de frégates à vapeur à coque noire, mouilla dans la baie d’Edo et refusa de partir.\n\nIncapable de résister à la vapeur et à l’obus, le shogunat signa des traités ouvrant des ports — et son autorité, reposant sur la prétention à soumettre les barbares, s’effondra en quinze ans. La restauration de Meiji en 1868 mit fin au règne des samouraïs au nom de l’empereur. Pourtant les héritages du Japon Tokugawa — une société unifiée, ordonnée, hautement lettrée, ayant le goût de l’organisation disciplinée — sont précisément ce qui rendit possible la fulgurante modernisation du Japon.",
      "En 1701, un seigneur de province, provoqué dans le palais du shogun, tira son épée — un crime capital — et reçut l’ordre de commettre seppuku ; son domaine fut confisqué et ses samouraïs devinrent des rōnin sans maître. Quarante-sept d’entre eux passèrent près de deux ans à se faire passer pour des ivrognes et des artisans afin d’endormir les soupçons, puis prirent d’assaut la demeure du dignitaire de cour qui avait provoqué leur seigneur et déposèrent sa tête sur la tombe de leur maître. Le shogunat affronta un dilemme qui fascina le Japon : les rōnin avaient suivi la loyauté, la plus haute vertu des samouraïs, en enfreignant la loi. Le verdict — seppuku honorable plutôt qu’exécution — satisfit les deux. Racontée sans fin au kabuki et en estampes, l’histoire devint le récit emblématique du Japon Tokugawa : que signifie le devoir pour une caste guerrière dans un monde où il ne reste plus de guerres à livrer ?",
    ],
  },
  'modern-01': {
    de: [
      "Die Industrielle Revolution begann um 1760 in Britannien, getrieben von einer einzigartigen Verbindung von Faktoren: reichlich Kohle und Eisen, eine stabile Regierung, gesicherte Eigentumsrechte, ein wachsendes Reich, das Märkte und Rohstoffe lieferte, und eine Kultur, die praktische Erfindung schätzte. James Watts verbesserte Dampfmaschine (1769) wurde zu ihrem Sinnbild — eine Maschine, die Wärme in mechanische Arbeit verwandeln konnte.\n\nTextilfabriken in Lancashire, Eisengießereien in Birmingham und Kohlebergwerke in Wales verwandelten Britanniens Wirtschaft. Um 1800 erzeugte Britannien mehr Eisen und Stahl als der Rest der Welt zusammen. Kinderarbeit war verbreitet; Arbeiter schufteten 14-Stunden-Tage unter gefährlichen Bedingungen für kärglichen Lohn.",
      "Die Dampflokomotive revolutionierte den Verkehr. George Stephensons „Rocket“ (1829) läutete das Eisenbahnzeitalter ein. Um 1850 hatte Britannien 10 000 km Eisenbahn; um 1900 verfügte die Welt über 790 000 km. Eisenbahnen bewegten Güter und Menschen mit beispielloser Geschwindigkeit — und verkürzten Reisezeiten von Tagen auf Stunden.\n\nDer Telegraf, in den 1830er und 1840er Jahren patentiert, ermöglichte nahezu augenblickliche Fernkommunikation. Zum ersten Mal in der Menschheitsgeschichte konnte Information schneller reisen als ein Mensch. Diese Technologien schufen die ersten wirklich integrierten nationalen — und schließlich globalen — Märkte.",
      "Die Industrialisierung entwurzelte Millionen. Bauern wanderten in die Industriestädte; um 1851 war Britannien die erste mehrheitlich städtische Nation der Welt. Diese Städte waren oft überfüllt, verschmutzt und von Krankheiten heimgesucht. Doch die Industrialisierung schuf auch Wohlstand, senkte Preise und hob schließlich den Lebensstandard.\n\nNeue soziale Klassen entstanden: das industrielle Bürgertum (Fabrikbesitzer) und das Proletariat (Lohnarbeiter). Karl Marx und Friedrich Engels, die das Elend Manchesters beobachteten, schrieben „Das Kommunistische Manifest“ (1848) und behaupteten, der Klassenkampf sei der Motor der Geschichte. Gewerkschaften organisierten sich; die Arbeiter erkämpften schließlich kürzere Arbeitszeiten, besseren Lohn und politische Rechte.",
      "Nach 1870 verwandelte eine Zweite Industrielle Revolution die fortgeschrittenen Volkswirtschaften der Welt — diesmal angeführt von Deutschland und den Vereinigten Staaten neben Britannien. Stahl, mit dem Bessemer-Verfahren billig erzeugt, ersetzte das Eisen; elektrische Kraft ermöglichte den effizienten Betrieb der Fabriken; der Verbrennungsmotor und das Erdöl begründeten ein neues Energieparadigma. Neue Industrien — Chemie, Pharmazie, Elektrotechnik, Automobilbau — beruhten auf systematischer wissenschaftlicher Forschung.\n\nDeutschland führte in Chemie und Elektrotechnik; amerikanische Unternehmen wie Carnegie Steel und Standard Oil erreichten zuvor unvorstellbare Produktionsmaßstäbe. Henry Fords bewegtes Fließband (1913) machte das Automobil erschwinglich. Diese Veränderungen ballten wirtschaftliche Macht in riesigen Konzernen zusammen und verschärften die Konflikte zwischen Industriekapital und Arbeit — was den Nährboden für den Aufstieg von Gewerkschaften, sozialistischen Parteien und kommunistischen Revolutionsbewegungen bildete.",
      "Industrieller Reichtum befeuerte die europäische imperiale Expansion. Um 1914 beherrschten die europäischen Mächte 85 % der Landfläche der Welt. Der „Wettlauf um Afrika“ (1880er–1914) teilte den Kontinent in Verhandlungen unter den europäischen Mächten auf, die keinerlei Rücksicht auf die afrikanischen Völker oder bestehende politische Strukturen nahmen — und schuf künstliche Grenzen, die bis heute Konflikte auslösen.\n\nDie Industrialisierung verschärfte auch den europäischen Nationalismus. Deutschland, erst 1871 geeint, wurde rasch zur beherrschenden Wirtschafts- und Militärmacht des Kontinents und bedrohte das bestehende Gleichgewicht. Ein Wettrüsten zwischen Britannien und Deutschland brachte die größten Seestreitkräfte der Welt hervor; Bündnissysteme banden die europäischen Mächte in starre Verpflichtungen. Um 1914 war eine Generation industriell organisierter Militärs auf einen Krieg vorbereitet, den alle für kurz hielten — und der sich als katastrophal erwies.",
    ],
    fr: [
      "La révolution industrielle commença en Grande-Bretagne vers 1760, portée par une combinaison unique de facteurs : charbon et fer abondants, gouvernement stable, droits de propriété assurés, un empire grandissant fournissant marchés et matières premières, et une culture valorisant l’invention pratique. La machine à vapeur perfectionnée de James Watt (1769) en devint le symbole — une machine capable de transformer la chaleur en travail mécanique.\n\nLes filatures du Lancashire, les fonderies de Birmingham et les mines de charbon du pays de Galles transformèrent l’économie britannique. Vers 1800, la Grande-Bretagne produisait plus de fer et d’acier que le reste du monde réuni. Le travail des enfants était courant ; les ouvriers peinaient 14 heures par jour dans des conditions dangereuses pour un salaire de misère.",
      "La locomotive à vapeur révolutionna les transports. La « Rocket » de George Stephenson (1829) inaugura l’âge du chemin de fer. Vers 1850, la Grande-Bretagne comptait 10 000 km de voies ferrées ; vers 1900, le monde en comptait 790 000 km. Les chemins de fer transportaient marchandises et personnes à une vitesse inédite — réduisant les temps de trajet de jours à heures.\n\nLe télégraphe, breveté dans les années 1830 et 1840, permit une communication à longue distance quasi instantanée. Pour la première fois dans l’histoire humaine, l’information pouvait voyager plus vite qu’un être humain. Ces technologies créèrent les premiers marchés véritablement intégrés à l’échelle nationale — puis mondiale.",
      "L’industrialisation déracina des millions de personnes. Les paysans migrèrent vers les villes industrielles ; vers 1851, la Grande-Bretagne fut la première nation à majorité urbaine du monde. Ces villes étaient souvent surpeuplées, polluées et ravagées par la maladie. Pourtant l’industrialisation créa aussi de la richesse, abaissa les prix et finit par élever le niveau de vie.\n\nDe nouvelles classes sociales émergèrent : la bourgeoisie industrielle (les propriétaires d’usines) et le prolétariat (les salariés). Karl Marx et Friedrich Engels, observant la misère de Manchester, écrivirent le « Manifeste du parti communiste » (1848), affirmant que la lutte des classes était le moteur de l’histoire. Les syndicats s’organisèrent ; les ouvriers conquirent finalement des horaires plus courts, de meilleurs salaires et des droits politiques.",
      "Après 1870, une seconde révolution industrielle transforma les économies avancées du monde — cette fois menée par l’Allemagne et les États-Unis aux côtés de la Grande-Bretagne. L’acier, produit à bas coût grâce au convertisseur Bessemer, remplaça le fer ; l’énergie électrique permit aux usines de fonctionner efficacement ; le moteur à combustion interne et le pétrole lancèrent un nouveau paradigme énergétique. De nouvelles industries — chimie, pharmacie, génie électrique, automobile — reposaient sur une recherche scientifique systématique.\n\nL’Allemagne dominait en chimie et en génie électrique ; des entreprises américaines comme Carnegie Steel et Standard Oil atteignirent des échelles de production auparavant inconcevables. La chaîne de montage mobile d’Henry Ford (1913) rendit l’automobile abordable. Ces changements concentrèrent le pouvoir économique dans des sociétés géantes et aiguisèrent les conflits entre capital industriel et travail — offrant le contexte de l’essor des syndicats, des partis socialistes et des mouvements révolutionnaires communistes.",
      "La richesse industrielle alimenta l’expansion impériale européenne. Vers 1914, les puissances européennes contrôlaient 85 % des terres du monde. La « ruée vers l’Afrique » (années 1880–1914) partagea le continent entre les puissances européennes lors de négociations sans aucun égard pour les peuples africains ou les structures politiques existantes — créant des frontières artificielles qui provoquent des conflits jusqu’à aujourd’hui.\n\nL’industrialisation intensifia aussi le nationalisme européen. L’Allemagne, unifiée seulement en 1871, devint rapidement la puissance économique et militaire dominante du continent, menaçant l’équilibre existant. Une course aux armements entre la Grande-Bretagne et l’Allemagne produisit les plus grandes forces navales du monde ; les systèmes d’alliances enfermèrent les puissances européennes dans des obligations rigides. En 1914, une génération d’armées organisées industriellement était prête pour une guerre que tous croyaient brève — et qui se révéla catastrophique.",
    ],
  },
  'modern-02': {
    de: [
      "Der Erste Weltkrieg begann im August 1914, ausgelöst durch die Ermordung des österreichisch-ungarischen Thronfolgers Franz Ferdinand in Sarajevo. Die tieferen Ursachen lagen anderswo: starre Bündnissysteme, imperiale Rivalität, ein Wettrüsten und aggressiver Nationalismus. Binnen Wochen befanden sich die Großmächte Europas im Krieg.\n\nDie Westfront wurde rasch zum Albtraum des Grabenkriegs. Millionen Soldaten standen einander über dem Niemandsland gegenüber, getrennt durch Stacheldraht und Maschinengewehre. Allein die Schlacht an der Somme (1916) forderte über 1 Million Opfer. Neue Waffen — Giftgas, Panzer, Flugzeuge — machten den Krieg einzigartig schrecklich. Bis 1918 waren 20 Millionen tot, und vier große Reiche — das Osmanische, das Österreich-Ungarische, das Russische und das Deutsche — waren zusammengebrochen.",
      "Der Vertrag von Versailles (1919) demütigte Deutschland mit Kriegsschuld, Reparationen und Gebietsverlusten. Die Weltwirtschaftskrise (1929–1939) verwüstete die Volkswirtschaften weltweit und schuf fruchtbaren Boden für den Extremismus. Adolf Hitlers Nationalsozialisten stiegen 1933 in Deutschland zur Macht auf, mit Versprechungen nationaler Wiedergeburt, und gaben Juden und Kommunisten die Schuld an Deutschlands Nöten.\n\nHitler remilitarisierte das Rheinland, annektierte Österreich und riss die Tschechoslowakei an sich, während Britannien und Frankreich, vom Ersten Weltkrieg traumatisiert, eine Beschwichtigungspolitik betrieben. Als Deutschland am 1. September 1939 Polen überfiel, erklärten Britannien und Frankreich endlich den Krieg. Der Zweite Weltkrieg hatte begonnen.",
      "Der Zweite Weltkrieg war der zerstörerischste Konflikt der Menschheitsgeschichte. Deutschland eroberte bis 1941 den größten Teil Europas; Japan riss weite Teile Asiens und des Pazifiks an sich. Deutschlands Überfall auf die Sowjetunion im Juni 1941 eröffnete den größten Landfeldzug der Geschichte. Amerika trat nach Japans Angriff auf Pearl Harbor im Dezember 1941 in den Krieg ein.\n\nDas NS-Regime ermordete systematisch 6 Millionen Juden, dazu Roma, Behinderte, Homosexuelle und politische Gegner — den Holocaust. Alliierte Truppen befreiten 1945 die Vernichtungslager. Deutschland kapitulierte im Mai 1945; Japan kapitulierte im August, nachdem die Vereinigten Staaten Atombomben auf Hiroshima und Nagasaki abgeworfen hatten. Zwischen 70 und 85 Millionen Menschen waren gestorben — der blutigste Konflikt der Menschheitsgeschichte.",
      "Die 1920er Jahre begannen verheißungsvoll mit relativer wirtschaftlicher Erholung und kultureller Lebendigkeit (die „Goldenen Zwanziger“, Jazz, moderne Kunst). Doch strukturelle Schwächen — Kriegsschulden, Reparationen, spekulative Finanzen — machten die Weltwirtschaft fragil. Als der amerikanische Aktienmarkt im Oktober 1929 zusammenbrach und der Kredit einfror, weitete sich der Schock zur Weltwirtschaftskrise. Bis 1932 erreichte die Arbeitslosigkeit in Amerika 25 %, in Deutschland fast 30 %.\n\nDie Krise zerstörte das Vertrauen in die liberale Demokratie und den Kapitalismus. In Italien hatte Mussolinis faschistische Bewegung bereits 1922 die Macht ergriffen und nationale Größe und Ordnung versprochen. Hitlers Nationalsozialisten nutzten die deutsche Arbeitslosigkeit und den Antisemitismus, um 1933 an die Macht zu gelangen. Stalins Sowjetunion erzwang durch Terror die Zwangskollektivierung und Industrialisierung und tötete Millionen. Die demokratischen Mächte — vom Ersten Weltkrieg traumatisiert, zerstritten und beschwichtigend — versäumten es, der Ausbreitung des Faschismus entgegenzutreten, bis es gefährlich spät war.",
      "Das katastrophale Ausmaß des Zweiten Weltkriegs überzeugte die alliierten Führer, dass eine neue internationale Architektur unerlässlich sei. Die 1945 gegründeten Vereinten Nationen schufen Foren zur friedlichen Konfliktlösung. Die Allgemeine Erklärung der Menschenrechte (1948) setzte internationale Normen. Die Nürnberger Prozesse (1945–46) begründeten das Präzedenz einer internationalen strafrechtlichen Verantwortung für Kriegsverbrechen und Verbrechen gegen die Menschlichkeit.\n\nDie Atombomben, die den Pazifikkrieg beendeten, läuteten einen grundlegenden Wandel im Wesen des Krieges ein — die Menschheit besaß nun Waffen, die imstande waren, die Zivilisation zu vernichten. Der Marshallplan pumpte 13 Milliarden Dollar in den Wiederaufbau Westeuropas und schuf starke, mit Amerika verbündete Demokratien. Die NATO begründete ein Militärbündnis gegen die sowjetische Expansion. Diese Ordnungen erwiesen sich als bemerkenswert dauerhaft: Die internationale Nachkriegsordnung blieb, obwohl herausgefordert, bis ins 21. Jahrhundert der Rahmen des Weltgeschehens.",
    ],
    fr: [
      "La Première Guerre mondiale éclata en août 1914, déclenchée par l’assassinat de l’archiduc austro-hongrois François-Ferdinand à Sarajevo. Les causes profondes étaient plus vastes : systèmes d’alliances rigides, rivalité impériale, course aux armements et nationalisme agressif. En quelques semaines, les grandes puissances d’Europe étaient en guerre.\n\nLe front de l’Ouest devint vite un cauchemar de guerre de tranchées. Des millions de soldats se faisaient face de part et d’autre du no man’s land, séparés par les barbelés et les mitrailleuses. La seule bataille de la Somme (1916) fit plus d’un million de victimes. De nouvelles armes — gaz toxiques, chars, avions — rendirent la guerre uniquement terrible. En 1918, 20 millions de morts, et quatre grands empires — ottoman, austro-hongrois, russe et allemand — s’étaient effondrés.",
      "Le traité de Versailles (1919) humilia l’Allemagne par la culpabilité de guerre, les réparations et les pertes territoriales. La Grande Dépression (1929–1939) dévasta les économies du monde entier, créant un terrain fertile pour l’extrémisme. Le parti nazi d’Adolf Hitler accéda au pouvoir en Allemagne en 1933 sur des promesses de renaissance nationale, imputant aux juifs et aux communistes les malheurs de l’Allemagne.\n\nHitler remilitarisa la Rhénanie, annexa l’Autriche et s’empara de la Tchécoslovaquie tandis que la Grande-Bretagne et la France, traumatisées par la Première Guerre mondiale, pratiquaient l’apaisement. Lorsque l’Allemagne envahit la Pologne le 1ᵉʳ septembre 1939, la Grande-Bretagne et la France déclarèrent enfin la guerre. La Seconde Guerre mondiale avait commencé.",
      "La Seconde Guerre mondiale fut le conflit le plus destructeur de l’histoire humaine. L’Allemagne conquit la majeure partie de l’Europe en 1941 ; le Japon s’empara de vastes pans de l’Asie et du Pacifique. L’invasion de l’Union soviétique par l’Allemagne en juin 1941 ouvrit la plus grande campagne terrestre de l’histoire. L’Amérique entra en guerre après l’attaque japonaise sur Pearl Harbor en décembre 1941.\n\nLe régime nazi assassina systématiquement 6 millions de juifs, ainsi que des Roms, des personnes handicapées, des homosexuels et des opposants politiques — la Shoah. Les forces alliées libérèrent les camps de la mort en 1945. L’Allemagne capitula en mai 1945 ; le Japon capitula en août après que les États-Unis eurent largué des bombes atomiques sur Hiroshima et Nagasaki. Entre 70 et 85 millions de personnes étaient mortes — le conflit le plus sanglant de l’histoire humaine.",
      "Les années 1920 débutèrent de façon prometteuse, avec une reprise économique relative et une vitalité culturelle (les « Années folles », le jazz, l’art moderniste). Mais des faiblesses structurelles — dettes de guerre, réparations, finance spéculative — rendaient l’économie mondiale fragile. Quand la Bourse américaine s’effondra en octobre 1929 et que le crédit se figea, le choc dégénéra en Grande Dépression. En 1932, le chômage atteignait 25 % en Amérique, près de 30 % en Allemagne.\n\nLa Dépression détruisit la confiance dans la démocratie libérale et le capitalisme. En Italie, le mouvement fasciste de Mussolini avait déjà pris le pouvoir en 1922, promettant gloire nationale et ordre. Le parti nazi d’Hitler exploita le chômage allemand et l’antisémitisme pour conquérir le pouvoir en 1933. L’Union soviétique de Staline imposa la collectivisation forcée et l’industrialisation par la terreur, tuant des millions de personnes. Les puissances démocratiques — traumatisées par la Première Guerre mondiale, divisées et conciliantes — ne surent affronter l’expansion du fascisme qu’à une heure dangereusement tardive.",
      "L’ampleur catastrophique de la Seconde Guerre mondiale convainquit les dirigeants alliés qu’une nouvelle architecture internationale était essentielle. L’Organisation des Nations unies, établie en 1945, créa des forums de résolution pacifique des conflits. La Déclaration universelle des droits de l’homme (1948) fixa des normes internationales. Les procès de Nuremberg (1945–46) établirent le précédent d’une responsabilité pénale internationale pour crimes de guerre et crimes contre l’humanité.\n\nLes bombes atomiques qui mirent fin à la guerre du Pacifique inaugurèrent un bouleversement fondamental de la nature du conflit — l’humanité possédait désormais des armes capables de détruire la civilisation. Le plan Marshall déversa 13 milliards de dollars dans la reconstruction de l’Europe occidentale, créant de solides démocraties alliées de l’Amérique. L’OTAN établit une alliance militaire contre l’expansion soviétique. Ces dispositifs se révélèrent remarquablement durables : l’ordre international de l’après-guerre, bien que contesté, demeura le cadre des affaires mondiales jusqu’au XXIᵉ siècle.",
    ],
  },
  'modern-03': {
    de: [
      "Als der Zweite Weltkrieg endete, zerbrach das Bündnis zwischen dem demokratischen Westen (angeführt von den USA) und dem kommunistischen Osten (angeführt von der UdSSR). 1947 sprach Winston Churchill von einem „Eisernen Vorhang“, der Europa teilte. Die USA antworteten mit der Truman-Doktrin und dem Marshallplan — Milliarden Dollar zum Wiederaufbau Westeuropas und zur Eindämmung des Kommunismus.\n\nDie Sowjetunion entwickelte 1949 ihre eigene Atombombe; China wurde im selben Jahr kommunistisch. Beide Supermächte bauten gewaltige Nukleararsenale auf, die imstande waren, die Zivilisation zu vernichten. Die Kubakrise von 1962 — als sowjetische Raketen auf Kuba entdeckt wurden — brachte die Welt bis auf Stunden an einen Atomkrieg heran, ehe eine angespannte diplomatische Lösung gefunden wurde.",
      "Der Kalte Krieg wurde indirekt durch Stellvertreterkriege und den Wettstreit um Einfluss in der Dritten Welt ausgetragen. Der Koreakrieg (1950–53) endete in einer Pattsituation ungefähr am 38. Breitengrad. Der Vietnamkrieg zog ein massives amerikanisches Engagement nach sich; die USA zogen sich schließlich nach dem Verlust von 58 000 Soldaten zurück, und Vietnam wurde unter kommunistischer Herrschaft wiedervereinigt.\n\nBeide Supermächte wetteiferten im Weltraum — dem „Wettlauf ins All“. Die UdSSR startete 1957 den Sputnik und brachte 1961 Juri Gagarin in die Umlaufbahn; die USA antworteten 1969 mit der Mondlandung. Der wissenschaftliche und technologische Wettbewerb trieb beispiellose Fortschritte voran.",
      "Während die Supermächte wetteiferten, brachen die europäischen Reiche zusammen. Indien erlangte 1947 die Unabhängigkeit; Dutzende afrikanischer Nationen wurden in den 1950er und 1960er Jahren unabhängig. Der Prozess verlief oft gewaltsam — Frankreich führte brutale Kriege in Vietnam und Algerien. Der Wettbewerb des Kalten Krieges verkomplizierte die Entkolonialisierung, da jede Supermacht in den neu unabhängigen Nationen bevorzugte Fraktionen unterstützte.\n\nIn den 1980er Jahren stagnierte die sowjetische Wirtschaft. Michail Gorbatschows Reformen (Glasnost und Perestroika) entfesselten Kräfte, die er nicht beherrschen konnte. Die osteuropäischen Nationen brachen sich 1989 los — die Berliner Mauer fiel am 9. November. 1991 löste sich die Sowjetunion selbst in 15 unabhängige Staaten auf. Der Kalte Krieg war vorbei.",
      "Im Oktober 1962 kam die Welt einem Atomkrieg näher als zu jedem anderen Zeitpunkt der Geschichte. Der sowjetische Führer Chruschtschow hatte heimlich Atomraketen auf Kuba stationiert — 150 Kilometer von Florida entfernt —, die die meisten amerikanischen Städte treffen konnten. Als amerikanische U-2-Spionageflugzeuge die Raketenstellungen fotografierten, stand Präsident Kennedy vor einer quälenden Wahl zwischen Luftangriffen, Seeblockade oder Kapitulation.\n\nKennedy wählte eine seeseitige „Quarantäne“ und stellte Chruschtschow am 22. Oktober öffentlich zur Rede. Dreizehn Tage lang dampften sowjetische Schiffe auf die amerikanische Blockade zu, während die Nuklearstreitkräfte beider Seiten in höchster Alarmbereitschaft standen. Diplomatische Hinterkanäle brachten schließlich eine Lösung: Die Sowjets zogen ihre Raketen ab im Austausch gegen ein amerikanisches Versprechen, Kuba nicht zu überfallen, und ein geheimes Abkommen, amerikanische Jupiter-Raketen aus der Türkei abzuziehen. Die Krise ernüchterte beide Führer zutiefst; binnen Monaten wurde ein direkter „heißer Draht“ zwischen dem Weißen Haus und dem Kreml eingerichtet.",
      "Nach der Kubakrise bemühten sich beide Supermächte, ihren Wettbewerb behutsamer zu steuern. Entspannung — die Lockerung der Spannungen durch Verhandlung — prägte die späten 1960er und die 1970er Jahre. Die Verträge zur Begrenzung strategischer Waffen (SALT I, 1972) deckelten die Zahl der Atomsprengköpfe. Nixons historischer Besuch in China 1972 eröffnete die Beziehungen der USA zu Peking neu und verkomplizierte die strategischen Berechnungen der Sowjets.\n\nDoch die Entspannung geriet ins Wanken, als die Sowjetunion 1979 in Afghanistan einmarschierte. Reagans konfrontativer Kurs in den 1980er Jahren beschleunigte die sowjetische Wirtschaftskrise. Gorbatschows Perestroika und Glasnost entfesselten Forderungen nach Freiheit, denen das System nicht nachkommen konnte. Polens Solidarność-Bewegung, Ungarns Grenzöffnung, Ostdeutschlands Massenexodus — all das gipfelte im Fall der Berliner Mauer. Bis Dezember 1991 hatte sich die Sowjetunion aufgelöst. Das Ende des Kalten Krieges schien eine neue Weltordnung des demokratischen Friedens anzukündigen — eine Hoffnung, die die folgenden Jahrzehnte der Regionalkriege und der Großmachtrivalität verkomplizieren sollten.",
    ],
    fr: [
      "À la fin de la Seconde Guerre mondiale, l’alliance entre l’Ouest démocratique (mené par les États-Unis) et l’Est communiste (mené par l’URSS) se fractura. Dès 1947, Winston Churchill évoqua un « rideau de fer » divisant l’Europe. Les États-Unis répondirent par la doctrine Truman et le plan Marshall — des milliards de dollars pour reconstruire l’Europe occidentale et endiguer le communisme.\n\nL’Union soviétique mit au point sa propre bombe atomique en 1949 ; la Chine devint communiste la même année. Les deux superpuissances constituèrent de vastes arsenaux nucléaires capables de détruire la civilisation. La crise des missiles de Cuba de 1962 — lorsque des missiles soviétiques furent découverts à Cuba — approcha le monde à quelques heures d’une guerre nucléaire avant une tendue résolution diplomatique.",
      "La guerre froide se livra indirectement, par guerres par procuration et compétition d’influence dans le monde en développement. La guerre de Corée (1950–53) se termina par une impasse autour du 38ᵉ parallèle. La guerre du Vietnam entraîna un engagement américain massif ; les États-Unis finirent par se retirer après avoir perdu 58 000 soldats, et le Vietnam fut réunifié sous un régime communiste.\n\nLes deux superpuissances rivalisèrent dans l’espace — la « course à l’espace ». L’URSS lança Spoutnik en 1957 et mit Youri Gagarine en orbite en 1961 ; les États-Unis répliquèrent en se posant sur la Lune en 1969. La compétition scientifique et technologique entraîna des progrès sans précédent.",
      "Tandis que les superpuissances rivalisaient, les empires européens s’effondraient. L’Inde obtint son indépendance en 1947 ; des dizaines de nations africaines devinrent indépendantes dans les années 1950 et 1960. Le processus fut souvent violent — la France mena des guerres brutales au Vietnam et en Algérie. La compétition de la guerre froide compliqua la décolonisation, chaque superpuissance soutenant des factions favorites dans les nations nouvellement indépendantes.\n\nDans les années 1980, l’économie soviétique stagnait. Les réformes de Mikhaïl Gorbatchev (glasnost et perestroïka) libérèrent des forces qu’il ne put maîtriser. Les nations d’Europe de l’Est s’affranchirent en 1989 — le mur de Berlin tomba le 9 novembre. En 1991, l’Union soviétique elle-même se dissolut en 15 États indépendants. La guerre froide était terminée.",
      "En octobre 1962, le monde s’approcha d’une guerre nucléaire plus qu’à tout autre moment de l’histoire. Le dirigeant soviétique Khrouchtchev avait secrètement placé des missiles nucléaires à Cuba — à 150 kilomètres de la Floride — capables de frapper la plupart des villes américaines. Quand des avions espions américains U-2 photographièrent les sites de missiles, le président Kennedy affronta un choix déchirant entre frappes aériennes, blocus naval ou capitulation.\n\nKennedy choisit une « quarantaine » navale et affronta publiquement Khrouchtchev le 22 octobre. Pendant treize jours, les navires soviétiques firent route vers le blocus américain tandis que les forces nucléaires des deux camps se tenaient en alerte maximale. Des canaux diplomatiques discrets produisirent finalement une résolution : les Soviétiques retirèrent leurs missiles en échange d’un engagement américain de ne pas envahir Cuba et d’un accord secret de retirer les missiles américains Jupiter de Turquie. La crise dégrisa profondément les deux dirigeants ; un « téléphone rouge » direct entre la Maison-Blanche et le Kremlin fut établi en quelques mois.",
      "Après la crise de Cuba, les deux superpuissances cherchèrent à gérer leur rivalité plus prudemment. La détente — le relâchement des tensions par la négociation — caractérisa la fin des années 1960 et les années 1970. Les traités de limitation des armements stratégiques (SALT I, 1972) plafonnèrent le nombre d’ogives nucléaires. La visite historique de Nixon en Chine en 1972 rouvrit les relations des États-Unis avec Pékin et compliqua les calculs stratégiques soviétiques.\n\nMais la détente vacilla quand l’Union soviétique envahit l’Afghanistan en 1979. L’approche conflictuelle de Reagan dans les années 1980 accéléra la crise économique soviétique. La perestroïka et la glasnost de Gorbatchev libérèrent des exigences de liberté que le système ne put satisfaire. Le mouvement Solidarność en Pologne, l’ouverture de la frontière hongroise, l’exode massif d’Allemagne de l’Est — tout culmina dans la chute du mur de Berlin. En décembre 1991, l’Union soviétique s’était dissoute. La fin de la guerre froide sembla annoncer un nouvel ordre mondial de paix démocratique — un espoir que les décennies suivantes de guerres régionales et de rivalité entre grandes puissances allaient compliquer.",
    ],
  },
  'modern-04': {
    de: [
      "Die Erfindung des Personalcomputers (1970er Jahre), des World Wide Web (1989) und des Smartphones (2007) veränderte die menschliche Gesellschaft ebenso tiefgreifend wie die Druckerpresse oder die Dampfmaschine. Bis 2023 hatten über 5 Milliarden Menschen Internetzugang. Information, Kultur und Handel fließen nun in Echtzeit rund um den Globus.\n\nSoziale Medien verliehen dem Einzelnen eine beispiellose Fähigkeit zu kommunizieren und sich zu organisieren und befeuerten politische Bewegungen vom Arabischen Frühling bis zu weltweiten Klimastreiks. Doch die digitale Revolution ermöglichte auch Desinformation, Massenüberwachung und die Ballung von Macht bei einer Handvoll Technologiekonzerne.",
      "Der Zusammenbruch der Sowjetunion und Chinas Öffnung zu den Märkten lösten die größte wirtschaftliche Globalisierung der Geschichte aus. Handelsschranken fielen; Lieferketten spannten sich über Kontinente. Hunderte Millionen entkamen der Armut — besonders in China und Indien. Die Welthandelsorganisation (1995) schuf Regeln für den globalen Handel.\n\nDoch die Vorteile der Globalisierung waren ungleich verteilt. Fertigungsarbeitsplätze wanderten aus den reichen Nationen in Niedriglohnländer. Die Ungleichheit stieg innerhalb vieler Nationen, während sie zwischen ihnen sank. Die Finanzkrise von 2008 — mit Ursprung in den amerikanischen Hypothekenmärkten — weitete sich zu einer weltweiten Rezession aus und zeigte, wie vernetzt und zerbrechlich die Weltwirtschaft geworden war.",
      "Die Anschläge vom 11. September 2001 durch al-Qaida töteten 3 000 Menschen und lösten zwei Jahrzehnte amerikanischen Militärengagements in Afghanistan und im Irak aus. Der Terrorismus wurde zu einem prägenden Sicherheitsanliegen des frühen 21. Jahrhunderts.\n\nDer Klimawandel — angetrieben durch die Treibhausgasemissionen der industriellen Zivilisation — ist die prägende Herausforderung unserer Zeit. Die globalen Temperaturen steigen, die Meeresspiegel klettern, und Extremwetterereignisse verschärfen sich. Der wissenschaftliche Konsens ist eindeutig, doch das politische Handeln ist zögerlich. Wie die Menschheit auf den Klimawandel reagiert, wird die Geschichte der kommenden Jahrhunderte mehr als jede andere Entscheidung prägen.",
      "Vielleicht hat keine Entwicklung mehr zur Umgestaltung der Welt des 21. Jahrhunderts beigetragen als Chinas wirtschaftlicher Aufstieg. Nach Deng Xiaopings ab 1978 einsetzenden Marktreformen wuchs China drei Jahrzehnte lang um fast 10 % jährlich — das schnellste anhaltende Wachstum der Menschheitsgeschichte. Hunderte Millionen wurden aus der Armut gehoben. Bis in die frühen 2020er Jahre kam Chinas Wirtschaft dem amerikanischen BIP nahe. Chinesische Investitionen reichten über die „Neue Seidenstraße“ nach Afrika, Asien und Lateinamerika.\n\nChinas Aufstieg widerlegte die Annahme der Zeit nach dem Kalten Krieg, die Globalisierung werde automatisch zu Demokratisierung führen. Die Kommunistische Partei Chinas behielt straffe politische Kontrolle, selbst während sie die Wirtschaft liberalisierte — und stellte ein Alternativmodell zum liberal-demokratischen Konsens vor Augen. Die Spannungen mit den Vereinigten Staaten über Handel, Technologie, Taiwan und das Südchinesische Meer verschärften sich in den 2010er und 2020er Jahren. Der Aufstieg Indiens, Russlands erneutes Streben nach Großmachtambitionen und die Schwächung internationaler Institutionen deuteten darauf hin, dass das 21. Jahrhundert multipolarer und umkämpfter sein würde, als es der Moment nach dem Kalten Krieg versprochen hatte.",
      "Die 2020er Jahre brachten mehrere zusammenlaufende Krisen, die die internationale Ordnung auf die Probe stellten. Die COVID-19-Pandemie (2020–2022) tötete über 7 Millionen Menschen und störte Volkswirtschaften weltweit, legte Verwundbarkeiten in den globalen Lieferketten offen und zeigte zugleich sowohl die Fähigkeit zu rascher wissenschaftlicher Reaktion — mRNA-Impfstoffe, in weniger als einem Jahr entwickelt — als auch die Zerbrechlichkeit internationaler Zusammenarbeit, wenn nationale Interessen kollidieren.\n\nDie künstliche Intelligenz trat als möglicherweise umwälzendste Technologie seit der industriellen Revolution hervor. Große Sprachmodelle zeigten Leistungen auf menschlichem Niveau über eine erstaunliche Bandbreite von Aufgaben und warfen tiefgreifende Fragen über die Zukunft von Arbeit, Kreativität, Wissen und das Verhältnis zwischen Mensch und Maschine auf. Unterdessen beschleunigte sich der Klimawandel weiter, während geopolitische Spannungen über Taiwan, die Ukraine und andere Brennpunkte die Beobachter daran erinnerten, dass ein Großmachtkonflikt eine reale Möglichkeit blieb. Die Entscheidungen, die die Menschheit in den kommenden Jahrzehnten über die Steuerung der KI, den Klimaschutz und die internationale Zusammenarbeit trifft, werden die Geschichte ebenso tiefgreifend prägen wie jedes in diesem Kurs behandelte Ereignis.",
    ],
    fr: [
      "L’invention de l’ordinateur personnel (années 1970), du World Wide Web (1989) et du smartphone (2007) transforma la société humaine aussi profondément que l’imprimerie ou la machine à vapeur. En 2023, plus de 5 milliards de personnes avaient accès à Internet. L’information, la culture et le commerce circulent désormais mondialement en temps réel.\n\nLes réseaux sociaux donnèrent aux individus une capacité inédite de communiquer et de s’organiser, alimentant des mouvements politiques du Printemps arabe aux grèves mondiales pour le climat. Mais la révolution numérique permit aussi la désinformation, la surveillance de masse et la concentration du pouvoir entre les mains d’une poignée de sociétés technologiques.",
      "La chute de l’Union soviétique et l’ouverture de la Chine aux marchés déclenchèrent la plus grande mondialisation économique de l’histoire. Les barrières commerciales tombèrent ; les chaînes d’approvisionnement s’étirèrent à travers les continents. Des centaines de millions de personnes échappèrent à la pauvreté — surtout en Chine et en Inde. L’Organisation mondiale du commerce (1995) créa des règles pour le commerce mondial.\n\nMais les bénéfices de la mondialisation furent inégalement répartis. Les emplois manufacturiers migrèrent des nations riches vers des pays à bas salaires. L’inégalité augmenta au sein de nombreuses nations alors même qu’elle diminuait entre elles. La crise financière de 2008 — née des marchés hypothécaires américains — dégénéra en récession mondiale, montrant à quel point l’économie du monde était devenue interconnectée et fragile.",
      "Les attentats du 11 septembre 2001 perpétrés par al-Qaïda tuèrent 3 000 personnes et déclenchèrent deux décennies d’engagement militaire américain en Afghanistan et en Irak. Le terrorisme devint une préoccupation sécuritaire déterminante du début du XXIᵉ siècle.\n\nLe changement climatique — provoqué par les émissions de gaz à effet de serre de la civilisation industrielle — est le défi déterminant de notre époque. Les températures mondiales s’élèvent, le niveau des mers monte, et les phénomènes météorologiques extrêmes s’intensifient. Le consensus scientifique est sans équivoque, pourtant l’action politique tarde. La manière dont l’humanité répondra au changement climatique façonnera l’histoire des siècles à venir plus que toute autre décision.",
      "Aucun développement n’a peut-être plus remodelé le monde du XXIᵉ siècle que l’essor économique de la Chine. À la suite des réformes de marché de Deng Xiaoping amorcées en 1978, la Chine crût de près de 10 % par an pendant trois décennies — la croissance soutenue la plus rapide de l’histoire humaine. Des centaines de millions de personnes furent sorties de la pauvreté. Au début des années 2020, l’économie chinoise rivalisait avec le PIB américain. Les investissements chinois s’étendirent à travers l’Afrique, l’Asie et l’Amérique latine via les « Nouvelles Routes de la soie ».\n\nL’essor de la Chine ébranla l’hypothèse de l’après-guerre froide selon laquelle la mondialisation produirait automatiquement la démocratisation. Le Parti communiste chinois maintint un contrôle politique étroit tout en libéralisant l’économie — démontrant un modèle alternatif au consensus démocratique libéral. Les tensions avec les États-Unis sur le commerce, la technologie, Taïwan et la mer de Chine méridionale s’intensifièrent au cours des années 2010 et 2020. L’émergence de l’Inde, la réaffirmation des ambitions de grande puissance de la Russie et l’affaiblissement des institutions internationales laissaient présager que le XXIᵉ siècle serait plus multipolaire et disputé que ne l’avait promis le moment de l’après-guerre froide.",
      "Les années 2020 apportèrent plusieurs crises convergentes qui mirent à l’épreuve l’ordre international. La pandémie de COVID-19 (2020–2022) tua plus de 7 millions de personnes et perturba les économies du monde entier, exposant les vulnérabilités des chaînes d’approvisionnement mondiales tout en démontrant à la fois la capacité de réponse scientifique rapide — des vaccins à ARNm mis au point en moins d’un an — et la fragilité de la coopération internationale lorsque les intérêts nationaux s’opposent.\n\nL’intelligence artificielle émergea comme peut-être la technologie la plus transformatrice depuis la révolution industrielle. Les grands modèles de langage démontrèrent des performances de niveau humain sur un éventail stupéfiant de tâches, soulevant de profondes questions sur l’avenir du travail, de la créativité, du savoir et de la relation entre les humains et les machines. Pendant ce temps, le changement climatique continua de s’accélérer tandis que les tensions géopolitiques autour de Taïwan, de l’Ukraine et d’autres points chauds rappelaient aux observateurs que le conflit entre grandes puissances restait une possibilité réelle. Les choix que fera l’humanité dans les décennies à venir sur la gouvernance de l’IA, l’action climatique et la coopération internationale façonneront l’histoire aussi profondément que tout événement abordé dans ce cours.",
    ],
  },
  'modern-05': {
    de: [
      "Das späte 19. Jahrhundert sah die europäischen Mächte eine beispiellose Expansion über Afrika, Asien und den Pazifik entfalten. Getrieben vom Bedürfnis des Industriekapitalismus nach Rohstoffen und Märkten, vom nationalistischen Wettstreit zwischen den europäischen Staaten und von einer rassistischen Ideologie der „Zivilisation“, teilten die imperialen Mächte binnen einer Generation den größten Teil der Welt unter sich auf.\n\nTechnologische Überlegenheit machte die Eroberung möglich: dampfgetriebene Kanonenboote drangen in die Flusssysteme ein; Telegrafenkabel koordinierten Militäroperationen über Kontinente hinweg; das Maxim-Gewehr — das erste moderne Maschinengewehr der Welt — erlaubte kleinen europäischen Streitkräften, weit größere Heere zu besiegen. Chinin machte das afrikanische Landesinnere endlich für Europäer zugänglich, ohne den Massentod durch Malaria. Wie der Dichter Hilaire Belloc bissig zusammenfasste: „Was auch geschieht, wir haben / das Maxim-Gewehr, und sie haben es nicht.“",
      "Vor 1880 beschränkte sich die europäische Präsenz in Afrika weitgehend auf Handelsposten an der Küste. Dann, in einer atemberaubenden Spanne von 30 Jahren, wurde der gesamte Kontinent — außer Äthiopien und Liberia — kolonisiert. Die Berliner Konferenz von 1884–85, von Otto von Bismarck einberufen, legte die Regeln für diese Aufteilung fest. Vertreter von 14 europäischen und amerikanischen Nationen zogen Linien über die Karte Afrikas und schufen Grenzen, die ethnische Gruppen, Königreiche, Handelsnetze und die physische Geografie missachteten.\n\nBritannien erhielt den größten Anteil: Ägypten, Sudan, Nigeria, Ghana, Kenia, Uganda, Rhodesien (Simbabwe) und Südafrika. Frankreich beherrschte West- und Zentralafrika. Belgien erhielt den Kongo; Deutschland bekam Namibia, Tansania und Kamerun; Italien nahm Libyen und Somalia. Kein einziger afrikanischer Führer wurde befragt. Diese willkürlichen Grenzen wurden zu den unabhängigen Nationen des nachkolonialen Afrikas und schufen ethnische Spannungen und Konflikte, die bis heute fortdauern.",
      "Keine Kolonie veranschaulichte die Brutalität des Imperialismus besser als der Kongo-Freistaat, der von 1885 bis 1908 persönlich dem belgischen König Leopold II. gehörte. Leopold stellte seine Herrschaft als humanitäre Mission dar, „Zivilisation“ nach Zentralafrika zu bringen. In Wahrheit betrieb er einen Terrorstaat, darauf angelegt, maximalen Gewinn aus Kautschuk und Elfenbein zu ziehen.\n\nDie Kongolesen wurden gezwungen, Kautschuk nach Quoten zu ernten; das Verfehlen der Vorgaben wurde mit Verstümmelung bestraft — Soldaten hackten Arbeitern und deren Familienangehörigen die Hände ab, um zu beweisen, dass sie keine Kugeln vergeudet hatten. Millionen starben durch Gewalt, Hunger und Krankheit. Eine internationale humanitäre Kampagne, angeführt vom Journalisten E. D. Morel und dem humanitären Aktivisten Roger Casement, deckte die Gräuel auf und schuf eine der ersten internationalen Menschenrechtskampagnen der Geschichte. Unter Druck übergab Leopold den Kongo 1908 der belgischen Staatskontrolle — doch bis dahin waren schätzungsweise 10 Millionen Menschen gestorben.",
      "Die Afrikaner waren keine passiven Opfer der Eroberung. Über den ganzen Kontinent leisteten Königreiche, Konföderationen und Völker erbitterten Widerstand. Das Zulu-Königreich im südlichen Afrika, geführt von König Cetshwayo, fügte den Briten in der Schlacht von Isandlwana im Januar 1879 die schwerste britische Militärniederlage in Afrika zu und tötete an einem einzigen Nachmittag über 1 300 britische und verbündete Soldaten. Obwohl die Briten sich letztlich durchsetzten, erzwang der Zulu-Widerstand einen weit kostspieligeren und vorsichtigeren Feldzug als erwartet.\n\nÄthiopiens Kaiser Menelik II. erreichte, was keinem anderen afrikanischen Führer gelang: Er besiegte ein europäisches Kolonialheer vollständig. In der Schlacht von Adua im März 1896 vernichteten äthiopische Truppen — über 100 000 Mann stark und mit modernen, in Frankreich und Russland gekauften Waffen ausgerüstet — ein italienisches Heer von 17 000 Mann. Italien war gezwungen, im darauffolgenden Vertrag von Addis Abeba die Unabhängigkeit Äthiopiens anzuerkennen. Adua wurde zum Sinnbild afrikanischen Widerstands und Stolzes und beflügelte über Generationen hinweg Unabhängigkeitsbewegungen auf dem ganzen Kontinent.",
      "Um 1914 beherrschten die europäischen Reiche 84 % der Landfläche der Welt. Die Folgen waren tiefgreifend und dauerhaft. Die imperiale Ausbeutung übertrug gewaltigen Reichtum nach Europa — die britische Industrialisierung beruhte auf indischer Baumwolle, karibischem Zucker und afrikanischen Bodenschätzen. Zugleich wurden die kolonialen Volkswirtschaften verzerrt, um europäischen Bedürfnissen statt lokaler Entwicklung zu dienen, was strukturelle Abhängigkeiten schuf, die lange nach der Unabhängigkeit fortbestanden.\n\nDer Imperialismus formte Kulturen, Sprachen und Identitäten rund um den Globus um. Christliche Missionare verbreiteten europäische Bildung und Religion und unterdrückten zugleich einheimische Glaubensvorstellungen und Sprachen. Die Kolonialverwaltungen schufen neue ethnische Hierarchien und bevorzugten oft eine Gruppe gegenüber einer anderen, um die Herrschaft zu erleichtern — eine Teile-und-herrsche-Strategie mit tödlichen langfristigen Folgen. Die Welle der afrikanischen und asiatischen Unabhängigkeit nach dem Zweiten Weltkrieg (die meisten afrikanischen Nationen wurden zwischen 1956 und 1975 unabhängig) hinterließ Nationen, die mit willkürlichen Grenzen, wirtschaftlicher Unterentwicklung und kultureller Entwurzelung ringen, die das unmittelbare Erbe des imperialen Zeitalters sind. Den Imperialismus zu verstehen ist unerlässlich, um die moderne Welt zu verstehen.",
    ],
    fr: [
      "La fin du XIXᵉ siècle vit les puissances européennes lancer une expansion sans précédent à travers l’Afrique, l’Asie et le Pacifique. Poussées par le besoin de matières premières et de marchés du capitalisme industriel, par la rivalité nationaliste entre États européens et par une idéologie raciste de la « civilisation », les puissances impériales se partagèrent l’essentiel du monde en une génération.\n\nLa supériorité technologique rendit la conquête possible : des canonnières à vapeur pénétrèrent les réseaux fluviaux ; des câbles télégraphiques coordonnèrent les opérations militaires à travers les continents ; la mitrailleuse Maxim — la première mitrailleuse moderne du monde — permit à de petites forces européennes de défaire des armées bien plus nombreuses. La quinine rendit enfin l’intérieur africain accessible aux Européens sans hécatombe par le paludisme. Comme le résuma sardoniquement le poète Hilaire Belloc : « Quoi qu’il arrive, nous avons / la mitrailleuse Maxim, et eux non. »",
      "Avant 1880, la présence européenne en Afrique se bornait largement à des comptoirs côtiers. Puis, en une saisissante période de 30 ans, le continent tout entier — hormis l’Éthiopie et le Liberia — fut colonisé. La conférence de Berlin de 1884–85, convoquée par Otto von Bismarck, établit les règles de ce partage. Les représentants de 14 nations européennes et américaines tracèrent des lignes sur la carte de l’Afrique, créant des frontières qui ignoraient groupes ethniques, royaumes, réseaux commerciaux et géographie physique.\n\nLa Grande-Bretagne obtint la plus grande part : Égypte, Soudan, Nigeria, Ghana, Kenya, Ouganda, Rhodésie (Zimbabwe) et Afrique du Sud. La France domina l’Afrique de l’Ouest et centrale. La Belgique reçut le Congo ; l’Allemagne obtint la Namibie, la Tanzanie et le Cameroun ; l’Italie prit la Libye et la Somalie. Pas un seul dirigeant africain ne fut consulté. Ces frontières arbitraires devinrent les nations indépendantes de l’Afrique postcoloniale, engendrant des tensions et des conflits ethniques qui persistent jusqu’à aujourd’hui.",
      "Aucune colonie n’illustra mieux la brutalité de l’impérialisme que l’État indépendant du Congo, propriété personnelle du roi belge Léopold II de 1885 à 1908. Léopold présentait son règne comme une mission humanitaire visant à apporter la « civilisation » à l’Afrique centrale. En réalité, il dirigeait un État de terreur conçu pour extraire un profit maximal de caoutchouc et d’ivoire.\n\nLes Congolais étaient forcés de récolter le caoutchouc sous quotas ; l’échec à atteindre les objectifs était puni par mutilation — les soldats coupaient les mains des ouvriers et de leurs familles pour prouver qu’ils n’avaient pas gaspillé de balles. Des millions de personnes moururent de violence, de famine et de maladie. Une campagne humanitaire internationale menée par le journaliste E. D. Morel et l’activiste humanitaire Roger Casement révéla les atrocités, créant l’une des premières campagnes internationales pour les droits humains de l’histoire. Sous la pression, Léopold transféra le Congo au contrôle de l’État belge en 1908 — mais d’ici là, environ 10 millions de personnes étaient mortes.",
      "Les Africains ne furent pas des victimes passives de la conquête. À travers le continent, royaumes, confédérations et peuples opposèrent une résistance farouche. Le royaume zoulou d’Afrique australe, mené par le roi Cetshwayo, infligea aux Britanniques leur pire défaite militaire en Afrique à la bataille d’Isandlwana en janvier 1879, tuant plus de 1 300 soldats britanniques et alliés en un seul après-midi. Bien que les Britanniques l’emportassent finalement, la résistance zouloue imposa une campagne bien plus coûteuse et prudente que prévu.\n\nL’empereur d’Éthiopie Ménélik II accomplit ce qu’aucun autre dirigeant africain ne réussit : il défit purement et simplement une armée coloniale européenne. À la bataille d’Adoua en mars 1896, les forces éthiopiennes — fortes de plus de 100 000 hommes et équipées d’armes modernes achetées à la France et à la Russie — anéantirent une armée italienne de 17 000 hommes. L’Italie fut contrainte de reconnaître l’indépendance éthiopienne dans le traité d’Addis-Abeba qui suivit. Adoua devint un symbole de résistance et de fierté africaines, inspirant les mouvements d’indépendance à travers le continent pendant des générations.",
      "Vers 1914, les empires européens contrôlaient 84 % de la surface terrestre du monde. Les conséquences furent profondes et durables. L’extraction impériale transféra d’immenses richesses vers l’Europe — l’industrialisation britannique dépendait du coton indien, du sucre caribéen et des minéraux africains. Dans le même temps, les économies coloniales furent distordues pour servir les besoins européens plutôt que le développement local, créant des dépendances structurelles qui persistèrent longtemps après l’indépendance.\n\nL’impérialisme remodela cultures, langues et identités à travers le globe. Les missionnaires chrétiens répandirent l’éducation et la religion européennes tout en réprimant croyances et langues indigènes. Les administrations coloniales créèrent de nouvelles hiérarchies ethniques, favorisant souvent un groupe au détriment d’un autre pour faciliter le contrôle — une stratégie de division aux conséquences mortelles à long terme. La vague d’indépendances africaines et asiatiques après la Seconde Guerre mondiale (la plupart des nations africaines devinrent indépendantes entre 1956 et 1975) laissa des nations aux prises avec des frontières arbitraires, un sous-développement économique et une dislocation culturelle qui sont l’héritage direct de l’âge impérial. Comprendre l’impérialisme est essentiel pour comprendre le monde moderne.",
    ],
  },
  'modern-06': {
    de: [
      "Jugoslawien („Land der Südslawen“) entstand nach dem Ersten Weltkrieg und wurde nach dem Zweiten Weltkrieg als kommunistische Föderation unter Josip Broz Tito neu begründet. Titos charismatische Führung und die blockfreie Außenpolitik hielten ein Mosaik aus sechs Republiken — Slowenien, Kroatien, Bosnien-Herzegowina, Serbien, Montenegro und Mazedonien — sowie zwei autonomen Provinzen, dem Kosovo und der Vojvodina, zusammen. Diese Gebiete enthielten Serben, Kroaten, Bosniaken (bosnische Muslime), Slowenen, Mazedonier, Albaner, Ungarn und Dutzende kleinerer Gruppen, die verschiedene Sprachen sprachen und Orthodoxie, Katholizismus und Islam praktizierten.\n\nTito unterdrückte nationalistische Bewegungen rücksichtslos und hielt die Macht zwischen den Republiken im Gleichgewicht. Sein berühmter Ausspruch — „Ich habe drei Länder: eine Vergangenheit, eine Gegenwart, eine Zukunft“ — brachte die zerbrechliche Natur der jugoslawischen Einheit zum Ausdruck. Als Tito 1980 starb, begann das von ihm errichtete System sich aufzulösen. Die rotierende Präsidentschaft schuf ein politisches Vakuum; die wirtschaftliche Stagnation nährte Verbitterung; und nationalistische Politiker witterten Gelegenheit darin, uralte Missstände zu schüren, die Tito unterdrückt, aber nie gelöst hatte.",
      "Als der Kommunismus 1989–1991 in ganz Osteuropa zusammenbrach, strebten die jugoslawischen Republiken zur Unabhängigkeit. Serbien unter dem Nationalisten Slobodan Milošević suchte die serbische Vorherrschaft in einem Rest-Jugoslawien zu bewahren. Im Juni 1991 erklärten Slowenien und Kroatien gleichzeitig ihre Unabhängigkeit. Die Jugoslawische Volksarmee (JNA) marschierte im „Zehn-Tage-Krieg“ in Slowenien ein, zog sich jedoch zurück, als klar wurde, dass Sloweniens Lage — an Österreich und Italien grenzend, mit einer winzigen serbischen Minderheit — die Kontrolle unpraktikabel machte.\n\nKroatiens Fall war weit blutiger. Kroatien hatte eine bedeutende serbische Minderheit (12 %), und serbische Paramilitärs, von der JNA unterstützt, rissen die Kontrolle über die Region Krajina und andere serbisch dominierte Gebiete an sich. Gräueltaten wurden von beiden Seiten begangen. Die Stadt Vukovar wurde 87 Tage lang beschossen und vor ihrer Kapitulation im November 1991 praktisch zerstört — ein Vorbote der Schrecken, die in Bosnien kommen sollten. Die internationale Gemeinschaft, angeführt von Deutschland, erkannte im Januar 1992 die Unabhängigkeit Sloweniens und Kroatiens an, eine Entscheidung, die die Ausbreitung des Krieges nach Bosnien beschleunigte.",
      "Bosnien-Herzegowina war die ethnisch gemischteste der jugoslawischen Republiken: 1991 rund 44 % Bosniaken (Muslime), 31 % Serben und 17 % Kroaten. Als Bosnien im März 1992 die Unabhängigkeit erklärte, entfesselten die bosnischen Serben — von Serbien und der JNA unterstützt — sogleich einen Krieg, um Gebiet für einen serbischen Staat (Republika Srpska) herauszuschneiden. Die Belagerung von Sarajevo, die längste Belagerung einer Hauptstadt in der Geschichte der modernen Kriegsführung, begann im April 1992 und dauerte 44 Monate. Scharfschützenfeuer und Artillerie töteten über 11 000 Zivilisten in Sarajevo.\n\nDie bosnisch-serbische Armee unter General Ratko Mladić verfolgte eine Strategie der „ethnischen Säuberung“ — der Vertreibung oder Ermordung nichtserbischer Bevölkerungen, um ethnisch reine Gebiete zu schaffen. Konzentrationslager, systematische Vergewaltigung und Massenerschießungen erschütterten die Welt. Internationale Friedenstruppen (UNPROFOR) standen weitgehend hilflos daneben, ihr Mandat durch die Lähmung des UN-Sicherheitsrats begrenzt. Das Massaker von Srebrenica im Juli 1995, bei dem über 8 000 bosniakische Männer und Jungen in einer von der UN erklärten „Schutzzone“ ermordet wurden, war der schlimmste Völkermord in Europa seit dem Holocaust.",
      "Der Fall von Srebrenica im Juli 1995 steht als das katastrophalste Versagen internationaler Friedenssicherung in der Ära nach dem Kalten Krieg. Die Stadt im Osten Bosniens war 1993 zur UN-„Schutzzone“ erklärt worden und wurde von einem niederländischen UN-Bataillon (Dutchbat) geschützt. Als Mladićs Truppen Srebrenica am 11. Juli umzingelten und betraten, leisteten die niederländischen Friedenssoldaten — in der Unterzahl und unzureichend ausgerüstet — keinen Widerstand.\n\nBosniakische Männer und Jungen im Alter von 12 bis 77 Jahren wurden von Frauen und Kindern getrennt und in den folgenden Tagen zu Massenhinrichtungsstätten transportiert. Die Leichen wurden in Massengräbern verscharrt, dann exhumiert und in Sekundärgräbern erneut beigesetzt, um die Beweise zu verbergen. Der systematische Charakter der Tötungen — von der militärischen Führung organisiert, in koordinierter Weise an mehreren Stätten gleichzeitig ausgeführt — erfüllt die rechtliche Definition des Völkermords nach internationalem Recht. Der Internationale Gerichtshof bestätigte dies 2007. Niederländische Friedenssoldaten sahen zu, wie Familien getrennt wurden. Das Versagen verfolgte die Niederlande und führte 2002 schließlich zum Rücktritt des niederländischen Kabinetts. Srebrenica wurde zum Sinnbild für das Versagen der Menschheit, einen Völkermord trotz feierlicher Gelöbnisse nach dem Holocaust zu verhindern.",
      "Die Kriege pausierten vorübergehend mit dem Abkommen von Dayton vom November 1995, das den Bosnienkrieg beendete, indem es Bosnien zwischen der bosniakisch-kroatischen Föderation und der Republika Srpska aufteilte. Doch die Gewalt wanderte in den Kosovo — die serbische Provinz mit einer albanischen Mehrheit von 90 %. Nachdem friedlicher Widerstand gescheitert war, entfesselte die Kosovo-Befreiungsarmee (UÇK) 1996 einen Aufstand. Milošević reagierte mit brutalen Repressionen, die Tausende albanischer Zivilisten töteten und Hunderttausende vertrieben.\n\nIm März 1999 begann die NATO — ohne ein Mandat des UN-Sicherheitsrats (Russland und China hätten ein Veto eingelegt) — eine 78 Tage dauernde Luftkampagne gegen Serbien. Milošević zog sich aus dem Kosovo zurück; die NATO entsandte Friedenstruppen; und der Kosovo erklärte 2008 schließlich seine Unabhängigkeit, anerkannt von über 100 Ländern, jedoch nicht von Serbien oder Russland. Milošević wurde 1999 vom ICTY angeklagt — das erste amtierende Staatsoberhaupt, das wegen Kriegsverbrechen angeklagt wurde — und starb 2006 vor dem Urteil in Haft. Die Jugoslawienkriege töteten etwa 140 000 Menschen, vertrieben über 2 Millionen und hinterließen ein Erbe aus ethnischer Spaltung, Kriegsverbrechen und umstrittenen Grenzen, das den westlichen Balkan bis heute prägt.",
    ],
    fr: [
      "La Yougoslavie (« pays des Slaves du Sud ») fut créée après la Première Guerre mondiale et reconstituée après la Seconde en fédération communiste sous Josip Broz Tito. Le leadership charismatique de Tito et la politique étrangère non alignée maintinrent unie une mosaïque de six républiques — Slovénie, Croatie, Bosnie-Herzégovine, Serbie, Monténégro et Macédoine — et deux provinces autonomes, le Kosovo et la Voïvodine. Ces territoires abritaient Serbes, Croates, Bosniaques (musulmans de Bosnie), Slovènes, Macédoniens, Albanais, Hongrois et des dizaines de groupes plus petits, parlant des langues différentes et pratiquant l’orthodoxie, le catholicisme et l’islam.\n\nTito réprima impitoyablement les mouvements nationalistes et équilibra le pouvoir entre les républiques. Sa fameuse phrase — « J’ai trois pays : un passé, un présent, un avenir » — traduisait la nature fragile de l’unité yougoslave. À la mort de Tito en 1980, le système qu’il avait bâti commença à se défaire. La présidence tournante créa un vide politique ; la stagnation économique nourrit le ressentiment ; et des politiciens nationalistes virent l’occasion d’attiser des griefs anciens que Tito avait réprimés mais jamais résolus.",
      "Alors que le communisme s’effondrait à travers l’Europe de l’Est en 1989–1991, les républiques yougoslaves se dirigèrent vers l’indépendance. La Serbie, sous le nationaliste Slobodan Milošević, chercha à préserver la domination serbe au sein d’une Yougoslavie croupion. En juin 1991, la Slovénie et la Croatie déclarèrent simultanément leur indépendance. L’Armée populaire yougoslave (JNA) envahit la Slovénie lors de la « guerre des Dix Jours », mais se retira quand il devint clair que la géographie de la Slovénie — bordant l’Autriche et l’Italie, avec une minuscule minorité serbe — rendait le contrôle impraticable.\n\nLe cas croate fut bien plus sanglant. La Croatie comptait une importante minorité serbe (12 %), et des paramilitaires serbes, soutenus par la JNA, s’emparèrent de la région de la Krajina et d’autres zones à majorité serbe. Des atrocités furent commises des deux côtés. La ville de Vukovar fut bombardée pendant 87 jours et pratiquement détruite avant sa reddition en novembre 1991 — un avant-goût des horreurs à venir en Bosnie. La communauté internationale, menée par l’Allemagne, reconnut l’indépendance slovène et croate en janvier 1992, une décision qui accéléra l’extension de la guerre à la Bosnie.",
      "La Bosnie-Herzégovine était la plus mêlée ethniquement des républiques yougoslaves : environ 44 % de Bosniaques (musulmans), 31 % de Serbes et 17 % de Croates en 1991. Quand la Bosnie déclara son indépendance en mars 1992, les Serbes de Bosnie — soutenus par la Serbie et la JNA — lancèrent immédiatement une guerre pour tailler un territoire destiné à un État serbe (Republika Srpska). Le siège de Sarajevo, le plus long siège d’une capitale dans l’histoire de la guerre moderne, commença en avril 1992 et dura 44 mois. Les tirs de snipers et l’artillerie tuèrent plus de 11 000 civils à Sarajevo.\n\nL’armée serbe de Bosnie, sous le général Ratko Mladić, poursuivit une stratégie de « nettoyage ethnique » — expulsant ou massacrant les populations non serbes pour créer des territoires ethniquement purs. Camps de concentration, viols systématiques et exécutions de masse choquèrent le monde. Les casques bleus internationaux (FORPRONU) demeurèrent largement impuissants, leur mandat limité par la paralysie du Conseil de sécurité de l’ONU. Le massacre de Srebrenica de juillet 1995, où plus de 8 000 hommes et garçons bosniaques furent assassinés dans une « zone de sécurité » déclarée par l’ONU, fut le pire acte de génocide en Europe depuis la Shoah.",
      "La chute de Srebrenica en juillet 1995 demeure l’échec le plus catastrophique du maintien de la paix internationale de l’après-guerre froide. La ville de l’est de la Bosnie avait été déclarée « zone de sécurité » de l’ONU en 1993 et était protégée par un bataillon néerlandais de l’ONU (Dutchbat). Quand les forces de Mladić encerclèrent et entrèrent dans Srebrenica le 11 juillet, les casques bleus néerlandais — en infériorité numérique et sous-équipés — ne résistèrent pas.\n\nLes hommes et garçons bosniaques âgés de 12 à 77 ans furent séparés des femmes et des enfants et transportés vers des sites d’exécution de masse au cours des jours suivants. Les corps furent enterrés dans des fosses communes, puis exhumés et réinhumés dans des tombes secondaires pour dissimuler les preuves. La nature systématique des tueries — organisées par le commandement militaire, exécutées de façon coordonnée sur plusieurs sites simultanément — répond à la définition juridique du génocide en droit international. La Cour internationale de justice le confirma en 2007. Les casques bleus néerlandais regardèrent les familles se faire séparer. L’échec hanta les Pays-Bas, menant finalement à la démission du cabinet néerlandais en 2002. Srebrenica devint l’emblème de l’incapacité de l’humanité à prévenir un génocide malgré les serments solennels de l’après-Shoah.",
      "Les guerres s’interrompirent provisoirement avec les accords de Dayton de novembre 1995, qui mirent fin à la guerre de Bosnie en partageant la Bosnie entre la Fédération croato-bosniaque et la Republika Srpska. Mais la violence migra vers le Kosovo — la province serbe à majorité albanaise de 90 %. Après l’échec de la résistance pacifique, l’Armée de libération du Kosovo (UÇK) lança une insurrection en 1996. Milošević répondit par de brutales répressions qui tuèrent des milliers de civils albanais et en déplacèrent des centaines de milliers.\n\nEn mars 1999, l’OTAN — sans mandat du Conseil de sécurité de l’ONU (la Russie et la Chine auraient opposé leur veto) — entama une campagne aérienne contre la Serbie qui dura 78 jours. Milošević se retira du Kosovo ; l’OTAN déploya des casques bleus ; et le Kosovo déclara finalement son indépendance en 2008, reconnue par plus de 100 pays mais non par la Serbie ni la Russie. Milošević fut inculpé par le TPIY en 1999 — premier chef d’État en exercice accusé de crimes de guerre — et mourut en détention en 2006 avant le verdict. Les guerres de Yougoslavie tuèrent environ 140 000 personnes, en déplacèrent plus de 2 millions et laissèrent un héritage de division ethnique, de crimes de guerre et de frontières contestées qui définit encore les Balkans occidentaux.",
    ],
  },
  'modern-07': {
    de: [
      "Um die Wende zum 20. Jahrhundert war Mazedonien eine geografische und historische Region innerhalb des Osmanischen Reiches, die ungefähr das heutige Nordmazedonien, Nordgriechenland und Südwestbulgarien umfasste. Es war eines der ethnisch komplexesten Gebiete Europas: orthodoxe Christen, die griechische, bulgarische oder serbische Identität beanspruchen konnten, Muslime (Türken und slawische Konvertiten), Albaner, Juden, Aromunen und Roma lebten alle in einander überlappenden Gemeinschaften. Da das Osmanische Reich sich erkennbar im endgültigen Niedergang befand, begehrten Griechenland, Bulgarien und Serbien je Mazedonien, und jedes behauptete, seine Bevölkerung stehe ihm rechtmäßig zu.\n\nDer Wettstreit war nicht bloß militärisch, sondern kulturell und demografisch. Alle drei Länder entsandten Lehrer, Priester und Propagandisten nach Mazedonien, um die Herzen und Köpfe zu gewinnen. Schulen wurden eröffnet; die Dorfbevölkerungen wurden gedrängt, sich zum griechischen Patriarchat oder zum bulgarischen Exarchat zu bekennen. Das bulgarische Exarchat (gegründet 1870) war besonders wirksam und gewann viele mazedonische Dorfbewohner vom griechischen Patriarchat ab — ein demografischer Kampf mit tiefgreifenden politischen Folgen. Ein Mazedonier, der eine Patriarchatsschule besuchte, wurde in der Volkszählung zum „Griechen“; einer, der eine Exarchatsschule besuchte, zum „Bulgaren“.",
      "Die Innere Mazedonische Revolutionäre Organisation (IMRO), 1893 in Thessaloniki gegründet, erstrebte ein autonomes oder unabhängiges Mazedonien unter der Losung „Mazedonien den Mazedoniern“. Die IMRO ließ sich vom Vorbild der Befreiung Bulgariens leiten und schöpfte aus einer Tradition des Haiduken-Widerstands (Räuber-Rebellen). Ihre Netze reichten durch Dörfer und Diaspora-Gemeinschaften; sie erhob Steuern, hinrichtete Kollaborateure und organisierte Guerillabanden.\n\nAm 2. August 1903 — dem Fest des heiligen Elias (Ilinden) — entfesselte die IMRO einen großen Aufstand in ganz Mazedonien und in der angrenzenden Region Adrianopel. Die Republik von Kruševo, in der Stadt Kruševo ausgerufen, bestand zehn Tage, ehe osmanische Truppen sie niederschlugen. Der Aufstand scheiterte militärisch, wurde aber zum Gründungsmythos der mazedonischen nationalen Identität. Die brutale Niederschlagung durch die Osmanen — niedergebrannte Dörfer, niedergemetzelte Zivilisten, 70 000 Flüchtlinge — erzeugte internationales Mitgefühl und Druck zur Reform. Das Mürzsteger Abkommen zwischen Österreich-Ungarn und Russland im Oktober 1903 zwang Mazedonien ein Reformprogramm auf und erkannte damit die Instabilität der Region und die Unfähigkeit des Reiches an, sie allein zu bewältigen.",
      "Nach dem Scheitern des Ilinden-Aufstands begann eine neue Phase: ein organisierter Guerillakrieg zwischen griechischen und bulgarischen bewaffneten Banden um die Kontrolle über die mazedonische Bevölkerung. Griechenland entsandte erfahrene Offiziere und Irreguläre — die „Andartes“ —, um an der Seite des griechischen Patriarchatsklerus Patriarchatsdörfer zu schützen und Exarchatsdörfer, oft mit Gewalt, zur griechischen Zugehörigkeit zurückzuführen. Bulgariens IMRO entsandte zu demselben Zweck ihre eigenen „Komitadschi“-Banden.\n\nDer Kampf war von äußerster Gewalt gegen Zivilisten geprägt. Dörfer, die verdächtigt wurden, die Gegenseite zu begünstigen, wurden niedergebrannt; örtliche Führer wurden ermordet; Geistliche wurden getötet. Die mazedonischen Bauern gerieten zwischen die rivalisierenden Nationalismen, gezwungen, sich für eine Zugehörigkeit zu entscheiden — oder die Zugehörigkeit zu wechseln, wenn sich die militärischen Umstände änderten. Pavlos Melas, ein griechischer Armeeoffizier, der den griechischen Widerstand in Mazedonien vor seinem Tod 1904 organisierte, wurde zum Nationalhelden; Dutzende bulgarischer und griechischer Kämpfer wurden auf ähnliche Weise mythisiert. Dies war ein Krieg, geführt nicht nur um Gebiet, sondern um die Identität eines Volkes selbst, das nie ein geeintes Nationalbewusstsein besessen hatte.",
      "Der Mazedonische Kampf entfaltete sich vor dem Hintergrund des osmanischen Niedergangs und der Reform. Das Regime von Sultan Abdülhamid II. stand unter enormem Druck — von inneren Reformern, von europäischen Mächten, die den Schutz der christlichen Minderheiten forderten, und von nationalistischen Bewegungen auf dem ganzen Balkan. Mazedonien war ein Pulverfass: Das Mürzsteger Reformprogramm stellte europäische Offiziere an die Spitze der Neuordnung der osmanischen Gendarmerie, ein beispielloser Eingriff in die osmanische Souveränität.\n\nDie Jungtürkische Revolution vom Juli 1908 — angeführt von Offizieren des Komitees für Einheit und Fortschritt (CUP), von denen viele selbst in Mazedonien stationiert waren — veränderte die Lage über Nacht. Abdülhamid II. wurde gezwungen, die Verfassung wiederherzustellen und Wahlen auszurufen. Die Revolution einte vorübergehend alle Gemeinschaften Mazedoniens in euphorischer Feier: Muslime, Christen und Juden umarmten sich in den Straßen von Thessaloniki. Die griechischen und bulgarischen Banden ruhten kurzzeitig. Doch die konstitutionelle Flitterwochenzeit hielt nicht an; binnen Monaten flammte die zwischengemeinschaftliche Gewalt wieder auf, und der zugrunde liegende nationale Wettbewerb um Mazedonien war bloß ausgesetzt, nicht gelöst.",
      "Die mazedonische Frage wurde schließlich — teilweise und gewaltsam — durch die Balkankriege von 1912–1913 gelöst. Im Ersten Balkankrieg bildeten Griechenland, Bulgarien, Serbien und Montenegro den Balkanbund und griffen das Osmanische Reich an, das rasch zusammenbrach. Die osmanischen Truppen wurden binnen Wochen aus fast ihrem gesamten europäischen Gebiet verdrängt; Mazedonien fiel an die Verbündeten des Bundes. Im Zweiten Balkankrieg vom Juni 1913 zerstritten sich die Verbündeten über die Teilung Mazedoniens: Bulgarien griff Griechenland und Serbien gleichzeitig an, wurde aber besiegt und gezwungen, im Vertrag von Bukarest den größten Teil Mazedoniens an Griechenland und Serbien abzutreten.\n\nGriechenland erhielt den größten Anteil Mazedoniens (Ägäis-Mazedonien, einschließlich Thessaloniki). Serbien erhielt Vardar-Mazedonien (ungefähr das heutige Nordmazedonien). Bulgarien behielt nur einen kleinen östlichen Streifen (Pirin-Mazedonien). Die Teilung befriedigte niemanden vollständig. Für Griechenland wurde Thessaloniki — eine große Stadt mit jüdischer Mehrheit und gemischter Bevölkerung — nach einem Jahrhundert des Wettstreits zur zweiten Stadt des griechischen Staates. Für Bulgarien war der Verlust des größten Teils Mazedoniens ein nationales Trauma, das die bulgarische Außenpolitik durch beide Weltkriege trieb. Der Mazedonische Kampf endete somit nicht mit mazedonischer Autonomie, sondern mit Teilung — eine Mahnung, dass im Zeitalter konkurrierender Nationalismen kleine Völker selten ihr eigenes Schicksal bestimmten.",
    ],
    fr: [
      "Au tournant du XXᵉ siècle, la Macédoine était une région géographique et historique de l’Empire ottoman, couvrant à peu près l’actuelle Macédoine du Nord, le nord de la Grèce et le sud-ouest de la Bulgarie. C’était l’un des territoires les plus complexes ethniquement d’Europe : des chrétiens orthodoxes pouvant revendiquer une identité grecque, bulgare ou serbe, des musulmans (Turcs et convertis slaves), des Albanais, des juifs, des Valaques et des Roms vivaient tous dans des communautés enchevêtrées. L’Empire ottoman étant manifestement en déclin terminal, la Grèce, la Bulgarie et la Serbie convoitaient chacune la Macédoine, et chacune prétendait que sa population lui revenait de droit.\n\nLa compétition n’était pas seulement militaire mais culturelle et démographique. Les trois pays envoyèrent enseignants, prêtres et propagandistes en Macédoine pour gagner les cœurs et les esprits. Des écoles furent ouvertes ; les populations villageoises furent pressées de se déclarer fidèles au patriarcat grec ou à l’exarchat bulgare. L’exarchat bulgare (établi en 1870) fut particulièrement efficace, détachant de nombreux villageois macédoniens du patriarcat grec — une bataille démographique aux implications politiques profondes. Un Macédonien fréquentant une école du patriarcat devenait « grec » au recensement ; celui fréquentant une école de l’exarchat devenait « bulgare ».",
      "L’Organisation révolutionnaire intérieure macédonienne (ORIM), fondée à Thessalonique en 1893, visait une Macédoine autonome ou indépendante sous le slogan « La Macédoine aux Macédoniens ». L’ORIM s’inspirait du précédent de la libération de la Bulgarie et puisait dans une tradition de résistance haïdouk (bandit-rebelle). Ses réseaux s’étendaient à travers villages et communautés de la diaspora ; elle levait des impôts, exécutait les collaborateurs et organisait des bandes de guérilla.\n\nLe 2 août 1903 — jour de la fête de saint Élie (Ilinden) — l’ORIM déclencha un grand soulèvement à travers la Macédoine et la région voisine d’Andrinople. La République de Kruševo, proclamée dans la ville de Kruševo, dura dix jours avant que les forces ottomanes ne l’écrasent. Le soulèvement échoua militairement mais devint le mythe fondateur de l’identité nationale macédonienne. La répression brutale des Ottomans — villages incendiés, civils massacrés, 70 000 réfugiés — suscita une sympathie internationale et une pression en faveur de réformes. L’accord de Mürzsteg entre l’Autriche-Hongrie et la Russie, en octobre 1903, imposa un programme de réformes à la Macédoine, reconnaissant la volatilité de la région et l’incapacité de l’empire à la gérer seul.",
      "Après l’échec du soulèvement d’Ilinden, une nouvelle phase débuta : une guerre de guérilla organisée entre bandes armées grecques et bulgares pour le contrôle de la population macédonienne. La Grèce dépêcha des officiers expérimentés et des irréguliers — les « andartes » — pour œuvrer aux côtés du clergé du patriarcat grec, protégeant les villages du patriarcat et ramenant ceux de l’exarchat à l’allégeance grecque, souvent par la force. L’ORIM bulgare envoya ses propres bandes de « comitadji » dans le même but.\n\nLa lutte se caractérisa par une violence extrême contre les civils. Les villages soupçonnés de favoriser le camp adverse étaient incendiés ; les chefs locaux assassinés ; les membres du clergé tués. Les paysans macédoniens, pris entre des nationalismes rivaux, étaient contraints de choisir leurs allégeances — ou d’en changer selon l’évolution des circonstances militaires. Pavlos Melas, officier de l’armée grecque qui organisa la résistance grecque en Macédoine avant sa mort en 1904, devint un héros national ; des dizaines de combattants bulgares et grecs furent mythifiés de même. Ce fut une guerre menée non seulement pour un territoire mais pour l’identité même d’un peuple qui n’avait jamais eu de conscience nationale unifiée.",
      "La Lutte macédonienne se déroula sur fond de déclin et de réforme ottomans. Le régime du sultan Abdülhamid II subissait une pression énorme — de la part des réformateurs internes, des puissances européennes exigeant la protection des minorités chrétiennes et des mouvements nationalistes de tous les Balkans. La Macédoine était une poudrière : le programme de réforme de Mürzsteg plaça des officiers européens à la tête de la réorganisation de la gendarmerie ottomane, une intrusion sans précédent dans la souveraineté ottomane.\n\nLa révolution des Jeunes-Turcs de juillet 1908 — lancée par des officiers du Comité Union et Progrès (CUP), dont beaucoup étaient stationnés en Macédoine même — transforma la situation du jour au lendemain. Abdülhamid II fut contraint de rétablir la constitution et de convoquer des élections. La révolution unit temporairement toutes les communautés de Macédoine dans une célébration euphorique : musulmans, chrétiens et juifs s’étreignirent dans les rues de Thessalonique. Les bandes grecques et bulgares suspendirent brièvement les combats. Mais la lune de miel constitutionnelle ne dura pas ; en quelques mois, la violence intercommunautaire reprit, et la compétition nationale sous-jacente pour la Macédoine ne fut que suspendue, non résolue.",
      "La question macédonienne fut finalement résolue — partiellement et violemment — par les guerres balkaniques de 1912–1913. Lors de la première guerre balkanique, la Grèce, la Bulgarie, la Serbie et le Monténégro formèrent la Ligue balkanique et attaquèrent l’Empire ottoman, qui s’effondra rapidement. Les forces ottomanes furent chassées de la quasi-totalité de leur territoire européen en quelques semaines ; la Macédoine tomba aux mains des alliés de la Ligue. Lors de la seconde guerre balkanique de juin 1913, les alliés se brouillèrent sur le partage de la Macédoine : la Bulgarie attaqua la Grèce et la Serbie simultanément, mais fut défaite et contrainte de céder la majeure partie de la Macédoine à la Grèce et à la Serbie par le traité de Bucarest.\n\nLa Grèce obtint la plus grande part de la Macédoine (la Macédoine égéenne, y compris Thessalonique). La Serbie reçut la Macédoine du Vardar (à peu près l’actuelle Macédoine du Nord). La Bulgarie ne conserva qu’une étroite bande orientale (la Macédoine du Pirin). Le partage ne satisfit personne pleinement. Pour la Grèce, Thessalonique — grande ville à majorité juive et à population mêlée — devint la deuxième ville de l’État grec après un siècle de rivalité. Pour la Bulgarie, la perte de la majeure partie de la Macédoine fut un traumatisme national qui orienta la politique étrangère bulgare à travers les deux guerres mondiales. La Lutte macédonienne ne s’acheva donc pas par l’autonomie macédonienne mais par le partage — un rappel qu’à l’âge des nationalismes concurrents, les petits peuples maîtrisaient rarement leur propre destin.",
    ],
  },
  'modern-08': {
    de: [
      "Anfang 1917 wankte das Russische Reich: zwei Millionen tote Soldaten im Weltkrieg, hungernde Städte, der Zar persönlich für jedes Versagen verantwortlich gemacht. Im Februar (März nach westlichem Kalender) schwollen Brotunruhen in Petrograd zu einer allgemeinen Meuterei an, und Nikolaus II. dankte ab — drei Jahrhunderte Romanow-Herrschaft endeten in einer Woche. Eine liberale Provisorische Regierung teilte sich die unbequeme Macht mit Arbeiter- und Soldatenräten: den Sowjets.\n\nDie verhängnisvolle Entscheidung der Regierung war es, den Krieg fortzusetzen. Lenin, aus dem Exil zurückgekehrt, bot das einzige Programm, das zählte: „Frieden, Land und Brot“ und „Alle Macht den Sowjets“. In der Nacht des 25. Oktober (7. November) besetzten die bolschewistischen Roten Garden die Brücken, Bahnhöfe und schließlich fast widerstandslos das Winterpalais. Der erste sozialistische Staat der Welt hatte mit einem nahezu unblutigen Umsturz begonnen — das Blut kam danach.",
      "Die Bolschewiki erkauften den Frieden mit Deutschland in Brest-Litowsk (1918) um den Preis eines Drittels der Bevölkerung des Reiches — und kämpften dann ums Überleben gegen die Weißen: zaristische Generäle, Kosaken, verratene Sozialisten und Interventionstruppen aus Britannien, Frankreich, Japan und den Vereinigten Staaten. Trotzki baute die Rote Armee aus dem Nichts zu fünf Millionen Mann auf und bereiste ihre Fronten in einem Panzerzug.\n\nIndem sie das industrielle Zentrum gegen zerstrittene Feinde hielten, siegten die Roten bis 1922 — über eine Landschaft aus Hunger und Typhus, die vielleicht zehn Millionen getötet hatte. In jenem Dezember wurde die Union der Sozialistischen Sowjetrepubliken ausgerufen. Der „Kriegskommunismus“ wich kurzzeitig den Marktkompromissen der Neuen Ökonomischen Politik, und als Lenin 1924 starb, begann der Kampf um seine Nachfolge.",
      "Josef Stalin, der Generalsekretär der Partei, überlistete jeden Rivalen — Trotzki wurde verbannt und später mit einem Eispickel in Mexiko ermordet — und herrschte ab 1928 allein. Seine Revolution von oben kollektivierte das Land und Getreide der Bauern mit Gewalt und brach den Widerstand durch Deportationen und herbeigeführten Hunger: Millionen verhungerten 1932–33, am schrecklichsten in der Ukraine (der Holodomor).\n\nDieselben Pläne bauten die Hochöfen von Magnitogorsk, die Moskauer Metro und ganze Industrien aus dem Nichts — die UdSSR wurde binnen eines Jahrzehnts zur Industriemacht. Dann wandte sich der Terror nach innen: Die Säuberungen von 1936–38 verschlangen alte Bolschewiki in inszenierten Schauprozessen, erschossen die meisten hohen Offiziere der Roten Armee und schickten Millionen in die Gulag-Arbeitslager. Stalins UdSSR trat in den Zweiten Weltkrieg ein, nachdem sie bereits Krieg gegen sich selbst geführt hatte.",
      "Die Sowjetunion trug die erdrückende Last des NS-Krieges — vielleicht 27 Millionen Tote — und ging als Supermacht mit ihrer Armee an der Elbe daraus hervor. Vier Jahrzehnte lang beherrschte sie die Hälfte Europas durch den Warschauer Pakt, wetteiferte mit Amerika Sprengkopf um Sprengkopf und brachte den ersten Satelliten (Sputnik, 1957) und den ersten Menschen (Juri Gagarin, 1961) ins All.\n\nDoch die Kommandowirtschaft, die Raketen bauen konnte, konnte die Läden nicht füllen. Gorbatschows Reformen — Glasnost (Offenheit) und Perestroika (Umbau) —, die das System retten sollten, entfesselten stattdessen jede unterdrückte Kraft in ihm. Die Berliner Mauer fiel 1989; die unterworfenen Nationen gingen; und am 26. Dezember 1991 löste sich die UdSSR selbst auf. Das sowjetische Jahrhundert — seine Befreiungen und seine Schrecken, seine Siege und sein Gulag — bleibt die tiefste Narbe und schärfste Lehre des zwanzigsten Jahrhunderts.",
      "Am 26. April 1986 explodierte der Reaktor Nr. 4 des Kernkraftwerks Tschernobyl in der sowjetischen Ukraine während eines misslungenen Sicherheitstests und schleuderte radioaktiven Niederschlag über Europa. Der erste Instinkt des Staates war Schweigen: Die Mai-Parade in Kiew fand statt, während Kinder unter der Wolke marschierten, und die Welt erfuhr von der Katastrophe durch schwedische Strahlungsmessgeräte. Hunderttausende „Liquidatoren“ wurden mit Schaufeln und Hubschraubern gegen den brennenden Kern geworfen. Für Gorbatschow wurde Tschernobyl zum leibhaftigen Argument für Glasnost — der Beweis, dass ein auf Geheimhaltung gebautes System seine eigene Technik nicht beherrschen konnte. Er nannte es später „vielleicht die eigentliche Ursache des Zusammenbruchs der Sowjetunion fünf Jahre später“: der Augenblick, in dem das Schweigen des Staates sichtbar tödlicher wurde als die Wahrheit.",
    ],
    fr: [
      "Au début de 1917, l’Empire russe fléchissait : deux millions de soldats morts dans la guerre mondiale, des villes affamées, le tsar personnellement tenu pour responsable de chaque échec. En février (mars, selon le calendrier occidental), des émeutes du pain à Petrograd enflèrent en mutinerie générale, et Nicolas II abdiqua — trois siècles de règne des Romanov prirent fin en une semaine. Un gouvernement provisoire libéral partagea un pouvoir malaisé avec les conseils d’ouvriers et de soldats : les soviets.\n\nLa décision fatale du gouvernement fut de continuer la guerre. Lénine, revenu d’exil, offrit le seul programme qui comptait : « Paix, terre et pain » et « Tout le pouvoir aux soviets ». Dans la nuit du 25 octobre (7 novembre), les Gardes rouges bolcheviks s’emparèrent des ponts, des gares et enfin du Palais d’Hiver presque sans résistance. Le premier État socialiste du monde avait commencé par un coup d’État presque sans effusion de sang — le sang vint après.",
      "Les bolcheviks achetèrent la paix avec l’Allemagne à Brest-Litovsk (1918) au prix d’un tiers de la population de l’empire — puis luttèrent pour leur survie contre les Blancs : généraux tsaristes, cosaques, socialistes qu’ils avaient trahis, et forces d’intervention de Grande-Bretagne, de France, du Japon et des États-Unis. Trotski bâtit l’Armée rouge à partir de rien pour en faire cinq millions d’hommes, parcourant ses fronts dans un train blindé.\n\nTenant le centre industriel face à des ennemis divisés, les Rouges l’emportèrent en 1922 — sur un paysage de famine et de typhus qui avait tué peut-être dix millions de personnes. En décembre, l’Union des républiques socialistes soviétiques fut proclamée. Le « communisme de guerre » céda brièvement la place aux compromis de marché de la Nouvelle Politique économique, et lorsque Lénine mourut en 1924, la lutte pour sa succession commença.",
      "Joseph Staline, secrétaire général du parti, déjoua chaque rival — Trotski exilé puis assassiné d’un coup de piolet au Mexique — et régna seul à partir de 1928. Sa révolution par le haut collectivisa par la force la terre et le grain de la paysannerie, brisant la résistance par les déportations et une famine provoquée : des millions de personnes moururent de faim en 1932–33, le plus terriblement en Ukraine (l’Holodomor).\n\nLes mêmes plans bâtirent les hauts fourneaux de Magnitogorsk, le métro de Moscou et des industries entières à partir de rien — l’URSS devint une puissance industrielle en une décennie. Puis la terreur se retourna vers l’intérieur : les purges de 1936–38 dévorèrent les vieux bolcheviks dans des procès-spectacles scénarisés, fusillèrent la plupart des officiers supérieurs de l’Armée rouge et envoyèrent des millions de personnes dans les camps de travail du Goulag. L’URSS de Staline entra dans la Seconde Guerre mondiale après s’être déjà fait la guerre à elle-même.",
      "L’Union soviétique porta le poids écrasant de la guerre nazie — peut-être 27 millions de morts — et en sortit superpuissance, son armée sur l’Elbe. Pendant quatre décennies, elle gouverna la moitié de l’Europe par le pacte de Varsovie, égala l’Amérique ogive pour ogive, et mit le premier satellite (Spoutnik, 1957) et le premier humain (Youri Gagarine, 1961) dans l’espace.\n\nMais l’économie planifiée qui pouvait construire des fusées ne pouvait remplir les magasins. Les réformes de Gorbatchev — la glasnost (transparence) et la perestroïka (restructuration) —, censées sauver le système, libérèrent au contraire toutes les forces réprimées en son sein. Le mur de Berlin tomba en 1989 ; les nations captives partirent ; et le 26 décembre 1991, l’URSS se dissolut elle-même. Le siècle soviétique — ses émancipations et ses terreurs, ses victoires et son Goulag — demeure la cicatrice la plus profonde et la leçon la plus tranchante du vingtième siècle.",
      "Le 26 avril 1986, le réacteur nº 4 de la centrale nucléaire de Tchernobyl, en Ukraine soviétique, explosa lors d’un test de sécurité bâclé, projetant des retombées radioactives à travers l’Europe. Le premier réflexe de l’État fut le silence : le défilé du 1ᵉʳ mai à Kiev eut lieu tandis que des enfants marchaient sous le panache, et le monde apprit la catastrophe par les détecteurs de radiation suédois. Des centaines de milliers de « liquidateurs » furent jetés contre le cœur en feu avec des pelles et des hélicoptères. Pour Gorbatchev, Tchernobyl devint l’argument de la glasnost incarné — la preuve qu’un système bâti sur le secret ne pouvait maîtriser sa propre technologie. Il l’appela plus tard « peut-être la véritable cause de l’effondrement de l’Union soviétique cinq ans plus tard » : le moment où le silence de l’État devint visiblement plus meurtrier que la vérité.",
    ],
  },
  'modern-09': {
    de: [
      "Um 1900 beherrschte Britannien rund 300 Millionen Inder mit einem Beamtenapparat von etwa tausend britischen Amtsträgern — eine Herrschaft, die auf indischen Soldaten, indischen Steuern und sorgsam gepflegter Spaltung ruhte. Indien finanzierte Britanniens Kriege und kaufte seine Baumwolle; Hungersnöte töteten Millionen, während die Getreideausfuhren weitergingen. Eine englisch gebildete indische Elite, die 1885 den Indischen Nationalkongress gründete, ersuchte zunächst höflich um eine Stimme.\n\nDer Erste Weltkrieg änderte die Temperatur: Eine Million Inder diente, und statt der versprochenen Selbstregierung erhielt Indien Kriegsrechtsbefugnisse. Im April 1919 feuerten in Jallianwala Bagh in Amritsar die Truppen von General Dyer 1 650 Schuss in eine eingeschlossene, unbewaffnete Menge. Das Massaker — und Britanniens laue Reaktion darauf — überzeugte eine Generation, dass die moralischen Ansprüche des Reiches hohl waren.",
      "Mohandas Gandhi kehrte 1915 aus Südafrika zurück, wo er eine neue Waffe geschmiedet hatte: Satyagraha, „Wahrheitskraft“ — diszipliniertes, offen angekündigtes, gewaltloses Gesetzesbrechen, das die Strafe annimmt und damit die Gewalt des Staates gegen dessen eigene Legitimität wendet. Er verwandelte den Kongress aus einem Klub von Anwälten in eine Massenbewegung von Millionen und sich selbst in den „Mahatma“ — große Seele —, gekleidet in das selbstgesponnene Tuch, das ganz Indien anstelle der Importe aus Lancashire weben sollte.\n\nSein Genie galt den Symbolen. Als er 1930 aufgerufen war, gegen das britische Salzmonopol zu protestieren, wanderte er 380 km zum Meer bei Dandi, mit einem anschwellenden Strom von Anhängern, und hob eine Handvoll salzigen Schlamms auf — und machte damit augenblicklich jeden Inder zum Verbrecher, der Meerwasser verdunsten ließ, was Millionen prompt taten. Sechzigtausend kamen ins Gefängnis, Gandhi unter ihnen, und Wochenschauen trugen das Schauspiel imperialer Polizisten, die reglose Demonstranten niederknüppelten, in jedes Kino der Erde.",
      "Als Britannien 1939 im Namen Indiens den Krieg erklärte, ohne einen einzigen Inder zu befragen, legte der Kongress seine Provinzregierungen nieder; 1942 rief Gandhi die „Quit India“-Bewegung aus, und die gesamte Führung verbrachte den Krieg im Gefängnis. Unterdessen verhärtete Muhammad Ali Jinnahs Muslimliga — aus Furcht vor einem dauerhaften Minderheitenstatus unter einer hindu-mehrheitlichen Demokratie — ihre Forderung nach einem eigenen Staat: Pakistan.\n\nBritannien ging siegreich und bankrott aus dem Krieg hervor, seine indische Armee nicht länger verlässlich, seine Öffentlichkeit unwillig, Indien mit Gewalt zu halten. Der letzte Vizekönig, Lord Mountbatten, zog die Machtübergabe auf den 15. August 1947 vor und gab einem britischen Juristen, Cyril Radcliffe — der zuvor nie indischen Boden betreten hatte —, fünf Wochen Zeit, die Grenzen der Teilung durch den Punjab und Bengalen zu ziehen.",
      "„Zum Schlag der Mitternachtsstunde, wenn die Welt schläft, wird Indien zu Leben und Freiheit erwachen“, sagte Nehru zur Verfassunggebenden Versammlung. Doch die Freiheit kam gepaart mit der Katastrophe: Als die Radcliffe-Linie verkündet wurde, lösten sich Punjab und Bengalen in gemeinschaftliches Gemetzel auf. Etwa 14 Millionen Menschen flohen in beide Richtungen — die größte Migration der Geschichte —, und Hunderttausende, vielleicht mehr als eine Million, wurden getötet.\n\nGandhi weigerte sich zu feiern und fastete im von Unruhen zerrissenen Kalkutta, um die Mörder zum Frieden zu beschämen. Am 30. Januar 1948 wurde er von einem Hindu-Nationalisten ermordet, der ihn für zu großzügig gegenüber den Muslimen hielt. Was ihn überdauerte, ist das Zeitalter der Entkolonialisierung, das er mehr als jeder andere in Gang setzte: Binnen zweier Jahrzehnte war das Imperium — die ordnende Tatsache der modernen Welt — am Ende, und seine Methoden waren auf Martin Luther King Jr., Nelson Mandela und jede Bewegung seither übergegangen, die die Waffe des disziplinierten gewaltlosen Widerstands gewählt hat.",
      "Die erste große Tat des freien Indiens war es, sich selbst ein Regelwerk zu schreiben — und der Mann, der die Ausarbeitung leitete, war B. R. Ambedkar, geboren als „unberührbarer“ Dalit, als Kind verwehrt, im eigenen Klassenzimmer zu sitzen, der sich zu Doktortiteln aus Columbia und der LSE emporgekämpft hatte. Die am 26. Januar 1950 angenommene Verfassung ist die längste der Welt: Sie schaffte die Unberührbarkeit ab, verbürgte die Gleichheit vor dem Gesetz, gab jedem Erwachsenen — Mann und Frau, in einem weitgehend analphabetischen Land — vom ersten Tag an das Wahlrecht und schuf fördernde Quoten für die von der Kaste zermalmten Gemeinschaften. Ambedkar warnte die Versammlung, dass politische Gleichheit ohne soziale und wirtschaftliche Gleichheit die Demokratie zu „einer Deckschicht auf indischem Boden“ machen würde. Fünfundsiebzig Jahre der größten Demokratie der Welt sind zu einem großen Teil eine Auseinandersetzung mit diesem Satz gewesen.",
    ],
    fr: [
      "Vers 1900, la Grande-Bretagne gouvernait quelque 300 millions d’Indiens avec une fonction publique d’environ un millier de fonctionnaires britanniques — un contrôle reposant sur des soldats indiens, des impôts indiens et une division soigneusement cultivée. L’Inde finançait les guerres de la Grande-Bretagne et achetait son coton ; les famines tuaient des millions de personnes tandis que les exportations de céréales continuaient. Une élite indienne éduquée à l’anglaise, fondant le Congrès national indien en 1885, adressa d’abord de polies pétitions pour obtenir une voix.\n\nLa Première Guerre mondiale changea la température : un million d’Indiens servirent, et au lieu de l’autogouvernement promis, l’Inde reçut des pouvoirs de loi martiale. En avril 1919, à Jallianwala Bagh, à Amritsar, les troupes du général Dyer tirèrent 1 650 cartouches dans une foule désarmée et prise au piège. Le massacre — et la réponse tiède de la Grande-Bretagne — convainquit une génération que les prétentions morales de l’empire étaient creuses.",
      "Mohandas Gandhi revint d’Afrique du Sud en 1915, y ayant forgé une arme nouvelle : le satyagraha, « force de la vérité » — une désobéissance disciplinée, ouvertement annoncée et non violente, qui accepte le châtiment et retourne ainsi la violence de l’État contre sa propre légitimité. Il transforma le Congrès, d’un club d’avocats, en un mouvement de masse de millions de personnes, et lui-même en « Mahatma » — grande âme —, vêtu de l’étoffe filée à la main qu’il demandait à toute l’Inde de tisser à la place des importations du Lancashire.\n\nSon génie tenait aux symboles. En 1930, sommé de protester contre le monopole britannique du sel, il marcha 380 km jusqu’à la mer à Dandi, avec un fleuve grandissant de partisans, et ramassa une poignée de boue salée — faisant instantanément un criminel de tout Indien qui évaporait l’eau de mer, ce que des millions firent aussitôt. Soixante mille personnes allèrent en prison, Gandhi parmi elles, et les actualités filmées portèrent le spectacle de la police impériale matraquant des manifestants immobiles dans tous les cinémas de la Terre.",
      "Lorsque la Grande-Bretagne déclara la guerre au nom de l’Inde en 1939 sans consulter un seul Indien, le Congrès démissionna de ses gouvernements provinciaux ; en 1942, Gandhi lança le mouvement « Quit India » et toute la direction passa la guerre en prison. Pendant ce temps, la Ligue musulmane de Muhammad Ali Jinnah — craignant un statut de minorité permanente sous une démocratie à majorité hindoue — durcit sa demande d’un État séparé : le Pakistan.\n\nLa Grande-Bretagne sortit de la guerre victorieuse et ruinée, son armée indienne n’étant plus fiable, son opinion publique peu disposée à tenir l’Inde par la force. Le dernier vice-roi, Lord Mountbatten, avança le transfert du pouvoir au 15 août 1947 et donna à un juriste britannique, Cyril Radcliffe — qui n’avait jamais auparavant posé le pied en Inde — cinq semaines pour tracer les frontières de la partition à travers le Pendjab et le Bengale.",
      "« Au douzième coup de minuit, tandis que le monde dort, l’Inde s’éveillera à la vie et à la liberté », déclara Nehru à l’Assemblée constituante. Mais la liberté vint jumelée à la catastrophe : à l’annonce de la ligne Radcliffe, le Pendjab et le Bengale sombrèrent dans un carnage communautaire. Quelque 14 millions de personnes fuirent dans les deux sens — la plus grande migration de l’histoire —, et des centaines de milliers, peut-être plus d’un million, furent tuées.\n\nGandhi refusa de célébrer, jeûnant dans Calcutta déchirée par les émeutes pour faire honte aux tueurs et les ramener à la paix. Le 30 janvier 1948, il fut assassiné par un nationaliste hindou qui le jugeait trop généreux envers les musulmans. Ce qui lui survécut, c’est l’âge de la décolonisation qu’il fit plus que quiconque pour amorcer : en deux décennies, l’empire — le fait organisateur du monde moderne — était fini, et ses méthodes étaient passées à Martin Luther King Jr., à Nelson Mandela et à tout mouvement depuis lors ayant choisi l’arme de la non-violence disciplinée.",
      "Le premier grand acte de l’Inde libre fut de se doter d’un règlement — et l’homme qui dirigea la rédaction fut B. R. Ambedkar, né « intouchable » dalit, interdit enfant de s’asseoir à l’intérieur de sa propre salle de classe, qui s’était frayé un chemin jusqu’à des doctorats de Columbia et de la LSE. La constitution adoptée le 26 janvier 1950 est la plus longue du monde : elle abolit l’intouchabilité, garantit l’égalité devant la loi, donna à chaque adulte — homme et femme, dans un pays largement analphabète — le droit de vote dès le premier jour, et institua des quotas de discrimination positive pour les communautés que la caste avait écrasées. Ambedkar avertit l’assemblée que l’égalité politique sans égalité sociale et économique maintiendrait la démocratie « comme un placage à la surface du sol indien ». Soixante-quinze ans de la plus grande démocratie du monde ont été, pour une large part, une discussion avec cette phrase.",
    ],
  },
};
